(window.GIM_TS=window.GIM_TS||{})["Zevachim.0"]={"from":0,"a":[["\u0003כל הזבחים\u0004 (מיני הקרבנות) \u0003שנזבחו\u0004 (נשחטו) \u0003שלא לשמן\u0004 שהקדיש בהמה לקרבן מסוג מסויים, ובזמן השחיטה התכוון לשם קרבן אחר — הרי הם \u0003כשרים\u0004 כשלעצמם, ואפשר להמשיך את סדר העבודה שלהם, ואף לאכול את בשרם אם הם מהקרבנות הנאכלים, \u0003אלא שלא עלו לבעלים לשם חובה,\u0004 והבעלים צריכים להביא קרבן אחר כדי למלא את חובתם. ודין זה הוא בכל הקרבנות, \u0003חוץ מן\u0004 קרבן \u0003הפסח והחטאת,\u0004 שאם נזבחו שלא לשמם הרי הם פסולים לגמרי. אלא שגם באלו יש הבדל, כי \u0003הפסח\u0004 פסול כשנשחט שלא לשמו. דווקא \u0003בזמנו\u0004 כלומר, בזמן שמצוה לשחוט אותו, בערב פסח אחר חצות היום, \u0003והחטאת בכל זמן.\u0004","\u0003ר' אליעזר אומר: אף האשם\u0004 פסול כשנשחט שלא לשמו, ולשיטתו צריך לשנות כאן: \u0003הפסח בזמנו, והחטאת והאשם בכל זמן. אמר ר' אליעזר\u0004 לנמק את דבריו: \u0003החטאת באה על חטא והאשם בא\u0004 גם הוא \u0003על חטא, מה חטאת פסולה שלא לשמה, אף האשם פסול שלא לשמו.\u0004","\u0003יוסי בן חוני אומר:\u0004 לא רק הפסח והחטאת פסולים כשנשחטו שלא לשמם, אלא גם קרבנות אחרים \u0003הנשחטין לשם פסח ולשם חטאת\u0004 — \u0003פסולין.\u0004","\u0003שמעון אחי עזריה אומר:\u0004 יש לחלק באופן זה, כל מיני הקרבנות אם \u0003שחטן לשם\u0004 קרבן שבמעלתו \u0003גבוה מהן\u0004 — \u0003כשרין,\u0004 שחטן \u0003לשם נמוך מהן\u0004 — \u0003פסולין.\u0004","\u0003כיצד? קדשי קדשים,\u0004 כגון חטאת ועולה, \u0003ששחטן לשם קדשים קלים,\u0004 כגון לשם שלמים — \u0003פסולין, קדשים קלים ששחטן לשם קדשי קדשים\u0004 — \u0003כשרין.\u0004 וכן בקדשים קלים עצמם יש דרגות שונות, \u0003הבכור והמעשר ששחטן לשם שלמים\u0004 — כיון ששלמים הם למעלה מהם — \u0003כשרין, שלמים ששחטן לשם בכור ולשם מעשר\u0004 — \u0003פסולין.\u0004","שנינו במשנתנו: כל הזבחים שנזבחו שלא לשמן כשרים אלא שלא עלו לבעלים לשם חובה. ושואלים: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 בלשון \u0003\"אלא שלא עלו\u0004 לבעלים לשם חובה\"? \u0003ליתני\u0004 \u0005[שישנה]\u0006 בקיצור: \u0003\"ולא עלו לבעלים לשם חובה\"!\u0004","ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 שכך יש לדייק: \u0003לבעלים הוא\u0004 ש\u0003לא עלו לשם חובה\u0004 וזה הפגם היחידי שבהם, \u0003אבל בקדושתייהו קיימי\u0004 \u0005[בקדושתם\u0006 הם \u0005עומדים]\u0006 \u0003ואסור לשנויי בהו\u0004 \u0005[לשנות בהם]\u0006 שינוי נוסף.","\u0003ו\u0004הוא \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: עולה ששחטה שלא לשמה\u0004 — \u0003אסור לזרוק דמה שלא לשמה.\u0004 ומנין דבר זה?","\u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה]\u0006 היא, \u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור מקרא]\u0006 מוכיח זאת. ומפרטים, \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה]:\u0006 וכי \u0003משום דשני\u0004 \u0005[ששינה]\u0006 \u0003בה\u0004 שינוי אחד, בשחיטה, \u0003כל הני\u0004 \u0003לישני\u0004 \u0005[אלה ישנה]\u0006 \u0003בה\u0004 \u0003וליזיל\u0004 \u0005[וילך]?\u0006 שאם עשה שלא כראוי אינו צריך להמשיך בכך.","\u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור מקרא]\u0006 מלמדנו זאת, שנאמר: \u0003\"מוצא שפתיך תשמר ועשית כאשר נדרת לה' אלהיך נדבה\u0004 אשר דברת בפיך\" (דברים כג, כד), ויש לתמוה: \u0003האי\u0004 \u0005[זו]\u0006 \u0003נדבה\u0004 היא?"],["הלוא \u0003נדר הוא,\u0004 שהרי נאמר \"כאשר נדרת\", ויש הבדל בין נדר לנדבה! \u0003אלא\u0004 כך צריך להבין: \u0003אם כמה שנדרת עשית\u0004 והבאת את הקרבן בכל פרטיו כמו שנדרת — \u0003יהא נדר\u0004 תצא בו ידי חובת הנדר, \u0003ואם לא\u0004 שלא עשית כמו שנדרת — \u0003נדבה\u0004 סתם \u0003יהא,\u0004 כאילו קרבן אחר הוא, ולא הקרבן שנתחייב בו בנדר.","\u0003ונדבה מי שרי לשנויי\u0004 \u0005[האם מותר לשנות]\u0006 \u0003בה\u0004 לעשותה לכתחילה לשם דבר אחר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב פפא: לא הוית גבן באורתא בתחומא\u0004 \u0005[היית אצלנו אמש בתחום]\u0006 המקום \u0003בי חרמך,\u0004 ולכן לא שמעת \u0003דרמי\u0004 \u0005[שהשליך]\u0006 \u0003רבא מילי מעלייתא אהדדי ושני להו\u0004 \u0005[דברים מעולים זה על זה,\u0006 הראה סתירה ביניהם, \u0005ותירץ אותם].\u0006","\u0003מאי מילי מעלייתא\u0004 \u0005[מה\u0006 הם \u0005הדברים המעולים\u0006 הללו\u0005]?\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כל הזבחים שנזבחו שלא לשמן\u0004 כשרים, אלא שלא עלו לבעלים לשם חובה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שנשחטו \u0003שלא לשמן\u0004 אלא לשם קרבן אחר, \u0003הא\u0004 \u0005[הרי]\u0006 אם שחטן \u0003סתמא\u0004 \u0005[סתם]\u0006 ולא פירש לשם מה — \u0003עלו נמי\u0004 \u0005[גם כן]\u0006 \u0003לבעלים לשם חובה, אלמא סתמא נמי כלשמן דמי\u0004 \u0005[מכאן ש\u0006דבר הנעשה \u0005סתם גם כן כמו לשמן\u0006 הוא \u0005נחשב].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0003]\u0004 ממה ששנינו במסכת גיטין: \u0003כל הגט שנכתב שלא לשם\u0004 ה\u0003אשה\u0004 המתגרשת בו — \u0003פסול,\u0004 משום שצריך להיכתב לשם האשה המתגרשת דווקא. ואילו בדין זה למדנו שגט שנכתב \u0003סתמא\u0004 \u0005[סתם]\u0006 שלא לשם אשה מסויימת \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול\u0004 (כאשר יבואר להלן)!","\u0003ושני\u0004 \u0005[ותירץ]\u0006 רבא כך: \u0003זבחים בסתם לשמן עומדין\u0004 לשם הקרבן שהוקדשו לו מתחילה, וצריך לעקור אותם משמם הראשון כדי שישתנה שמם, אבל \u0003אשה בסתמא לאו\u0004 \u0005[בסתם לא]\u0006 \u0003לגירושין עומדת,\u0004 ולכן צריך הגט להיכתב במכוון לשמה. ומבררים את שתי ההנחות שהניח רבא בענין זה.","ושואלים: \u0003וזבחים בסתמא\u0004 \u0005[בסתם]\u0006 \u0003כשירין מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו]:\u0006 \u0003כל הזבחים שנזבחו שלא לשמן כו'\u0004 לא עלו לבעלים לשם חובה, \u0003ולא קתני\u0004 \u0005[שנה\u0006 התנא\u0005]\u0006 בנוסח \u0003\"שלא נזבחו לשמן\",\u0004 שמשמעו — כל עוד לא נזבחו לשמן אינם עולים לבעלים — זו אינה ראיה, שהרי \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גט\u0004 שהוא פסול בסתם \u0003נמי הקתני\u0004 \u0005[גם כן הרי שנה]:\u0006 \u0003כל הגט שנכתב שלא לשם אשה\u0004 — \u0003פסול, ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"שלא נכתב לשם אשה\"\u0004 — \u0003פסול!\u0004 ואם כן, אי אפשר לדקדק כל כך מלשון זו.","\u0003אלא\u0004 תאמר כי הראיה שזבחים סתמם כשר \u0003מהא דתנן\u0004 \u0005[מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כיצד\u0004 הוא הזובח \u0003לשמן ושלא לשמן\u0004 שפוסל בקרבן הפסח ובחטאת — כגון ששחט אותו \u0003לשם פסח ולשם שלמים,\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר לשם פסח ולשם שלמים, הא\u0004 \u0005[הרי]\u0006 אם אמר \u0003לשם פסח וסתמא\u0004 \u0005[וסתם],\u0006 ולא פירש עוד — \u0003כשר, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003סתמן כלשמן דמי\u0004 \u0005[נחשב].\u0006","על כך יש להשיב: משם אין ראיה, \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם],\u0006 \u0003דאמר\u0004 \u0005[ש\u0006התנא \u0005אומר]:\u0006 \u0003כל העושה\u0004 דבר — \u0003על דעת ראשונה הוא עושה,\u0004 וכיון שפירש שבתחילה הוא עושה לשמו, אין להניח שהוא משנה דעתו!","\u0003אלא\u0004 נאמר כי \u0003מסיפא\u0004 \u0005[מהסוף]\u0006 של אותה משנה אפשר להוכיח, שנאמר שם: מהו \u0003שלא לשמן ולשמן\u0004 הפוסל בפסח וחטאת? כגון \u0003לשם שלמים ולשם פסח.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר לשם שלמים ולשם פסח, הא סתמא\u0004 \u0005[הרי סתם]\u0006 \u0003ו\u0004אחר כך \u0003לשם פסח\u0004 — \u0003כשר.\u0004","על כך יש להשיב: אף משם אין להוכיח, \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם],\u0006 \u0003דאמר\u0004 \u0005[ש\u0006התנא \u0005אומר]:\u0006 \u0003יוכיח סופו על תחילתו,\u0004 שאם בסוף נתכוון לשם פסח מן הסתם התכוון לכך אף בתחילה!","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לדחות באופן אחר: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 בתחילה \u0003לשמן ושלא לשמן,\u0004 ושם דווקא אם חשב שלא לשמן פסול (אבל בסתם — על דעת ראשונה הוא עושה) \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 באותו סגנון לשון \u0003שלא לשמן ולשמן,\u0004 אף שלהלכה גם בסתם ולשמן יהא פסול!","\u0003אלא מהא\u0004 \u0005[מ\u0006משנה \u0005זו]\u0006 אפשר להוכיח שקרבן כשר בסתם, ששנינו להלן: \u0003לשם ששה דברים הזבח\u0004 צריך שיהא \u0003נזבח\u0004 (נשחט): \u0003לשם זבח\u0004 לשם הקרבן המסויים שהוקדש לו (עולה, שלמים, וכו'), \u0003לשם זובח\u0004 לשם בעליו, \u0003לשם שם\u0004 שעושה אותו לשמו של הקדוש ברוך הוא, \u0003לשם אשים\u0004 שיעלה כקרבן על גבי המזבח, \u0003לשם ריח\u0004 שיקטירנו באופן שיעלה ריחו, \u0003לשם ניחוח\u0004 לשם נחת רוח לה'. \u0003והחטאת ואשם\u0004 — \u0003לשם חטא.\u0004","\u0003אמר ר' יוסי: אף מי שלא היה בלבו לשם אחת מכל אלו\u0004 ולא חשב עליהם כלל — הרי זה \u0003כשר, שתנאי בית דין הוא.\u0004 ומסבירים: \u0003אתנו\u0004 \u0005[התנו]\u0006 \u0003בית דין\u0004 ש\u0003לא לימא\u0004 \u0005[יאמר]\u0006 שהוא שוחט \u0003לשמו, דילמא אתי למימר\u0004 \u0005[שמא יבוא לומר]\u0006 שהוא שוחט \u0003שלא לשמו,\u0004 ולכן מוטב שלא יפרש כלל.","\u0003ואי סלקא דעתך סתמא\u0004 \u0005[ואם עולה על דעתך שבסתם]\u0006 הוא \u0003פסול,\u0004 וכי \u0003קיימי\u0004 \u0005[עומדים]\u0006 \u0003בית דין ומתני מילתא דמיפסיל ביה\u0004 \u0005[ומתנים דבר שייפסל בו]?\u0006 אלא ודאי מכאן הוכחה שהזבח כשר בסתם.","ושואלים עוד: \u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003גט דסתמא\u0004 \u0005[שסתמו]\u0006 \u0003פסול, מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו]\u0006 במשנה: \u0003היה עובר בשוק ושמע סופרים מקרין\u0004 (מקריאים) לתלמידיהם: \u0003\"איש פלוני גירש פלונית ממקום פלוני\", ואמר: זה שמי וזה שם אשתי,\u0004 וכיון שכתבתם אותו בשמות הללו אשתמש בו לגירושין, מכל מקום \u0003פסול לגרש בו.\u0004","ולכאורה הרי זה משום שלא נכתב לשם אותה האשה — יש לדחות: \u0003דילמא\u0004 \u0005[שמא]\u0006 שם הטעם הוא \u0003כ\u0004דברי \u0003רב פפא,\u0004 ש\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 \u0003בסופרים העשויין להתלמד עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ולא איכתוב\u0004 \u0005[נכתב]\u0006 הגט \u0003לשום כריתות\u0004 (לשם גירושין) \u0003כלל,\u0004 אלא נכתב רק כתרגיל כתיבה, ומשום כך הוא פסול!","\u0003אלא מהא\u0004 \u0005[מזו]\u0006 אפשר להוכיח, ממה ששנינו בהמשך אותה משנה:"],["\u0003יתר על כן, כתב לגרש את אשתו ונמלך\u0004 (התחרט) והחליט שלא לגרשה, \u0003מצאו בן עירו ואמר לו: שמי כשמך ושם אשתי כשם אשתך,\u0004 תן לי את הגט ואגרש בו את אשתי — \u0003פסול לגרש בו.\u0004","משמע שאם נכתב הגט בסתם, שלא לשם האשה המתגרשת, הרי הוא פסול למרות שנכתב לשם כריתות — גם משם אין ראיה, \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 \u0003דאינתיק ליה\u0004 \u0005[שנותק לו]\u0006 הגט הזה \u0003לשם גירושין\u0004 של \u0003ההוא,\u0004 ולכן אין אדם אחר יכול לגרש בו. אבל גט שנכתב בסתם — כשר, אם נכתב לשם כריתות!","\u0003אלא\u0004 נאמר כי למדנו דין זה \u0003מהא\u0004 \u0005[מזו]\u0006 ששנינו שם: \u0003יתר על כן, יש לו שתי נשים ששמותיהן שוות, כתב לגרש\u0004 בו \u0003את הגדולה\u0004 שביניהן — \u0003לא יגרש בו את הקטנה,\u0004 משמע שצריך לכתוב לשמה דווקא — גם זאת יש לדחות:","\u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 שאף על פי שנכתב לשמו של האיש המגרש, \u0003אינתיק ליה\u0004 \u0005[נותק לו]\u0006 הגט הזה \u0003לשם גירושין דההיא\u0004 \u0005[של אותה\u0006 אשה מסויימת\u0005],\u0006 אבל אם נכתב בסתם — שמא יהא כשר לגרש בו את אשתו!","\u0003אלא מהא\u0004 \u0005[מזו]\u0006 ששנינו שם: \u0003יתר על כן,\u0004 יש לו שתי נשים ששמותיהן שווים, ו\u0003אמר ללבלר\u0004 (לסופר): \u0003כתוב\u0004 גט לאחת משתי נשי, \u0003ולאיזה שארצה אגרש\u0004 אותה בו — \u0003פסול לגרש בו,\u0004 משמע שצריך לכתוב לשמה של האשה המסויימת —","\u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 שאין עושים כן משום ש\u0003אין ברירה\u0004 שאין אומרים שמתברר הדבר למפרע שלשמה של זו נכתב!","\u0003אלא\u0004 יש לכך ראיה \u0003מהא\u0004 \u0005[מזו]\u0006 ששנינו שם: \u0003הכותב טופסי גיטין\u0004 שמכין מראש נוסחים קבועים של גט כדי שיהיו מזומנים בידו — \u0003צריך שיניח מקום\u0004 לכתיבת שם \u0003האיש, ומקום\u0004 לכתיבת שם \u0003האשה, ומקום\u0004 עבור \u0003העדים, ומקום\u0004 עבור \u0003הזמן. ואמר רב יהודה אמר שמואל: אף צריך שיניח מקום\u0004 המלים \u0003\"הרי את מותרת לכל אדם\",\u0004 שצריכות להיכתב לשם אשה זו דווקא. משמע איפוא שצריך הגט להיכתב לשמה של אשה מסויימת, ואם כתבו סתם — פסול.","הוסיף רבינא ואמר לרב פפא, \u0003תו רמי מילתא אחריתי\u0004 \u0005[שוב השליך\u0006 רבא, הראה סתירה \u0005בדבר אחר],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב יהודה אמר רב:\u0004 \u0003חטאת ששחטה לשם עולה\u0004 — \u0003פסולה,\u0004 אבל אם \u0003שחטה לשם חולין\u0004 — \u0003כשירה; אלמא\u0004 \u0005[מכאן\u0006 אפשר להסיק\u0005]:\u0006 \u0003דמינה\u0004 \u0005[\u0006דבר \u0005ש\u0006הוא בן \u0005מינה]\u0006 קדשים כמותה, \u0003מחריב בה\u0004 גורם לה נזק, אבל דבר \u0003דלאו\u0004 \u0005[שאינו]\u0006 בן \u0003מינה לא מחריב בה\u0004 ואינו נחשב?","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0003]\u0004 ממה ששנינו: \u0003כל הגט שנכתב שלא לשם אשה\u0004 — \u0003פסול,\u0004 ומלשון כללית זו ניתן לדייק: \u0003ואפילו לשם גויה\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פסול.\u0004 והרי גויה אינה בת מינה, שאין בה דין גירושין!","\u0003ושני\u0004 \u0005[ותירץ]\u0006 רבא: \u0003גט, דל\u0004 \u0005[הוצא]\u0006 \u0003גויה מיניה\u0004 \u0005[ממנו],\u0006 הרי גם אם לא היה נכתב לשם גויה \u0003הוה ליה סתמא\u0004 \u0005[הריהו\u0006 כגט \u0005סתם],\u0006 \u0003וסתמא\u0004 \u0005[וסתם]\u0006 גט, שלא לשם האשה המסויימת — \u0003פסול.\u0004 לעומת זאת, \u0003קדשים, דל\u0004 \u0005[הוצא]\u0006 את כוונת \u0003חולין מינייהו\u0004 \u0005[מהם]\u0006 — \u0003הוה ליה סתמא\u0004 \u0005[הרי זה\u0006 כאילו נשחטו ב\u0005סתם],\u0006 \u0003וסתמא\u0004 \u0005[וסתם]\u0006 זבחים \u0003כשירים.\u0004","הוסיף רבינא ואמר: \u0003ורמא מילתא אחריתי\u0004 \u0005[\u0006ועוד \u0005השליך\u0006 רבא, הראה סתירה \u0005אחרת].\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב יהודה אמר רב: חטאת ששחטה לשם עולה\u0004 — \u0003פסולה, שחטה לשם חולין\u0004 — \u0003כשירה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מינה מחריב בה דלאו\u0004 \u0005[שאינו]\u0006 \u0003מינה לא מחריב בה?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 נאמר לענין השרצים הטמאים: \"וכל כלי חרש אשר יפול מהם אל תוכו, כל אשר בתוכו יטמא\" (ויקרא יא, לג), ששרץ מת הנופל בתוך כלי חרס מטמא את האוכל שבתוכו. \u0003ו\u0004אמרו חכמים שהלשון \"תוכו\" באה להדגיש: \u0003\"תוכו\" ולא תוך תוכו,\u0004 שאם היו האוכלים מונחים בכלי שבתוך כלי החרס — אינם נטמאים. \u0003ואפילו כלי שטף\u0004 כלומר, כלי מתכת או עץ, שמקבל טומאה מגבו (שלא כמו כלי חרס) — גם הוא \u0003מציל.\u0004 משמע שאפילו דבר שאינו מינו גם כן נחשב לבטל את דינו של כלי החרס!","\u0003ושני\u0004 \u0005[ותירץ]\u0006 רבא: כלי שטף נחשב כמינו של כלי חרס, ששניהם כלים, ולכן מועיל לגביו. אבל \u0003עשו חולין אצל קדשים כמחיצה אצל תנור, מה מחיצה אצל תנור לא מהניא\u0004 \u0005[אינה מועילה]\u0006 \u0003לה כלל\u0004 להפריש בין הטומאה והאוכל, מפני שאינה נחשבת כמינו של התנור כלל, ולכן אינה חוצצת בו — \u0003אף\u0004 שחיטה לשם \u0003חולין אצל קדשים לא מהניא ליה\u0004 \u0005[אינה מועילה]\u0006 \u0003כלל\u0004 לפוסלם. ומה עניינה של מחיצה זו?","\u0003דתנן\u0004 \u0005[ששנינו]\u0006 במשנה: \u0003תנור\u0004 חרס \u0003שחצצו\u0004 עד שפתו \u0003בנסרים או ביריעות ונמצא שרץ במקום אחד\u0004 בצד אחד של המחיצה — \u0003הכל טמא\u0004 גם מעבר למחיצה.","וכן \u0003כוורת\u0004 עשויה קש \u0003שהיא פחותה\u0004 (שבורה, ושוב אינה כלי) גם אם היתה \u0003פקוקה בקש, ומשולשלת לאויר התנור,\u0004 אם היה \u0003שרץ בתוכה\u0004 — \u0003התנור טמא,\u0004 היה \u0003שרץ בתנור\u0004 — \u0003אוכלין שבתוכה\u0004 \u0003טמאין,\u0004 שאין היא נחשבת כחציצה לגבי התנור, \u0003ור' אליעזר מטהר.\u0004","\u0003אמר ר' אליעזר: קל וחומר, אם הציל\u0004 סוג כזה של מחיצה \u0003ב\u0004אוהל \u0003מת החמור,\u0004 שמטמא אדם וכלים שבעה ימים, ואם עשו מחיצה כזאת באוהל המת הריהי מצילה מן הטומאה, \u0003לא תציל\u0004 מטומאת שרץ \u0003בכלי חרס הקל\u0004 שאין אוירו מטמא אלא אוכלים ומשקים?","\u0003אמרו לו: לא,\u0004"],["\u0003אם הציל במת\u0004 למרות שדינו \u0003חמור\u0004 — \u0003שכן\u0004 עושים \u0003חלוקה באוהלין\u0004 שמנהג בני אדם לחלוק אוהל במחיצה, וכל חלק נחשב כחדר נפרד לעצמו, \u0003תציל\u0004 מחיצה \u0003בכלי חרש הקל, שאין\u0004 כלי חרס \u0003חלוקין באוהלין\u0004 אין נוהגים לחלקם במחיצות?","ומשיבים: \u0003התינח\u0004 \u0005[נניח\u0006 דבר \u0005זה]\u0006 \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 הסבורים שאין המחיצה מצילה, אבל \u0003לר' אליעזר מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי לדעתו מחיצה מצילה גם בתנור!","ומשיבים: \u0003ר' אליעזר\u0004 סבור כרב, לגבי העיקרון שמה שאינו מינו — אינו מועיל בו, אבל לענין מחיצה בתנור — \u0003קל וחומר קאמר\u0004 \u0005[הוא אומר],\u0006 ממת לשרץ, ובגללו הוא סבור שאף דבר שאינו מינו מועיל בו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שדוחים סברת שאינו מינו מפני קל וחומר, \u0003התם נמי לימא\u0004 \u0005[שם,\u0006 בחטאת ששחטה לשם חולין, \u0005גם כן נאמר]\u0006 \u0003קל וחומר:\u0004 אם \u0003קדשים מחללין קדשים, חולין לא כל שכן\u0004 שמחללים?","\u0003אלא\u0004 צריך לומר כי \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003רב\u0004 הוא \u0003כ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר'\u0004 \u0003אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב?\u0004 נאמר \u0003\"ולא יחללו את קדשי בני ישראל את אשר ירימו לה'\"\u0004 (ויקרא כב, טו), לומר ש\u0003קדשים\u0004 דווקא \u0003מחללין קדשים, ואין חולין מחללין קדשים.\u0004","ומדייקים: \u0003אלמא אתא קרא אפקיה\u0004 \u0005[מכאן שבא המקרא והוציא אותו]\u0006 \u0003מקל וחומר\u0004 שיש בו. אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במחיצת התנור, שלמד ר' אליעזר מקל וחומר שמחיצה מועילה בתנור (למרות שאינה מינו) \u0003ליתי\u0004 \u0005[שיבוא\u0006 המקרא\u0005]\u0006 \"כל אשר ב\u0003\"תוכו\"\u0004 לומר שמחיצה אינה מצילה בו, \u0003לפקיה\u0004 \u0005[ויוציא אותו]\u0006 \u0003מקל וחומר!\u0004","ומשיבים: \u0003האי \"תוכו\" מיבעי ליה\u0004 \u0005[\"תוכו\" זה נצרך לו]\u0006 לדין אחר, \u0003לאוכלין שגיבלן\u0004 (לש אותם) \u0003בטיט\u0004 ועטף אותם מכל צד, \u0003והכניסן לאויר תנור, סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובנגיעה לא מטמא\u0004 האוכל, אם יגע בו השרץ, משום שהטיט חוצץ — \u0003באוירו\u0004 של תנור טמא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מטמו\u0004 \u0005[מיטמאים]\u0006 האוכלים, \u0003[קא משמע לן\u0004 \u0005[משמיע לנו]\u0006\u0003]\u0004 בהדגשה \"כל אשר בתוכו\", שבכל זאת נטמאים האוכלים, כיוון שהם נמצאים בתוך חללו.","\u0003ו\u0004מן הצד האחר, \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על ר' אליעזר, מה הם משיבים? הם סבורים ש\u0003הנך לא צריכי קרא\u0004 \u0005[\u0006דברים \u0005אלה אינם צריכים מקרא]\u0006 והם מובנים מעצמם, שהרי האוכלים מצויים בחלל הכלי.","אגב כך מביאים עוד דיונים באותו ענין, \u0003רב יוסף בר אמי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 מ\u0003שינוי קודש\u0004 על \u0003שינוי בעלים ומשני\u0004 \u0005[ומתרץ].\u0006","וכך הקשה, \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב\u0004 לענין שינוי קודש: \u0003חטאת ששחטה לשם חטאת\u0004 אחרת, לכפר על שגגה אחרת שבידו — \u0003כשירה, לשם עולה\u0004 — \u0003פסולה; אלמא דלאו\u0004 \u0005[מכאן\u0006 שדבר \u0005שאינו]\u0006 \u0003מינה\u0004 (לשם עולה) \u0003מחריב בה,\u0004 פוסלה, אבל דבר שהוא \u0003מינה\u0004 (לשם חטאת אחרת) \u0003לא מחריב בה,\u0004 אינו פוסלה?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב,\u0004 לענין שינוי בעלים: \u0003חטאת ששחטה\u0004 שלא לשם הבעלים, אלא \u0003על מי שמחוייב חטאת\u0004 — \u0003פסולה,\u0004 אבל אם שחטה \u0003על מי שמחוייב עולה\u0004 — \u0003כשרה, אלמא\u0004 \u0005[מכאן]\u0006 \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003מינה\u0004 (אדם אחר שחייב חטאת) \u0003מחריב בה, דלאו\u0004 \u0005[שאינו]\u0006 \u0003מינה\u0004 (שאינו מחויב חטאת) \u0003לא מחריב בה!\u0004","\u0003ומשני\u0004 \u0005[ומתרץ]:\u0006 \u0003התם\u0004 \u0005[שם],\u0006 לענין שינוי קודש — \u0003\"ושחט אתה לחטאת\"\u0004 (ויקרא ד, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והרי חטאת לשם חטאת נשחטה,\u0004 ולכן היא כשירה.","\u0003הכא\u0004 \u0005[כאן],\u0006 לענין שינוי בעלים — \u0003\"וכפר עליו\"\u0004 (ויקרא ד, כו) \u0003כתיב\u0004 \u0005[נאמר]\u0006 — \u0003\"עליו\" ולא על חבירו,\u0004 ויש ללמוד כי \u0003חבירו\u0004 שפוסל, הרי זה \u0003דומיא דידיה\u0004 \u0005[בדומה לו],\u0006 \u0003שמחוייב כפרה כמותה,\u0004 ולא מי שמחוייב עולה.","ועוד בענין זה, \u0003רב חביבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 מ\u0003שינוי בעלים\u0004 על \u0003תוך תוכו, ומשני\u0004 \u0005[ומתרץ].\u0006","וכך הקשה, \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב: חטאת ששחטה על מי שמחוייב [חטאת\u0004 — \u0003פסולה, על מי שמחוייב] עולה\u0004 — \u0003כשירה; אלמא\u0004 \u0005[מכאן]\u0006 שדבר שהוא \u0003מינה מחריב בה, לאו\u0004 \u0005[\u0006דבר \u0005שאינו]\u0006 \u0003מינה לא מחריב בה?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"תוכו\" ולא תוך תוכו, אפילו כלי שטף מציל,\u0004 הרי שדבר שאינו מינו גם כן נחשב כלי כדי להציל בתוכו!","\u0003ומשני\u0004 \u0005[ומתרץ]:\u0006 \u0003ארבעה\u0004 פעמים \u0003\"תוכו\" כתיבי\u0004 \u0005[כתובים]\u0006 שם \u0003(תוכו).\u0004 כלומר, המלה \"תוכו\" כתובה שתי פעמים, והיה יכול לכתוב \u0003\"תוך\"\u0004 ונכתב \u0003\"תוכו\", \"תוך\"\u0004 ונכתב \u0003\"תוכו\",\u0004 ואם כן הרי הם כארבע פעמים.","וכך למדים: \u0003חד\u0004 \u0003לגופיה\u0004 \u0005[אחד\u0006 נצרך \u0005לגופו]\u0006 שכלי חרס מטמא באוירו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003לגזירה שוה,\u0004 שכשם שהכלי מטמא מה שבתוכו אף שלא נגע בו, כך הכלי מקבל טומאה משרץ הנמצא בתוכו למרות שאינו נוגע בכלי.","\u0003חד\u0004 \u0005[אחד]\u0006 בא לומר: \u0003תוכו של זה ולא תוכו של אחר,\u0004 שאם היה שרץ בתוך כלי שאינו כלי חרס — אינו מטמא באוירו (אלא רק אם נגע בו). \u0003אידך\u0004 \u0005[והאחר]\u0006 — \u0003תוכו ולא תוך תוכו,\u0004 לומר ש\u0003אפילו כלי שטף\u0004 שהיה בתוך כלי חרס שיש בו שרץ \u0003מציל\u0004 על האוכלים שבו, ואם כן הרי זו גזירת הכתוב, שאף דבר שאינו מינו מציל בו."],["במשנה נאמר מה דין הקרבן שנשחט שלא לשמו, ומעתה באים לברר את מקור ההלכה. \u0003מנלן דבעינן\u0004 \u0005[מנין לנו שאנו צריכים]\u0006 שתהא \u0003זביחה לשמה?\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם זבח\u0004 — \u0003שלמים קרבנו\"\u0004 (ויקרא ג, א), לומר \u0003שתהא זביחה\u0004 (שחיטה) \u0003לשם [שלמים].\u0004","ומקשים: \u0003ודילמא היינו שמייהו\u0004 \u0005[ושמא זהו שמם\u0006 של קרבנות שלמים\u0005]\u0006 \"זבח שלמים\"!","ומשיבים: \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 במקום אחר: \u0003\"המקריב את דם השלמים\"\u0004 (ויקרא ז, לג), וכן \u0003\"הזורק את דם השלמים\"\u0004 (ויקרא ז, טו), \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"זבח\", והכא כתיב\u0004 \u0005[וכאן נאמר]\u0006 \u0003\"זבח\u0004 שלמים\", \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהכוונה כאן היא \u0003שתהא זביחה לשם שלמים.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ב\u0003זביחה\u0004 שתהא לשמה, \u0003שאר עבודות\u0004 שיש בקרבן (קבלת הדם, הולכתו, וזריקתו על המזבח) \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שאף הן צריכות להיות לשמן?","\u0003וכי תימא לילף\u0004 \u0005[ואם תאמר נלמד]\u0006 דבר זה \u0003מזביחה,\u0004 יש לדחות: \u0003מה לזביחה\u0004 שיש בה חומרה מיוחדת, \u0003שכן נפסלה שלא לשם אוכלין בפסח,\u0004 שהשוחט עבור אנשים שאינם יכולים לאכול מקרבן הפסח — שחיטתו פסולה, אבל אם עשה כן באחת משאר העבודות אינו פוסל!","\u0003אלא אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"המקריב את דם השלמים\"\u0004 (ויקרא ז, לג) ולפי דברי חכמים הקרבה זו קבלת הדם היא (ראה להלן) — לומר: \u0003שתהא קבלה לשם שלמים.\u0004","ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 דין זה של \"לשמה\" רק \u0003בקבלה, ולילף\u0004 \u0005[ונלמד]\u0006 \u0003שחיטה מינה\u0004 \u0005[ממנה]!\u0006","ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 את הלימוד, ולומר: \u0003מה לקבלה\u0004 שהיא חמורה יותר \u0003שכן פסולה בזר\u0004 (שאינו כהן) \u0003ואשה,\u0004 מה שאין כן בשחיטה הכשרה בכל ישראל.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא מקור להלכה זו ב\u0003שחיטה וקבלה, זריקה מנלן\u0004 \u0005[מנין לנו]\u0006 שצריך שתהא לשם הקרבן?","\u0003וכי תימא לילף מהני\u0004 \u0005[ואם תאמר: נלמד מאלה,\u0006 שחיטה וקבלה\u0005],\u0006 יש לדחות: \u0003מה להני\u0004 \u0005[לאלה]\u0006 \u0003שכן טעונות צפון\u0004 שבקדשי קדשים צריך לעשותן בצפון העזרה, \u0003וישנן\u0004 גם \u0003בחטאות הפנימיות\u0004 (שדמן ניתן בתוך ההיכל), מה שאין כן בזריקה, שאינה נעשית רק בצפון, ואין זורקים מדם החטאות הפנימיות על המזבח החיצון!","\u0003אלא\u0004 למדנו דבר זה ממה ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"הזורק את דם השלמים\"\u0004 (ויקרא ז, טו), לומר \u0003שתהא זריקה לשם שלמים.\u0004","ושואלים: \u0003ולכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 \u0003בזריקה, ולילף מינה\u0004 \u0005[ושנלמד ממנה]\u0006 גם לקבלה ולשחיטה!","ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 ולומר: \u0003מה לזריקה\u0004 שהיא חמורה, \u0003שכן חייב עליה זר מיתה\u0004 אם עשה אותה, מה שאין כן בשחיטה וקבלה.","ושואלים: \u0003אשכחן כולהו\u0004 \u0005[מצאנו\u0006 את \u0005כולן]\u0006 כלומר, שלוש מארבע העבודות, \u0003הולכה מנלן\u0004 \u0005[מנין לנו]\u0006 שצריך שתהא לשמה?","\u0003וכי תימא לילף מכולהו\u0004 \u0005[ואם תאמר: נלמד מכולן]\u0006 — יש לדחות: \u0003מה לכולהו\u0004 \u0005[לכולן]\u0006 שיש בהן צד חמור, \u0003שכן\u0004 כל אחת מהן \u0003היא\u0004 \u0003עבודה שאי אפשר לבטלה,\u0004 שהיא הכרחית לצורך ההקרבה, \u0003תאמר בהולכה שאפשר לבטלה,\u0004 שאם שוחט סמוך למזבח אינו צריך להוליך!","\u0003אלא\u0004 למדנו דבר זה ממה ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"והקריב... את הכל... המזבחה\"\u0004 (ויקרא א, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 הקרבה \u0003זו הולכת אברים לכבש, ו\u0004מן הצד האחר \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"והקריבו\u0004 בני אהרן הכהנים את הדם\" (ויקרא א, ה) — \u0003זו קבלת הדם, ואפיק רחמנא\u0004 \u0005[והוציאה התורה]\u0006 קבלה \u0003בלשון\u0004 של \u0003הולכה, למימרא\u0004 \u0005[לומר]\u0006 ש\u0003הולכה לא תפקה\u0004 \u0005[תוציא אותה]\u0006 \u0003מכלל קבלה,\u0004 אלא כל דין הקיים בקבלה יש גם בהולכה.","\u0003ו\u0004ממשיכים לברר, \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא מקור לענין \u0003שנוי קודש,\u0004 שיש לעשות את כל ארבע העבודות שבקרבן לשם אותו קרבן שהוקדש לו, ואולם \u0003שנוי בעלים מנלן\u0004 \u0005[מנין לנו]?\u0006 מנין שצריך להתכוון בעבודות אלו לשם הבעלים ולא לשם אדם אחר?","\u0003אמר רב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ובשר זבח תודת שלמיו\"\u0004 (ויקרא ז, טו), לומר \u0003שתהא זביחה לשם תודה. אם אינו ענין לשינוי קודש, דנפקא לן מהתם\u0004 \u0005[שנלמד לנו משם]\u0006 מ\"ואם זבח שלמים\", כמו שלמדנו לעיל, \u0003תנהו ענין לשינוי בעלים.\u0004","ומקשים: \u0003ו\u0004כי \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003הא מיבעי ליה לכדתניא\u0004 \u0005[הרי נחוץ הוא לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003\"ובשר זבח תודת שלמיו\"\u0004 — \u0003אבא חנין אומר משום\u0004 (בשם) \u0003ר' אליעזר: בא ללמד\u0004 ש\u0003תודה ששחטה לשם שלמים\u0004 — הרי היא \u0003כשרה,\u0004 אבל \u0003שלמים ששחטן לשם תודה\u0004 — \u0003פסולה.\u0004 ו\u0003מה הפרש בין זה לזה?\u0004 הטעם הוא ש\u0003תודה קרויה שלמים,\u0004 כפי שהוא בפסוק זה — \"תודת שלמיו\", \u0003ואין שלמים קרויה תודה!\u0004","ומשיבים: אבא חנין למד דבר זה מן המלים \"תודת שלמיו\", ואילו \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003מ\u0004המלה \u0003\"זבח\" קאמרינן\u0004 \u0005[אומרים אנו]\u0006 שתהא הזביחה לשם הבעלים.","ומקשים עוד: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 \"זבח\" זה ללימוד אחר, ששנינו במדרש ההלכה: \u0003חטאת ואשם מנין\u0004 שנאכלים ליום ולילה, כמו קרבן תודה, שנאמר שם: \"ובשר זבח תודת שלמיו ביום קרבנו יאכל\"? \u0003תלמוד לומר: \"זבח\",\u0004 שכל דבר הקרוי זבח, אם לא מפורש בו אחרת, הרי הוא נאכל ליום ולילה בלבד, כמו שמפורש בקרבן התודה!","ומשיבים: \u0003אם כן,\u0004 אם באה המילה רק לצורך זה, \u0003נכתוב קרא\u0004 \u0005[שיכתוב במקרא]\u0006 \u0003\"ובשר תודת שלמיו [זבח]\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המלה \u0003\"זבח\"\u0004 לפני \"תודת שלמיו\"? \u0003שמע מינה תרתי\u0004 \u0005[למד ממנה שתים].\u0006","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לענין שינוי בעלים ב\u0003זביחה, שאר עבודות מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003וכי תימא לילף\u0004 \u0005[ואם תאמר שנלמד]\u0006 דבר זה \u0003מזביחה,\u0004 אפשר לדחות: \u0003מה לזביחה\u0004 שיש בה חומרה, \u0003שכן פוסל\u0004 בשחיטה \u0003שלא לשם אוכלין בפסח!\u0004","אלא כך נאמר: \u0003נאמרה זביחה בשינוי קודש ונאמרה זביחה בשינוי בעלים, מה זביחה האמורה בשינוי קודש\u0004 — \u0003לא חלקת\u0004 בהלכה \u0003בין זביחה לשאר עבודות,\u0004 ובכולן צריך שייעשו לשמו, \u0003אף זביחה האמורה בשינוי בעלים\u0004 — \u0003לא תחלק בהן בין זביחה לשאר עבודות.\u0004","ומקשים: גם לימוד זה \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0003לפרוך]\u0004 אותו ולומר: \u0003מה לשינוי קודש שכן\u0004 יש בו דברים שאינם מצויים בשינוי בעלים, והם: \u0003פסולה בגופה\u0004 שהפסול הוא בגופו של הקרבן, שהרי הוא משנה את שמו ומהותו של הקרבן, \u0003וישנו בארבע עבודות\u0004 שבכל אחת מהן יש משמעות באיזה קרבן מדובר, אבל שינוי בעלים אינו נוגע אלא לזריקה, שהיא המכפרת על הבעלים,","\u0003ו\u0004כן \u0003ישנו לאחר מיתה\u0004 שקרבן שהיורש מקריבו לאחר מות הבעלים יש בו משמעות לשינוי קודש, אבל אין בו שינוי בעלים, שהרי כבר מתו. \u0003ו\u0004כן שינוי קודש \u0003ישנו בציבור כביחיד,\u0004 מה שאין כן בשינוי בעלים, שקרבן ציבור הכל בעליו!"],["ומוסיפים: \u0003ואף על גב דתרתי\u0004 \u0005[ואף על פי ששתים]\u0006 מארבע הוכחות אלה הן \u0003לאו דוקא\u0004 \u0005[אינן מדוייקות],\u0006 \u0003תרתי מיהא דוקא\u0004 \u0005[שתים\u0006 מהן \u0005על כל פנים מדוייקות].\u0006","ומסבירים: מה שנאמר ששינוי קודש פסולו בגופו אינו מדוייק, שכן \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003שינוי בעלים\u0004 שאנו אומרים \u0003דלא הוי\u0004 \u0005[שאין הוא]\u0006 \u0003פסולו בגופו?\u0004 משום שהוא \u0003מחשבה בעלמא\u0004 \u0005[בלבד]\u0006 ואינו נוגע לגוף הקרבן, אם כן, \u0003שינוי קודש נמי\u0004 \u0005[גם כן]\u0006 \u0003מחשבה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא! אלא\u0004 אומר אתה: \u0003כיון דאחשבה\u0004 \u0005[שחשב אותה\u0006\u0003]\u0004 \u0003פסלה\u0004 בשינוי קודש, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בשינוי בעלים \u0003כיון דאחשבה\u0004 \u0005[שחשב אותה]\u0006 \u0003פסלה! ו\u0004כן מה שנאמר שדווקא שינוי קודש ישנו לאחר מיתה, אינו נכון","\u0003ל\u0004דעת \u0003רב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי\u0004 ש\u0003אמר: יש שינוי בעלים\u0004 גם \u0003לאחר מיתה.\u0004 אולם \u0003תרתי מיהא איכא למיפרך\u0004 \u0005[שתים על כל פנים יש\u0006 מקום \u0003לפרוך].\u0004 ואם כן אין ללמוד משינוי קודש לשינוי בעלים!","\u0003אלא אמר רב אשי\u0004 מקור אחר, ש\u0003אמר קרא\u0004 \u0005[המקרא\u0006 בקרבן עולה\u0005]:\u0006 \u0003\"ונרצה לו לכפר עליו\"\u0004 (ויקרא א, ד), לדייק: הכפרה (שנעשית על ידי זריקת הדם) צריך שתהיה עליו \u0003ולא על חבירו.\u0004","ושואלים: \u0003ו\u0004כי \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[\u0006הרי כתוב \u0005זה נצרך לו לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"ונרצה לו לכפר עליו\", ר' שמעון אומר: את ש\u0004קיבל \u0003עליו\u0004 להקריב (שאמר \"הרי עלי עולה\") — הוא זה ש\u0003חייב באחריותו,\u0004 שאם אבד או מת חייב להביא קרבן אחר. \u0003ואת שאינו עליו,\u0004 שלא הקדיש אלא בהמה מסויימת, כגון שאמר \"הרי זו עולה\", ולא קיבל על עצמו התחייבות כללית להביא קרבן מסוג זה — \u0003אינו חייב באחריותו.\u0004","\u0003ואמר רב יצחק בר אבדימי: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 \"הרי \u0003עלי\u0004 עולה\", \u0003כמאן דטעון ליה אכתפיה דמי\u0004 \u0005[כמי שטעון לו\u0006 הקרבן \u0005על כתפו הוא נחשב]\u0006 וחייב בו עד שיביאו בפועל!","ומשיבים: \u0003רב אשי מ\"ונרצה לו לכפר\" קאמר\u0004 \u0005[הוא אומר],\u0006 מן המלה \"לו\" — דווקא כשהוא לו, לשמו. ולא מן ההדגשה \"עליו\".","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה לענין \u0003זביחה וזריקה\u0004 שצריך שיעשה עבודות אלו לשם הבעלים, \u0003קבלה מנלן\u0004 \u0005[מנין לנו]\u0006 שמצוה שתיעשה לשם הבעלים?","\u0003וכי תימא לילף\u0004 \u0005[ואם תאמר שתלמד]\u0006 \u0003מזביחה וזריקה,\u0004 יש לדחות: \u0003מה לזביחה וזריקה שכן עבודה שחייבין עליה\u0004 מיתה אם עשאה \u0003בחוץ\u0004 (מחוץ למקדש), ואין הדין כן בקבלה!","\u0003אלא אמר רב אשי: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003מאיל נזיר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת האיל יעשה זבח שלמים\"\u0004 (במדבר ו, יז) \u0003שתהא עשייתו לשם שלמים. ואם אינו ענין לשינוי קודש, דנפקא ליה מהתם\u0004 \u0005[שיוצא לו משם]\u0006 ממקור אחר כמו שהוכחנו לעיל (עמוד א), \u0003תנהו ענין לשינוי בעלים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר אבא לרבא, אימא\u0004 \u0005[אמור]\u0006 כך: \u0003\"יעשה\"\u0004 — הרי זה \u0003כלל, \"זבח\"\u0004 — \u0003פרט,\u0004 ולפי שיטת מדרשי ההלכה: \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ונאמר לפיכך: \u0003זביחה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 צריך שיעשהו לשם בעליו, \u0003מידי אחרינא\u0004 \u0005[דבר\u0006 \u0003אחר]\u0004 כגון קבלה — \u0003לא!\u0004","ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \u0003\"יעשה שלמים זבח\"\u0004 — הייתי מפרש \u0003כדקאמרת\u0004 \u0005[כמו שאמרת],\u0006 שהכלל הוא \"יעשה שלמים\", והפרט — \"זבח\", ואולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"יעשה זבח שלמים\",\u0004 נמצא כי \"יעשה\" \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003כלל שאינו מלא,\u0004 שאינו מוגדר בשלימות, \u0003וכל כלל שאינו מלא\u0004 — \u0003אין דנין אותו בכלל ופרט.\u0004","\u0003רבינא אמר: לעולם דנין\u0004 כאן בכלל ופרט, \u0003ו\u0004מה שכתוב בסוף \u0003\"לה'\"\u0004— \u0003חזר וכלל\u0004 לדונו במידת כלל ופרט וכלל (כמבואר להלן).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: והא לא דמי כללא קמא לכללא בתרא\u0004 \u0005[והרי אינו דומה הכלל הראשון לכלל האחרון],\u0006 שכן \u0003כללא קמא\u0004 \u0005[הכלל הראשון]\u0006 \u0003מרבה עשיות ותו לא\u0004 \u0005[ולא עוד],\u0006 כלומר, רק דברים שהם עבודות הכרחיות עבור הקרבן, ואילו \u0003כללא בתרא\u0004 \u0005[הכלל האחרון]\u0006 הוא \u0003כל\u0004 דבר שהוא \u0003לה', ואפילו שפיכת שיריים והקטרת אימורין!\u0004 השיב לו: \u0003הא תנא דבי\u0004 \u0005[הרי התנא בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל בכללי ופרטי דריש כי האי גוונא\u0004 \u0005[בכללים ופרטים דורש כעין זה],\u0006 ולפיכך יש בכגון זה כלל (\"יעשה\") ופרט (\"זבח\") וכלל (\"לה'\"), ויש לדורשו לפי מידה זו:","\u0003כלל ופרט וכלל אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט, מה הפרט\u0004 (שחיטה) \u0003מפורש\u0004 שהוא \u0003עבודה ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שתהיה \u0003לשמן\u0004 של בעלים, \u0003אף כל\u0004 שהוא \u0003עבודה\u0004 בכלל זה, \u0003ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שיהיו \u0003לשמן\u0004 לשם הבעלים.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 אתה דן כעין הפרט, יש לדקדק יותר בהגדרה, ולומר: \u0003מה הפרט מפורש\u0004 שהוא \u0003עבודה וחייבין עליה בחוץ\u0004 (אם עשה אותה מחוץ למקדש), \u0003אף כל\u0004 שהוא \u0003עבודה וחייבין עליה בחוץ\u0004 בכלל זה, ולפיכך: \u0003שחיטה וזריקה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003קבלה והולכה\u0004 — \u0003לא!\u0004","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נאמר כך: \u0003מה הפרט מפורש דבר הטעון צפון\u0004 (שצריך שייעשה רק בצפון העזרה) \u0003וישנו בחטאות הפנימיות, אף כל הטעון צפון וישנו בחטאות הפנימיות\u0004 בכלל זה. ולפי זה, \u0003שחיטה וקבלה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003זריקה\u0004 שהוא על קרנות המזבח, וחלקו בדרום — \u0003לא!\u0004","ומשיבים: \u0003איכא למימר הכי ואיכא למימר הכי\u0004 \u0005[אפשר לומר כך ואפשר לומר כך],\u0006 ומשום כך \u0003שקולין הן ויבאו שניהן. לישנא אחרינא\u0004 \u0005[בלשון אחרת]\u0006 אמרו זאת: \u0003וחדא חדא תיקו במילתא\u0004 \u0005[ואחת אחת\u0006 מהן \u0005תעמוד\u0006 \u0005בעניינה].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003זריקה מדרב אשי נפקא\u0004 \u0005[יוצאת],\u0006 מ\"ונרצה לו לכפר עליו\" (ראה לעיל), ולפיכך אנו דנים כעין הפרט לרבות קבלה.","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא דין זה ב\u0003איל נזיר,\u0004 שמצוה לעשות לשם הבעלים \u0003שאר שלמים מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003וכי תימא נילף\u0004 \u0005[ואם תאמר שנלמד]\u0006 \u0003מאיל נזיר,\u0004 יש לדחות: \u0003מה לאיל נזיר שכן יש עמהן דמים אחרים\u0004 כלומר, שאינו בא כקרבן לבדו, אלא עם קרבנות אחרים (חטאת ועולה)!","ומשיבים: \u0003אם כן, נכתוב\u0004 \u0005[שיכתוב\u0006 הפסוק\u0005]\u0006 \u0003\"שלמי\", מאי\u0004 \u0005[מהו]\u0006 \u0003\"שלמים\"? לרבות כל שלמים.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה ל\u0003שלמים,\u0004 שצריך לעשותם לשמם ולשם הבעלים, \u0003שאר כל קדשים מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003וכי תימא נילף\u0004 \u0005[ואם תאמר נלמד]\u0006 הלכה זו \u0003משלמים,\u0004 יש לדחות: \u0003מה לשלמים, שכן טעונין סמיכה ונסכים ו\u0004יש בהם \u0003תנופת חזה ושוק,\u0004 ולא כל הקרבנות הם כיוצא בזה!","\u0003אלא אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"זאת התורה לעלה ולמנחה ולחטאת ולאשם ולמלואים ולזבח השלמים\"\u0004 (ויקרא ז, לז), \u0003הקישן הכתוב\u0004 את כל הקרבנות כולם \u0003לשלמים: מה שלמים בין\u0004 לענין \u0003שינוי קודש בין\u0004 לענין \u0003שינוי בעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003לשמה, אף כל\u0004 הקרבנות \u0003בין שינוי קודש בין שינוי בעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003לשמה.\u0004","ושואלים: אם כן, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003היכא דשחיט להו\u0004 \u0005[במקום שהוא שוחט אותם]\u0006 \u0003שלא לשמה ליפסלו\u0004 \u0005[ייפסלו],\u0006 ולא כמו שאמרנו במשנה שהם כשרים!","ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"מוצא שפתיך תשמר ועשית כאשר נדרת\u0004 לה' אלהיך נדבה\" (דברים כג, כד), \u0003האי\u0004 \u0005[זו]\u0006 \u0003נדבה\u0004 היא? הרי \u0003נדר הוא,\u0004 כמו שנאמר \"כאשר נדרת\"! \u0003[אלא], אם כמה שנדרת עשית\u0004 — \u0003יהא נדר\u0004 ותצא בו ידי חובה, \u0003ואם לאו\u0004 (ששינית בו) — \u0003יהא נדבה,\u0004 ועל כל פנים אינו נפסל.","ומעירים: \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 לומר הפסוק \u0003\"מוצא שפתיך\", ואיצטריך\u0004 \u0005[והוצרך]\u0006 ההיקש מ\u0003\"זאת התורה\", דאי כתב רחמנא\u0004 \u0005[שאילו\u0006 היתה \u0005כותבת התורה]\u0006 רק \u0003\"מוצא\u0004 שפתיך תשמור\", \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006"],["\u0003לא ידע במאי\u0004 \u0005[אין אנו יודעים במה]\u0006 נאמר הדבר, שהרי לא נאמר באיזה אופן משנה מן הנדר שנדר — לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"זאת התורה\"\u0004 להקיש את כל הקרבנות לקרבן שלמים, שצריך להעשות לשמו ולבעליו. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו\u0006 היתה \u0005כותבת התורה]\u0006 רק: \u0003\"זאת התורה\", הוה אמינא ליפסלו\u0004 \u0005[הייתי אומר שייפסלו\u0006 לגמרי\u0005]\u0006 על ידי שינוי זה ששינה בהם, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"מוצא שפתיך\"\u0004 ללמד שבכל זאת הריהו נרצה כנדבה, אף שאינו עולה לבעליו.","מספרים כי שאלה זו עלתה באופן אחר: \u0003רמי\u0004 \u0003ריש לקיש על מעוהי בי מדרשא, ומקשי\u0004 \u0005[מוטל היה ריש לקיש על בטנו בבית המדרש, והיה מקשה]\u0006 כך: קרבנות אלה שעשה בהם שינוי קודש או שינוי בעלים, \u0003אם כשרים הם\u0004 — \u0003ירצו\u0004 לבעליהם, ויצאו בהם ידי חובה, \u0003ואם אין מרצין\u0004 — \u0003למה באין?\u0004","\u0003אמר לו ר' (אליעזר) [אלעזר]: מצינו\u0004 (מצאנו) דין דומה לזה \u0003ב\u0004קרבנות ה\u0003באין לאחר מיתה\u0004 של הבעלים, \u0003שהן כשרין ו\u0004אולם \u0003אין\u0004 הם \u0003מרצין,\u0004 שהרי אין להם בעלים לרצות ולכפר עליהם. ומנין שהם כשרים? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה\u0004 (יולדת, שצריכה להביא כקרבן חטאת ועולה) \u0003שהביאה חטאתה ומתה\u0004 — \u0003יביאו יורשין עולתה,\u0004 הביאה \u0003עולתה ומתה\u0004 — \u0003לא יביאו יורשין חטאתה.\u0004 הרי שמביאים את קרבן העולה, למרות שאינו מרצה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך בעולה, דאתיא\u0004 \u0005[ש\u0006הרי היא \u0005באה]\u0006 \u0003לאחר מיתה\u0004 שאם מפריש בהמה לעולה, אפשר להקריב אותה גם לאחר מותו, אבל \u0003אשם דלא אתי\u0004 \u0005[שאינו בא]\u0006 \u0003לאחר מיתה,\u0004 שהרי הוא בא לכפרת עוון, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכאשר נשחט שלא לשמו הריהו כשר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003הרי מחלוקתך בצידו\u0004 כלומר, יש מי שבאמת מעלה סברה זו, כשיטתך, כמו ששנינו במשנה, \u0003ר' אליעזר אומר: אף האשם\u0004 נפסל לגמרי שלא לשמו.","\u0003אמר\u0004 ריש לקיש על ר' אלעזר: \u0003זהו שאומרין עליו אדם גדול הוא? קאמינא אנא\u0004 \u0005[אומר אני]\u0006 \u0003משנה שלימה\u0004 שהיא מסקנת ההלכה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 ומוכיח משיטת יחיד של \u0003ר' אליעזר!\u0004","\u0003אלא אמר ריש לקיש: אפתח אנא פתחא לנפשאי\u0004 \u0005[אפתח אני פתח לעצמי],\u0006 כלומר, אמצא אני עצמי פתרון לשאלתי, \u0003שנאמר:\u0004 \u0003\"מוצא שפתיך\u0004 תשמור ועשית כאשר נדרת לה' אלקיך\" (דברים כג, כד), ויש לתמוה: \u0003האי\u0004 \u0005[\u0006וכי \u0005זה]\u0006 \u0003נדבה? נדר הוא! כו' כדלעיל\u0004 \u0005[כמו\u0006 שאמרנו \u0005למעלה],\u0006 שמכאן עולה שאף שאין קרבן שנשחט שלא לשמו מועיל למלאות חובת נדרו של המקריב, מכל מקום הריהו כנדבה.","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003ר' זירא ו\u0004עמו \u0003ר' יצחק בר אבא ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003אביי גבייהו\u0004 \u0005[אצלם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[ויושבים\u0006 היו \u0005ואומרים]\u0006 כך: \u0003קשיא ליה\u0004 \u0005[קשה\u0006 היה \u0005לו]\u0006 \u0003לריש לקיש\u0004 מדין \u0003אשם\u0004 ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003לאחר מיתה, ונסיב לה תלמודא\u0004 \u0005[והביא לו תלמוד,\u0006 הסבר וטעם\u0005]\u0006 מ\u0003\"מוצא שפתיך\".\u0004 אבל אין מכאן ראיה, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: דווקא דבר \u0003הבא בנדר ובנדבה,\u0004 המוזכרים באותו פסוק, \u0003לייתי\u0004 \u0005[שיביא]\u0006 אותו \u0003ולא לירצי\u0004 \u0005[ירצה],\u0006 אבל \u0003אשם\u0004 שאינו בא בנדר, אלא חובה הוא \u0003—\u0004 \u0003לא לייתי\u0004 \u0005[יביא]\u0006 \u0003כלל\u0004 אם עשאו שלא לשמו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי, ריש לקיש\u0004 אמנם השתמש בפסוק זה לפתרון בעייתו, אבל \u0003מהכא\u0004 \u0005[מכאן]\u0006 \u0003פתח,\u0004 שנאמר בקרבן חטאת: \u0003\"ושחט אותה לחטאת\"\u0004 (ויקרא ד, לג), ויש כאן הדגשה: דוקא אם שחט \u0003\"אותה\"\u0004 — את החטאת — \u0003לשמה כשרה, שלא לשמה פסולה\u0004 לגמרי. \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שאר קדשים שלא לשמן\u0004 — \u0003כשרין; יכול ירצו\u0004 לגמרי, שיצא בהם ידי חובתו? \u0003תלמוד לומר: \"מוצא שפתיך\"\u0004 — שלמדנו מכאן שאם שינה — אינו עולה לו משום נדרו.","והקשו: ומכל מקום פסוק זה עוסק בדבר הבא בנדר ונדבה, \u0003ו\u0004אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 לצד ההפוך: אותו קרבן \u0003הבא בנדר ונדבה\u0004 — \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003ולא לירצי\u0004 \u0005[ירצה],\u0006 אבל \u0003אשם\u0004 ששחטו שלא לשמו \u0003ארצויי נמי לירצי\u0004 \u0005[גם כן ירצה]!\u0006","\u0003אמר אביי: אשם דמירצי לא מצית אמרת\u0004 \u0005[שירצה אין אתה יכול לומר],\u0006 \u0003קל וחומר מעולה, ומה עולה שאינה מכפרת אינה מרצה\u0004 כפי שאמרנו, שהרי היא באה בנדר ונדבה, \u0003אשם\u0004 שהוא חמור יותר, \u0003שמכפר\u0004 על עוון — \u0003אינו דין שאינו מרצה?\u0004","ואומרים: יש לדחות את הקל וחומר, כי \u0003מה לעולה\u0004 שהיא חמורה יותר \u0003שכן\u0004 היא קריבה \u0003כליל\u0004 על המזבח, מה שאין כן באשם שנאכל לכהנים!","ומשיבים: \u0003שלמים יוכיחו,\u0004 שאינם מרצים אף שאינם עולים כליל, ובכל זאת אינם מרצים אם עשאן שלא לשמם.","ודוחים: יש לפרוך גם הוכחה זו, \u0003מה לשלמים\u0004 שיש בהם חומרה מיוחדת, \u0003שכן טעונין נסכין ותנופת חזה ושוק,\u0004 מה שאין באשם!","ומשיבים: \u0003עולה תוכיח\u0004 שאף בה אין תנופת חזה ושוק, ומכל מקום אינה מרצה. \u0003וחזר הדין\u0004 כלומר, חוזרת ההוכחה למקומה, שהרי \u0003לא ראי זה כראי זה ולא ראי זה כראי זה\u0004 כל אחת מן ההוכחות אינה דומה לחברתה, שיש בה צד חמור יותר, אבל \u0003הצד השוה שבהן\u0004 הן בעולה והן בשלמים — \u0003שהן קדשים, ו\u0004אם \u0003שחטן שלא לשמן כשירין ואין מרצין, אף אני אביא אשם שהוא קודש, ו\u0004לפיכך אם \u0003שחטו שלא לשמו\u0004 — \u0003כשר ואינו מרצה.\u0004","ודוחים לימוד זה: \u0003מה להצד השוה שבהן\u0004 בעולה ושלמים, המבדילם מן האשם, \u0003שכן ישנו בציבור\u0004 גם עולה וגם שלמים, ואין אשם ציבור!","ומשיבים: \u0003תודה תוכיח\u0004 שאינה בציבור, ובכל זאת אם עשה שלא לשמה היא כשרה ואינה עולה לבעלים."],["ודוחים: \u0003מה לתודה שכן טעונה לחם,\u0004 שיש בה מצוה יתירה!","כנגד זה אפשר לטעון: \u0003עולה ושלמים יוכיחו,\u0004 שאין בהם לחם ומכל מקום אינם מרצים. \u0003וחזר הדין, לא ראי זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן\u0004 — \u0003שהן קדשים, ו\u0004אם \u0003שחטן שלא לשמן כשר ואינו מרצה, אף אני אביא אשם שהוא קדש ו\u0004אומר כי אם \u0003שחטו שלא לשמו\u0004 — \u0003כשר ואינו מרצה.\u0004","ומקשים: \u0003מה להצד השוה שבהן,\u0004 בעולה תודה ושלמים, \u0003שהן באין בנדר ובנדבה,\u0004 מה שאין כן באשם, שאינו בא אלא חובה!","\u0003אלא אמר רבא:\u0004 בפסוק \u0003\"זאת התורה\u0004 לעולה ולמנחה ולחטאת ולאשם ולמלואים ולזבח השלמים\" (ויקרא ז, לז), \u0003הקישו הכתוב\u0004 את האשם \u0003לשלמים: מה שלמים שהן קדשים ו\u0004אם \u0003שחטן שלא לשמן כשרים ואין מרצין, אף אני אביא אשם שהוא קודש\u0004 שהוא כשר ואינו מרצה.","ושואלים: \u0003מאי חזית דאקשת\u0004 \u0005[מה ראית שאתה מקיש]\u0006 אשם \u0003לשלמים? אקיש\u0004 \u0005[הקש\u0006 אותו\u0005]\u0006 \u0003לחטאת,\u0004 שנפסלה לגמרי בשינוי השם!","ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה התורה]\u0006 בחטאת על ידי המלה \u0003\"אותה\"\u0004 (\"ושחט אותה לחטאת\". ויקרא ד, לג), לומר שרק בחטאת יש דין זה ולא קרבן אחר.","","ובענין דברי ר' אלעזר בעמוד הקודם, שהביא ראיה לדין משנתנו, מקרבנות הבאים לאחר מיתה שהם כשרים למרות שאינם מרצים, מסופר \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב הונא ו\u0004עמו \u0003רב נחמן, ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003רב ששת גבייהו\u0004 \u0005[אצלם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[ויושבים\u0006 היו \u0005ואומרים]:\u0006 \u0003קשיא ליה\u0004 \u0005[קשה\u0006 היה \u0005לו]\u0006 \u0003לריש לקיש\u0004 על דברי ר' אלעזר: \u0003אשם\u0004 שהוא \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003לאחר מיתה\u0004 מנין שהוא כשר כשנעשה שלא לשמו. ויש לתמוה: \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003ר' אלעזר: אשם נמי אתי\u0004 \u0005[גם כן בא]\u0006 \u0003לאחר מיתה,\u0004 שאשם שמתו בעליו, לכשיפול בו מום מביאים בדמיו קרבן עולה!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: אשם למאי\u0004 \u0005[למה]\u0006 לאיזה דין נאמר שהוא \u0003קרב\u0004 לאחר מיתה? \u0003למותרו,\u0004 שאין מקריבים אותו עצמו, אלא משתמשים בדמיו לקנות קרבן עולה. והרי \u0003חטאת נמי\u0004 \u0005[גם כן]\u0006 יש בה דין זה, שאם מתו הבעלים \u0003מיקרב קרבה מותרה,\u0004 ובכל זאת אם נשחטה שלא לשמה הרי היא פסולה לגמרי. ואין איפוא ראיה מהבאת המותר לאחר מיתה לדין משנתנו. ודוחים: \u0003חטאת, אף על גב\u0004 ש\u0003קרבה מותרה, מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 אותה בלשון \u0003\"הוא\"\u0004 (\"חטאת הוא\", ויקרא ד, כד). לומר, שרק אם נשחטה כחטאת, הריהי כשירה.","","ועל כך מקשים: \u0003אשם נמי כתיב ביה\u0004 \u0005[גם כן נאמר בו]\u0006 \u0003\"הוא\"\u0004 (\"אשם הוא\". ויקרא ז, ה), ומדוע אינו נפסל כשעשאו שלא לשמו!","ומשיבים: \u0003ההוא\u0004 כתוב זה באשם אינו נוגע לענייננו, שהרי \u0003לאחר הקטרת אימורים\u0004 (האיברים הפנימיים המוקטרים על המזבח) \u0003הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שכתוב שם: \"והקטיר אותם הכהן המזבחה אשה לה' אשם הוא\", \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבל אשם לא נאמר בו \"הוא\"\u0004 \u0003אלא לאחר הקטרת אימורין\u0004 על גבי המזבח, \u0003והוא\u0004 (קרבן אשם) \u0003עצמו\u0004 אף \u0003אם לא הקטירו\u0004 כלל את ה\u0003אימורין\u0004 — \u0003כשר.\u0004","ואגב כך שואלים: \u0003ואלא\u0004 ההדגשה \u0003\"הוא\" למה לי?\u0004 ומשיבים: \u0003לכ\u0004 דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: אשם שניתק לרעיה\u0004 כלומר, שהחליטו בית הדין שמפני סיבה כלשהי (שנתכפרו בעליו או שמתו) אין להקריבו, ויש להשאירו שירעה בשדה עד שיפול בו מום ויביאו בדמיו עולה, \u0003ושחטו סתם\u0004 — \u0003כשר\u0004 כעולה.","ונדייק: \u0003ניתק\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא ניתק\u0004 — \u0003לא, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 מה מקורה של הלכה זו? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"הוא\",\u0004 כלומר: \u0003בהווייתו יהא,\u0004 ורק כאשר מנתקים אותו מ\"הוייתו\" הקודמת הריהו נידון כעולה.","ועוד מסופר: בהזדמנות אחרת \u0003יתבי\u0004 \u0005[יושבים\u0006 היו\u0005]\u0006 \u0003רב נחמן ו\u0004עמו \u0003רב ששת, ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003רב אדא בר מתנה גבייהו\u0004 \u0005[אצלם],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[ויושבים\u0006 היו \u0005ואומרים]\u0006 באותם חילופי דברים שבין ריש לקיש ור' אלעזר: \u0003הא דקאמר\u0004 \u0005[זו שאמר]\u0006 \u0003ר' אלעזר: מצינו בבאין לאחר מיתה שהן כשרין ואין מרצין\u0004 — \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003ריש לקיש: הנהו נמי לייתו ולירצו\u0004 \u0005[אלה גם כן שיבואו וירצו]\u0006 על היורשים?","\u0003אמר להן רב אדא בר מתנה:\u0004 כיצד אפשר שירצו? אשה שמפרישה קרבן \u0003יולדת\u0004 ומתה, \u0003אם היא ילדה, בניה מי\u0004 \u0005[האם]\u0006 \u0003ילדו?\u0004 ובודאי לא שייך שיתכפרו בקרבנה!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אסי: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003כמה\u0004 מצוות \u0003עשה גבה\u0004 \u0005[אצלה,\u0006 שעברה עליהם\u0005]\u0006 \u0003לא מיתכפרא\u0004 \u0005[תתכפר]\u0006 בעולה שהיא מביאה ללידתה? \u0003וכיון דכי איכא\u0004 \u0005[שכאשר יש]\u0006 \u0003כמה\u0004 מצוות \u0003עשה גבה\u0004 \u0005[אצלה],\u0006 \u0003מיכפרא\u0004 \u0005[\u0006היתה \u0005מתכפרת],\u0006 יש לומר כי \u0003יורשיה נמי מיכפר\u0004 \u0005[גם כן מתכפרים]\u0006 בעולה זו שירשו ממנה, על מצוות עשה שעברו עליהם!","ושואלים: \u0003למימרא דקניא להו\u0004 \u0005[האם לומר שקנוי להם]\u0006 הקרבן ליורשים, עד שיוכלו להתכפר בו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן:\u0004 אדם ש\u0003הניח מנחה\u0004 שהפריש קודם לכן \u0003לשני בניו ומת\u0004 — מנחה זו \u0003קריבה, ואין בו\u0004 דין \u0003שותפות. ואי סלקא דעתך קניא להו\u0004 \u0005[ואם עולה על דעתך\u0006 שהיא \u0005קנויה להם],\u0006 הלוא \u0003\"נפש\"\u0004 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 (\"ונפש כי תקריב קרבן מנחה לה'\". ויקרא ב, א), ודייקו חכמים: ולא שתי נפשות, שאין שניים מביאים קרבן מנחה אחד! אלא ודאי אין המנחה קנויה להם, ולכן אינם נחשבים כבעליה או כשותפים בה.","ושואלים: \u0003ולא קניא להו\u0004 \u0005[ו\u0006האם \u0005אינה קנויה להם]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 עצמו: \u0003הניח בהמה\u0004 של קרבן שהפריש \u0003לשני בניו ומת\u0004 — \u0003קריבה, ואין ממירין בה\u0004 שאם המירו בהמה זו באחרת — אין השניה קדושה. ומעתה, \u0003אי אמרת בשלמא קניא להו\u0004 \u0005[נניח אם אתה אומר\u0006 שהיא \u0005קנויה להם],\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם ש\u0003אין ממירין בה\u0004 — \u0003דהויא להו\u0004 \u0005[שהרי נעשה להם]\u0006 \u0003כ\u0004בהמת \u0003שותפין,\u0004"],["\u0003ושותפין לא מצו ממירין\u0004 \u0005[אינם יכולים להמיר].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהיא \u0003לא קניא להו\u0004 \u0005[קנויה להם],\u0006 ואין הם נחשבים בעלים כדי להיקרא שותפים בה — \u0003אמורי נמי לימרו\u0004 \u0005[להמיר שימירו גם כן],\u0006 שהרי יורשים הם, ויורש יכול להמיר!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 שאף על פי ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"אם המר ימיר\"\u0004 (ויקרא כז, י) — וכפל הלשון בא \u0003לרבות את היורש,\u0004 מכל מקום ממה שנאמר הדבר בלשון יחיד למדים שיורש \u0003אחד ממיר ואין שנים ממירין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יעקב מנהר פקוד: אלא מעתה, גבי\u0004 \u0005[אצל]\u0006 פדיון \u0003מעשר\u0004 שני, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ואם גאל יגאל\u0004 איש ממעשרו חמישיתו יוסף עליו\" (ויקרא כז, לא) — וגם שם נאמר הדבר \u0003לרבות את היורש, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר: \u0003אחד גואל ואין שנים גואלין\u0004 משום שנאמר בלשון יחיד? והרי לא מצאנו דין כזה במעשר!","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מעשר, דגבי אבוהון נמי איתיה\u0004 \u0005[שאצל אביהם\u0006 עצמו \u0005גם כן היה יכול להיות]\u0006 \u0003בשותפות,\u0004 ואילו תמורה אינה יכולה להיעשות כלל על ידי שותפים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי לרב אשי: ומינה\u0004 \u0005[וממנה]\u0006 מהלכה זו עצמה, שיורש אחד ממיר ולא שנים, אתה יכול להגיע למסקנה הפוכה, שהבהמה שהקדיש האב לקרבן קנויה ליורשים. \u0003שכן\u0004 \u0003אי אמרת בשלמא קניא להו\u0004 \u0005[נניח אם אתה אומר\u0006 שהיא \u0005קנויה להם],\u0006 \u0003היינו דחד מיהא מימר\u0004 \u0005[זו הסיבה ש\u0006יורש \u0005אחד על כל פנים ממיר].\u0006 \u0003אלא אי אמרת לא קניא להו\u0004 \u0005[אם אתה אומר\u0006 ש\u0005אינה קנויה להם],\u0006 \u0003היכי\u0004 \u0005[כיצד]\u0006 הוא \u0003מימר?\u0004","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו אמר ר' יוחנן\u0004 לענין המפרישים מממונם עבור חובת חבריהם: \u0003המקדיש\u0004 בהמה משלו כדי שיתכפר בה חבירו, ונפל בה מום, אם הוא רוצה לפדותה הוא \u0003מוסיף\u0004 על מחירה \u0003חומש\u0004 (חמישית), כדין כל בעל חפץ שפודה את מה שהקדיש, אבל לא מי שעבורו הקדיש בהמה זו. \u0003ו\u0004מצד אחר, \u0003מתכפר\u0004 כלומר, מי שבשבילו נועד הקרבן — הוא \u0003עושה תמורה. ו\u0004עוד: \u0003התורם\u0004 המפריש תרומה לכהן \u0003מ\u0004תבואתו \u0003שלו על\u0004 תבואתו \u0003של חבירו\u0004 כדי לפוטרו מחובת הפרשה זו — \u0003טובת הנאה\u0004 כל ההנאות הבאות לו מחמת נתינה זו — \u0003שלו\u0004 היא, של נותן התרומה, ולא של בעל התבואה. וממה שאמרו שדווקא המתכפר עושה תמורה, משמע שהקרבן שהפריש האב קנוי ליורשים ומכפר עליהם, שהרי יורש עושה תמורה!","השיב לו רב אשי: \u0003מקיבעא לא מכפרא\u0004 \u0005[מקביעות, אין\u0006 בהמה שהקדיש האב \u0005מכפרת\u0006] על היורשים, שלא לשם כך הוקדשה, ואינה נחשבת קרבנם. ולכן יכולים שני היורשים להביא מנחה של אביהם, כמבואר לעיל. אבל \u0003מקופיא\u0004 \u0005[מלמעלה,\u0006 דרך אגב\u0005]\u0006 \u0003מכפרא\u0004 \u0005[מכפרת]\u0006 על היורשים, ומכח אותה כפרה מסויימת יש ליורש אפשרות להמיר.","במשנה נאמר כי זבחים שנשחטו שלא לשמם — לא עלו לבעלים לשם חובתם, וצריכים הם להביא קרבן אחר לשם כך. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: האם אותם זבחים שנשחטו שלא לשמם \u0003כיפרו על מה שבאו\u0004 לכפר \u0003או לא כיפרו?\u0004","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003לא כיפרו, דאי סלקא דעתך\u0004 \u0005[שאם עולה\u0006 על \u0005דעתך]\u0006 \u0003כיפרו,\u0004 אם כן, קרבן \u0003שני למה הוא בא?\u0004","ודוחים את ההוכחה: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, ש\u0003לא כיפרו?\u0004 אם כן, קרבן ראשון \u0003למה הוא קרב?\u0004","\u0003אמר רב אשי: רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003לא כיפרו,\u0004 מכל מקום \u0003שלא לשמו מכח לשמו קאתי\u0004 \u0005[בא],\u0006 שכיוון שהוקדש מתחילה כראוי לשמו (ולא נפסל) — יש להקריב אותו. \u0003ו\u0004לפיכך, \u0003שני למה הוא בא\u0004 — \u0003לכפר. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שראשונים \u0003כיפרו, שני למה הוא בא?\u0004","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה אחרת, כללית: המביא קרבן עולה, שמכפר על ביטול מצוות עשה, האם גם על מצות \u0003עשה\u0004 ש\u0003לאחר הפרשה\u0004 של הקרבן \u0003מכפרא\u0004 \u0005[מכפרת]\u0006 עולה זו, \u0003או לא מכפרא\u0004 \u0005[מכפרת]?\u0006","והצדדים בשאלה זו: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדבר\u0005]\u0006 ב\u0003חטאת: מה חטאת,\u0004 על החטא שעשה \u0003קודם הפרשה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 היא מכפרת, ש\u0003לאחר הפרשה\u0004 — \u0003לא, אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בעולה, על עבירה ש\u0003קודם הפרשה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לאחר הפרשה\u0004 — \u0003לא.\u0004","\u0003או דלמא לא דמיא\u0004 \u0005[שמא אינה דומה]\u0006 \u0003לחטאת,\u0004 ש\u0003חטאת, על כל חטא וחטא בעי לאיתויי חדא חטאת\u0004 \u0005[צריך להביא חטאת אחת],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 בקרבן עולה, \u0003כיון\u0004 שגם במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כמה\u0004 מצוות \u0003עשה גביה\u0004 \u0005[אצלו]\u0006 \u0003מכפרא\u0004 \u0005[מכפרת]\u0006 עליהן עולה אחת, נאמר כי \u0003על\u0004 \u0003עשה\u0004 ש\u0003לאחר הפרשה נמי מכפרא\u0004 \u0005[גם כן מכפרת]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממדרש ההלכה על הפסוק: \u0003\"וסמך\u0004 ידו על ראש העולה \u0003ונרצה\u0004 לו לכפר עליו\" (ויקרא א, ד), ויש לתמוה: \u0003וכי סמיכה מכפרת? והלא אין כפרה אלא בדם, שנאמר: \"כי הדם הוא בנפש יכפר\"\u0004 (ויקרא יז, יא)! \u0003אלא מה תלמוד לומר \"וסמך... ונרצה לכפר\"?\u0004 לומר \u0003שאם עשאה לסמיכה שירי מצוה\u0004 כלומר, זלזל בה ולא עשאה, \u0003מעלה עליו הכתוב\u0004 כלומר, נחשב לו הדבר \u0003כאילו לא כיפר, ו\u0004בכל זאת \u0003כיפר\u0004 לו קרבן עולה זה.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 צריך להבין כך, ש\u0003כיפר\u0004 כוונתו שכיפר על מצות \u0003עשה\u0004 שביטלה \u0003קודם הפרשה, לא כיפר\u0004 — על ביטול \u0003עשה\u0004 של ה\u0003סמיכה\u0004 עצמה. וטעם הדבר, משום \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003עשה\u0004 ש\u0003לאחר הפרשה?\u0004","\u0003אמר רבא:\u0004 ביטול \u0003עשה\u0004 של \u0003סמיכה קאמרת\u0004 \u0005[אומר אתה]?\u0006 מזה אין להביא ראיה לשאר מצוות עשה שלאחר הפרשה, שכן \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 שגם לאחר ההפרשה, \u0003כל כמה דלא שחיט\u0004 \u0005[שאינו שוחט\u0006 אותו\u0005]\u0006 — \u0003ב\"עמוד וסמוך\" קאי\u0004 \u0005[הוא עומד],\u0006 שהמצוה לסמוך עדיין חלה עליו ולא ביטל אותה, \u0003אימת קא הוי\u0004 \u0005[מתי הוא נעשה\u0006 ביטול מצות\u0005]\u0006 \u0003עשה? לאחר שחיטה,\u0004 ששוב אינו יכול לסמוך. ובעשה שעבר עליו \u0003לאחר שחיטה לא קא מיבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו, שעליו בוודאי אין העולה מכפרת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר יהודה לרבא: אימא\u0004 \u0005[אמור]\u0006 והסבר את הברייתא כך: מה שאמרו \u0003כיפר\u0004 כוונתו כיפר \u0003גברא\u0004 \u0005[האיש]\u0006 שהתכפר לו חטאו בהקרבת הקרבן."],["מה שאמרו \u0003לא כיפר\u0004 — \u0003קמי שמיא\u0004 \u0005[כלפי שמים]\u0006 כלומר, שלא עשה מצוה שלימה, להיות מרוצה בה להקדוש ברוך הוא!","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו]\u0006 כיוצא בזה לגבי טהרת המצורע: \u0003\"והנותר בשמן אשר על כף\u0004 הכהן... יתן על ראש המיטהר \u0003לכפר עליו לפני ה'\"\u0004(ראה ויקרא יד, יח ושם כט), לומר ש\u0003אם נתן\u0004 על ראשו של המיטהר — \u0003כיפר, ואם לא נתן\u0004 — \u0003לא כיפר,\u0004 אלו \u0003דברי ר' עקיבא. ר' יוחנן [בן נורי] אומר:\u0004 מתנות הראש \u0003שירי מצוה הן,\u0004 ולכן \u0003בין ניתן בין שלא ניתן\u0004 — \u0003כיפר,\u0004 אלא שאם לא נתן — \u0003מעלין עליו\u0004 (מחשיבים לו) \u0003כאילו לא כיפר.\u0004","ונברר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כאילו לא כיפר\"? אילימא דמבעי לאיתויי קרבן אחרינא\u0004 \u0005[אם תאמר ש\u0006הוא \u0005צריך להביא קרבן אחר],\u0006 \u0003האמרת\u0004 \u0005[הרי אמרת]:\u0006 \u0003בין ניתן בין לא ניתן כיפר! אלא\u0004 זו הכוונה: \u0003כיפר\u0004 — \u0003גברא\u0004 \u0005[האיש]\u0006 ויצא ידי חובה, \u0003לא כיפר\u0004 — \u0003קמי שמיא\u0004 \u0005[כלפי שמים].\u0006 ולפי זה \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין סמיכה, יש לפרש \u0003כיפר\u0004 ולא כיפר באותה משמעות!","ודוחים: להיפך, \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 צריך לפרש כמו לענין סמיכה: אם לא נתן על הראש \u0003כיפר\u0004 — לענין \u0003מתן בהונות,\u0004 אבל \u0003לא כיפר\u0004 — לענין \u0003מתנות הראש.\u0004 ושבים לדון בשאלה האם קרבן עולה מכפר על עשה שלאחר ההפרשה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו, \u0003ר' שמעון אומר: כבשי עצרת למה הן באין?\u0004","ולפני שמביאים את המשך הדברים, תוהים על עצם השאלה: \u0003כבשי עצרת\u0004 הרי \u0003שלמים נינהו\u0004 \u0005[הם],\u0006 ובאים כחלק מקרבן שני הלחם של עצרת! \u0003אלא\u0004 יש לגרוס כך: \u0003שעירי\u0004 חטאת של \u0003עצרת למה הן באין?\u0004","\u0003על טומאת מקדש וקדשיו,\u0004 שאירעה טומאה במקדש או בקדשים בלי שנודע הדבר.","ואולם יש לשאול: לאחר \u0003ש\u0004\u0003נזרק דמו של\u0004 שעיר \u0003ראשון\u0004 וכיפר על טומאה זו, \u0003שני למה קרב? על טומאה שאורעה בין זה לזה,\u0004 שאם אירע עניין של טומאה כזו לאחר הקרבת השעיר הראשון, מכפר השעיר השני עליה. \u0003אמור מעתה, ראויין היו ישראל להקריב קרבנותיהן בכל עת ובכל שעה\u0004 שמא חטאו בינתיים, \u0003אלא שחיסך הכתוב\u0004 עליהם, ולא חייבם להקריב קרבנות כל הזמן.","ולענייננו: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 שאירעה טומאה בין זה לזה, והשני מכפר, מדובר בכפרה על ביטול מצות \u0003עשה\u0004 (שבהרחקה מן הטומאה) שנעשה \u0003לאחר הפרשה,\u0004 שהרי כבר הופרשו שני השעירים קודם לכן, \u0003וקא מכפרא\u0004 \u0005[והיא מכפרת]!\u0006","ודוחים: \u0003אי דאפרשינהו\u0004 \u0005[אם\u0006 מדובר \u0005שהפרישו אותם]\u0006 את שני השעירים \u0003בבת אחת\u0004 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אכן יש מכאן ראיה. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דאפרשינהו\u0004 \u0005[שהפרישו אותם]\u0006 לא יחד, אלא \u0003בזה אחר זה,\u0004 ור' שמעון מדבר על טומאה שאירעה בין הפרשת שעיר ראשון לבין הפרשת השעיר השני.","ומקשים: \u0003וליקו ולימא ליה לקרא\u0004 \u0005[ו\u0006האם יכולים אנו \u0005לעמוד ולומר לו לַכָּתוּב\u0006] \u0003דכי כתיבא\u0004 \u0005[שכאשר נכתב]\u0006 המקרא, כשהופרשו \u0003בזה אחר זה\u0004 דווקא \u0003כתיבא\u0004 \u0005[\u0006הוא \u0005כתוב]?!\u0006","\u0003אמר רב פפא\u0004 תירוץ אחר: \u0003קרבנות צבור קאמרת\u0004 \u0005[אומר אתה]\u0006 להביא ראיה? \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003קרבנות צבור,\u0004 ש\u0003לב בית דין מתנה עליהן\u0004 והם מחליטים שהפרשת השעיר השני לשם קרבן זה לא תחול עליו אלא רק סמוך להקרבתו, ומשום כך הוא מכפר על טומאה שאירעה עד אותה שעה. והוא \u0003כ\u0004דברי \u0003רב יהודה אמר שמואל,\u0004 ש\u0003אמר רב יהודה אמר שמואל: קרבנות צבור, סכין מושכתן למה שהן\u0004 כלומר, בתוך מעשה השחיטה עצמו הם נקבעים לכל קרבן שהם צריכים לו. אבל אין להוכיח מכאן לעולת יחיד, שתכפר גם על עשה שלאחר הפרשה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל לרב פפא: ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 האם מקבל\u0005]\u0006 \u0003ר' שמעון\u0004 את הסברה ש\u0003לב בית דין מתנה עליהן,\u0004 שאתה מסביר כך את דבריו? \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב אידי בר אבין אמר רב עמרם אמר ר' יצחק אמר ר' יוחנן: תמידין\u0004 כבשים שהופרשו לשם קרבן תמיד, \u0003שלא הוצרכו לצבור,\u0004 ונשארו איפוא קרבנות תמימים (בלא מום) שאין להם שימוש,"],["\u0003לדברי ר' שמעון\u0004 — \u0003אין נפדין תמימים,\u0004 שהרי לא ניתן לפדות בהמה שהוקדשה למזבח והיא תמימה. \u0003לדברי חכמים\u0004 — \u0003נפדין תמימין,\u0004 שכן בית דין מתנה עליהם שאם לא יהא בהם צורך לא יהיו קדושים בקדושת הקרבן!","\u0003ועוד\u0004 ראיה שיש להוכיח מדין כבשי עצרת לענייננו, \u0003הא בעא מיניה\u0004 \u0005[הרי שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא: שעירי עצרת\u0004 שנשחטו בבת אחת \u0003שקבל דמן בשני כוסות ונזרק דמו של ראשון, שני למה הוא בא?\u0004 וענה לו ר' זירא: כדי \u0003לכפר\u0004 \u0003על טומאה שאורעה בין [זריקה של] זה לזה, (נזרק דמו של שני למה הוא קריבין).\u0004","\u0003עד כאן לא מיבעיא ליה\u0004 \u0005[נשאלה לו\u0006 השאלה, לר' ירמיה\u0005]\u0006 \u0003אלא\u0004 לגבי כפרת \u0003עשה\u0004 ש\u0003לאחר שחיטה\u0004 (שעבר עבירה בין זריקה לזריקה), \u0003אבל עשה\u0004 ש\u0003לאחר הפרשה לא קא מיבעיא ליה\u0004 \u0005[נשאלה לו],\u0006 ומשמע שפשוט לו שהוא מכפר!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 שאל גם על עשה שלאחר הפרשה, ובדרך \u0003\"אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\" קאמר\u0004 \u0005[הוא אומר]\u0006 כלומר, ואם מכפר על עשה שלאחר הפרשה, האם מכפר גם על עשה שלאחר שחיטה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 קרבן \u0003תודה ששחטה לשם תודת חבירו, רבה אמר: כשרה\u0004 ועלתה לבעליה, \u0003רב חסדא אמר: פסולה\u0004 ולא עלתה לבעלים.","ומפרטים: \u0003רבה אמר כשרה,\u0004 שהרי \u0003תודה לשם תודה נשחטה. רב חסדא אמר פסולה,\u0004 כי \u0003לשום\u0004 (לשם) \u0003שלמים דידיה\u0004 \u0005[שלו]\u0006 \u0003נשחטה בעינן\u0004 \u0005[צריכים אנו],\u0006 וזו נשחטה לצורך אדם אחר.","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה,\u0006 את שיטתי\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"ובשר זבח תודת שלמיו... ביום הקריבו את\u0004 \u0003זבחו\" וגו'\u0004 (ראה ויקרא ז, טו-טז), \u0003אבא חנין אמר משום\u0004 (בשם) \u0003ר' אליעזר: בא ללמד\u0004 שתודה \u0003ששחטה לשם שלמים\u0004 — \u0003כשרה, שלמים שנשחטו לשם תודה\u0004 — \u0003פסולים. ומה הפרש בין זה לזה? תודה קרויה שלמים\u0004 שהיא חלק מקרבנות השלמים, \u0003ואין שלמים קרויין תודה.\u0004","ונדייק מכאן: דווקא אם שחט \u0003שלמים לשם תודה\u0004 — \u0003פסולה, הא\u0004 \u0005[אבל]\u0006 אם הקריב \u0003תודה לשם תודה\u0004 — \u0003כשרה, מאי לאו דחבריה\u0004 \u0005[האם לא\u0006 מדובר לשם תודה \u0005של חבירו]?\u0006","ודוחים: \u0003לא,\u0004 דווקא אם הקריב לשם תודה \u0003דידיה\u0004 \u0005[שלו],\u0006 וכגון שהפריש קרבן תודה על נס אחר שאירע לו.","ושואלים: \u0003אבל דחבריה מאי\u0004 \u0005[\u0006לשם תודה \u0005של חבירו מה\u0006 אתה אומר\u0005],\u0006 שהיא תהיה \u0003פסולה? אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 בקטע הבא: \u0003שלמים לשם תודה\u0004 — \u0003פסולה, ליתני\u0004 \u0005[שישנה]:\u0006 \u0003תודה לשם תודה\u0004 של חבירו פסולה, \u0003וכל שכן שלמים לשם תודה!\u0004","ומשיבים: \u0003שלמים לשם תודה דידיה\u0004 \u0005[שלו]\u0006 \u0003איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, מפני שיש בכך חידוש: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003מ\u0004כיון ש\u0003תודה קרויה שלמים\u0004 — \u0003שלמים נמי\u0004 \u0005[גם כן]\u0006 \u0003קרויין תודה, וכי שחיט להו\u0004 \u0005[וכאשר\u0006 הוא \u0005שוחט אותם]\u0006 \u0003לשם תודה ליכשרו\u0004 \u0005[\u0006יהיו \u0005כשרים],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא.","\u0003אמר רבא: חטאת ששחטה לשם חטאת,\u0004 אף על פי ששחטה לשם חטא אחר שחטא, ולא לשם זה שהפרישה עבורו — \u0003כשירה.\u0004 אבל אם שחטה \u0003לשם עולה\u0004 — \u0003פסולה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"ושחט אותה לחטאת\"\u0004 (ויקרא ד, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003והרי חטאת לשם חטאת נשחטה.\u0004 אבל אם שחטה \u0003לשם עולה\u0004 — \u0003פסולה,\u0004 שהרי שלא לשם חטאת שחטה.","\u0003ואמר רבא: חטאת ששחטה על מי שמחוייב חטאת\u0004 — \u0003פסולה, על מי שמחוייב עולה,\u0004 שקיבל על עצמו להביא קרבן עולה — \u0003כשרה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 נאמר בחטאת: \u0003\"וכפר עליו\"\u0004 (ויקרא ד, כו), ויש לדייק: \u0003עליו ולא על חבירו,\u0004 ודינו כשוחט חטאת שלא לשמה. אבל אין דיוק זה מלמד אלא כש\u0003חבירו דומיא דידיה\u0004 \u0005[בדומה לו],\u0006 \u0003במחוייב כפרה כמותו,\u0004 ואם אינו מחוייב כפרה בהבאת חטאת — אין דין זה חל.","\u0003ואמר רבא: חטאת ששחטה על מי שאינו מחוייב כלום\u0004 שאמר שהוא שוחט אותה לשם אדם שאינו מחוייב כלום — \u0003פסולה,\u0004 ומדוע? \u0003שאין לך אדם בישראל שאינו מחוייב\u0004 על ביטול מצות \u0003עשה.\u0004","\u0003ו\u0004כיוצא בזה \u0003אמר רבא: חטאת מכפרת על חייבי עשה מקל וחומר,\u0004 ומהו הקל וחומר? ומה אם \u0003על חייבי כריתות\u0004 שהם חמורים \u0003מכפרת\u0004 החטאת, \u0003על חייבי עשה\u0004 שהוא חטא חמור פחות \u0003לא כל שכן?\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שמצות עשה \u0003בת מינה\u0004 של חטאת \u0003היא? והאמר\u0004 \u0005[והרי\u0006 \u0003אמר]\u0004 \u0003רבא\u0004 לעיל: \u0003חטאת ששחטה על מי שמחוייב חטאת\u0004 — \u0003פסולה, על מי שמחוייב עולה\u0004 — \u0003כשרה,\u0004 משום שאינו מחוייב כפרה כמותו. והרי מביאים קרבן עולה כדי לכפר על מצות עשה!"],["ומשיבים: \u0003מקיבעא לא מכפרא\u0004 \u0005[\u0006כפרה שהיא \u0005מקביעות אין\u0006 חטאת \u0005מכפרת]\u0006 על מצוות עשה, \u0003אבל\u0004 \u0003מקופיא מכפרא\u0004 \u0005[\u0006כפרה שהיא \u0005דרך אגב מכפרת].\u0006","\u0003ואמר רבא: עולה ששחטה שלא לשמה\u0004 — \u0003אסור לזרוק דמה שלא לשמה.\u0004","\u0003איבעית אימא קרא, איבעית אימא סברא\u0004 \u0005[אם תרצה אמור מן המקרא,\u0006 \u0005אם תרצה אמור סברה].\u0006 ומפרטים: \u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור מן המקרא],\u0006 כמו שדרשו חכמים לעיל (זבחים ב,ב) דבר זה מן הכתוב: \u0003\"מוצא שפתיך תשמר\u0004 ועשית כאשר נדרת לה' אלקיך נדבה אשר דברת בפיך\" וגו' (דברים כג, כד). \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה]:\u0006 וכי \u0003משום דשני\u0004 \u0005[ששינה]\u0006 \u0003בה\u0004 ועשה שלא כראוי פעם אחת, יחזור וישנה בה? \u0003כדריש פירקא\u0004 \u0005[כמו\u0006 שנאמר \u0005בתחילת הפרק\u0006 שבמסכת זו\u0005]\u0006 (ב,א).","\u0003ואמר רבא: עולה הבאה לאחר מיתה\u0004 של המפריש, שהיורשים מקריבים אותה, אם \u0003שחטה\u0004 הכהן \u0003בשינוי קודש\u0004 כלומר, לשם קרבן אחר — הרי היא \u0003פסולה\u0004 שלא עלתה לבעליה, וצריך היורש להביא קרבן נוסף לחובתו. אבל אם שחטה \u0003בשינוי בעלים\u0004 — \u0003כשרה,\u0004 שאין היורש צריך להביא קרבן אחר, ומדוע? ש\u0003אין בעלים לאחר מיתה.\u0004","\u0003ורב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי אמר: יש בעלים לאחר מיתה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: דוקא קאמר מר\u0004 \u0005[האם בדיוק,\u0006 בהחלט \u0005אומר אדוני]\u0006 ש\u0003יש בעלים לאחר מיתה,\u0004 בניגוד לדברי רבא, \u0003ובעי לאיתויי\u0004 \u0005[וצריך להביא]\u0006 היורש \u0003עולה אחריתי\u0004 \u0005[אחרת]\u0006 אם שינה הבעלים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה רק לומר \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003כמה\u0004 מצוות \u0003עשה גביה\u0004 \u0005[אצלו]\u0006 שעבר היורש עליהן \u0003מכפרא\u0004 \u0005[מכפרת]\u0006 העולה, אבל אין זה מחייב להביא קרבן נוסף אם שינה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ב\u0003דוקא קאמינא\u0004 \u0005[אני אומר],\u0006 שלדעתי חובה על היורשים להביא אחר.","","\u0003ואמר רבא: עולה\u0004 — \u0003דורון\u0004 (מתנה) \u0003היא\u0004 למקום, ולא קרבן שבא לכפרה. והוא מוכיח את דבריו כך: שהרי \u0003היכי\u0004 \u0003דמי\u0004 \u0005[באיזה\u0006 מקרה \u0005מדובר]?\u0006 \u0003אי דליכא\u0004 \u0005[אם שאין\u0006 בידו\u0005]\u0006 \u0003תשובה,\u0004 שעבר על מצוות עשה ולא חזר בתשובה \u0003—\u0004 אסור לקבל ממנו את קרבנו, שהרי נאמר \u0003\"זבח רשעים תועבה\"\u0004 (משלי כא, כז)! \u0003ואי דאיכא\u0004 \u0005[ואם שיש]\u0006 \u0003תשובה\u0004 שכבר שב על עוונותיו — \u0003התניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003עבר על מצות עשה ושב, לא זז משם עד שמוחלים לו,\u0004 וכיון שמוחלים לו למה מביא קרבן? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003דורון הוא\u0004 שמביא כדי להתרצות לקונו. (חטא\"ת ע\"ל מ\"י מכפ\"ר עול\"ה לאח\"ר דורו\"ן, סימ\"ן).","","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 שזהו עניינו של קרבן עולה, \u0003אמר ר' שמעון: חטאת למה באה?\u0004 ותוהים: \u0003למה באה?\u0004 הרי באה \u0003לכפר! אלא למה באה\u0004 החטאת \u0003לפני עולה?\u0004 הרי זה דומה \u0003לפרקליט\u0004 (עורך דין, סניגור) \u0003שנכנס\u0004 אל המלך, כדי לדבר בזכותו של נאשם כדי שיימחל לו עוונו, ולאחר \u0003[\u0004ש\u0003ריצה פרקליט, נכנס] דורון אחריו.\u0004","שנינו במשנה כי כל הקרבנות שנשחטו שלא לשמן כשרים אלא שלא עלו לבעלים, \u0003חוץ מן הפסח והחטאת,\u0004 שאם נשחטו שלא לשמם — פסולים לגמרי. ושואלים: \u0003פסח מנלן\u0004 \u0005[מנין לנו]\u0006 שצריך שיישחט לשמו?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שמור את חדש האביב ועשית פסח\u0004 לה' אלקיך\" (דברים טז, א), לומר \u0003שיהו כל עשיותיו לשם פסח.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ש\u0003שינוי קודש\u0004 פוסל בו, \u0003שינוי בעלים מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואמרתם זבח פסח הוא\"\u0004 (שמות יב, כז), לומר \u0003שתהא זביחה לשם פסח.\u0004 ו\u0003אם\u0004 כתוב זה \u0003אינו ענין לשינוי קודש,\u0004 שכבר למדנו מכתוב אחר, \u0003תניהו ענין לשינוי בעלים.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא מקור \u0003למצוה\u0004 כלומר, שלכתחילה יש לעשותו לשמו ולשם בעליו, אבל \u0003לעכב מנלן\u0004 \u0005[מנין לנו]\u0006 שאם שינה פסל?","\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"וזבחת פסח לה'\u0004 \u0003אלהיך\" וגו'\u0004 (דברים טז, ב), והחזרה על הציווי באה ללמדנו שדבר זה מעכב בקרבן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ספרא: האי\u0004 \u0005[זה]\u0006 הפסוק \u0003\"וזבחת\" להכי\u0004 \u0005[לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו]\u0006 \u0003לכ\u0004 דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: מנין למותר פסח\u0004 קרבן שהוקדש לשם פסח ולא הוקרב, \u0003שקרב שלמים\u0004 לאחר הפסח? \u0003שנאמר: \"וזבחת פסח לה' אלהיך צאן ובקר\"\u0004 (דברים טז, ב), ויש לתמוה: כיצד נאמר בקר? \u0003והלא אין פסח בא אלא מן הכבשים ומן העזים!\u0004 אלא \u0003מכאן למותר הפסח שיהא\u0004 ראוי \u0003לדבר\u0004 (לקרבן) \u0003הבא\u0004 הן \u0003מן הצאן ו\u0004הן \u0003מן הבקר, ומאי ניהו\u0004 \u0005[ומה\u0006 הוא \u0005זה]?\u0006 קרבן \u0003שלמים!\u0004","\u0003אלא אמר רב ספרא\u0004 כך נדרשים הפסוקים שהובאו לעיל: מה שנאמר \u0003\"וזבחת פסח\"\u0004 אכן בא ללמד \u0003לכ\u0004 דברי \u0003רב נחמן,\u0004 למותר הפסח. מה שנאמר \u0003\"שמור את חדש\u0004 \u0003האביב\u0004 ועשית פסח\" (דברים טז, א) — \u0003למצוה בשינוי קודש\u0004 שמצוה לשוחטו לשמו. ומה שנאמר: \u0003\"ואמרתם זבח פסח\"\u0004 (שמות יב, כז), אם אינו ענין לשינוי קודש — תנהו \u0003ל\u0004\u0003שינוי בעלים למצוה.\u0004 ומה שנאמר באותו כתוב \u0003\"הוא\"\u0004 — הרי זה להדגשה, שלא ישנהו ממה שהוא, ובא \u0003לעכב\u0004 (ולפסול בדיעבד) \u0003בין הכא\u0004 \u0005[כאן]\u0006 בשינוי קודש \u0003ו\u0004בין \u0003הכא\u0004 \u0005[כאן]\u0006 בשינוי בעלים.","ושואלים: \u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 איפוא \u0003זביחה\u0004 שנזכרה במפורש בפסוקים אלה, \u0003שאר עבודות מנלן\u0004 \u0005[מנין לנו]\u0006 שגם בהן הדין כן? ומשיבים: \u0003הואיל וגלי גלי\u0004 \u0005[וגילה גילה]\u0006 כיון שגילה הכתוב שהיא לעיכוב, שכל שינוי בזביחה פוסל, אנו למדים שכן היא גם בשאר עבודות.","\u0003רב אשי אמר:\u0004 דרך זו של \u0003\"הואיל וגלי גלי\" לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ואין זו ראיה. \u0003אלא [\u0004שאר \u0003עבודות] מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת התורה לעולה ולמנחה\u0004 ולחטאת ולאשם ולמלואים ולזבח השלמים\" וגו' (ויקרא ז, לז), ובפסוק זה הוקשו כל הקרבנות לשלמים לענין שייעשו לשמם (לעיל זבחים ד,ב).","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 על הכתוב הסמוך: \u0003\"ביום צותו את בני ישראל להקריב את קרבניהם\"\u0004 (ויקרא ז, לח) — \"קרבניהם\" \u0003זה בכור ומעשר ופסח,\u0004 שלא נזכרו בפסוק הקודם, וכאן","\u0003הקישו הכתוב\u0004 יחד עם שאר כל הקרבנות \u0003לשלמים: מה שלמים בין שינוי קודש בין שינוי בעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003למצוה, אף כל\u0004 הקרבנות, \u0003בין שינוי קודש בין\u0004 \u0003שינוי בעלים למצוה. ו\u0004מאחר שהיקשנו את הפסח לשלמים — יש ללמוד מהיקש זה דין נוסף שבו יהא דין הפסח \u0003כשלמים: מה שלמים בין זביחה בין שאר עבודות לא חלקת בהן למצוה,\u0004 שבכולן מצוה לעשותם לשמם, \u0003אף פסח לא תחלוק בו בין זביחה לשאר עבודות,\u0004 וכמו בזביחה — כך בשאר העבודות, הציווי אינו רק למצוה אלא \u0003לעכב. (משום שנאמר \"הוא\" בזביחה אינו אלא לעכב).\u0004","ושואלים: \u0003אלא\u0004 כיוון שהדבר נלמד מן ההיקש, המלה \u0003\"הוא\" למה לי?\u0004 ומשיבים: להדגיש שדווקא בפסח הדין כן, ולא בקרבן אשם.","","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נאמר בפסח \"הוא\" בשחיטה\u0004 (\"זבח פסח הוא\") ולכן הרי זה \u0003לעכב, אבל אשם לא נאמר בו\u0004 המלה \u0003\"הוא\" אלא לאחר הקטרת אימורין,\u0004 וכיון ש\u0003הוא עצמו\u0004 אשם \u0003שלא הוקטרו אימוריו כשר\u0004 — אין \"הוא\" האמור בזה לעכב כלל.","ושואלים: \u0003חטאת מנלן\u0004 \u0005[מנין לנו]\u0006 שאם משנה בה פוסל אותה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושחט אתה לחטאת\"\u0004 (ויקרא ד, לג), \u0003שתהא שחיטה לשם חטאת.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה ב\u0003שחיטה, קבלה מנלן\u0004 \u0005[מנין לנו]\u0006 שצריכה להיות לשם חטאת? ומשיבים: ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"ולקח הכהן מדם החטאת\"\u0004 (ויקרא ד, כה), לומר \u0003שתהא קבלה לשם חטאת.\u0004","\u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 איפוא מקור ש\u0003שחיטה וקבלה\u0004 צריכות להיות לשמן, \u0003זריקה מנלן\u0004 \u0005[מנין לנו]\u0006 שאף היא צריכה להיות לשמה? ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכפר עליו הכהן מחטאתו\"\u0004 (ויקרא ד, כו), ללמד \u0003שתהא כפרה לשם חטאת,\u0004 וזריקת הדם היא המכפרת.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא \u0003שנוי קדש, שנוי בעלים מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שם: \"וכפר \u0003עליו\",\u0004 ללמד: \u0003עליו ולא על חבירו.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003למצוה\u0004 שלכתחילה צריך לזרוק לשם הבעלים, \u0003לעכב מנלן\u0004 \u0005[מנין לנו]\u0006 שאם שינה — פסל? ומשיבים: \u0003כ\u0004מו \u0003ש\u0004\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 להלן, בענין חטאת נזיר, שהיה יכול לכתוב \u0003\"חטאת\"\u0004 וכתב \u0003\"חטאתו\"\u0004 להדגיש — דווקא זו שנעשתה לשמו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לדרוש \u0003\"חטאת\" \"חטאתו\"\u0004 שאם זרק שלא לשמו — פסול.","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא \u0003שיש\u0004 \u0003מצוה בשנוי קדש, וזריקה בשנוי בעלים בין למצוה בין לעכב.\u0004 \u0003לעכב בכל עבודות בשנוי קדש, ובשאר עבודות\u0004 (חוץ מזריקה) \u0003בשנוי בעלים, בין למצוה בין לעכב מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003אמר ר' יונה: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 \u0003מחטאת נזיר, דכתיב\u0004 \u0005[שנאמר]\u0006 בחטאת נזיר: \u0003\"והקריב הכהן לפני ה' ועשה את חטאתו ואת עלתו\"\u0004 (במדבר ו, טז), לומר \u0003שיהו כל עשיותיו לשם חטאת.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא פסוק נוסף שהוא לעכב בענין \u0003שנוי קדש. שנוי בעלים\u0004 בשאר עבודות חוץ מזריקה, בין למצוה ובין לעכב, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003(אם אינו ענין לשנוי קדש, תניהו ענין לשנוי בעלים. אשכחן למצוה, לעכב מנלן?)\u0004","\u0003אמר רב הונא [בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:]\u0004 היה יכול לומר בענין זה \u0003\"חטאת\"\u0004 ואמר \u0003\"חטאתו\",\u0004 הרי זה בא להדגיש — חטאתו שלו ולא של אחר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: אלא מעתה,\u0004 מה שיכול היה לכתוב באותו פסוק עצמו \u0003\"עולת\"\u0004 וכתב \u0003\"עולתו\" מאי דרשת ביה\u0004 \u0005[מה אתה דורש בו]?\u0006","ולעצם שאלתו של רבינא, שואלים: \u0003ולרבינא,\u0004 מדוע לא שאל גם על מה שנאמר בפסוק הסמוך: \"ועשה הכהן את מנחתו ואת נסכו\" (במדבר ו, יז), שהיה יכול לכתוב \u0003\"מנחת\"\u0004 ונכתב \u0003\"מנחתו\",\u0004 וכן \u0003\"נסך\"\u0004 ונכתב \u0003\"נסכו\", מאי דרשת בהו\u0004 \u0005[מה אתה דורש בהם]?\u0006","ומשיבים: \u0003ההוא\u0004 \"את מנחתו ואת נסכו\" \u0003מבעי ליה\u0004 \u0005[נצרך לו]\u0006 לכמו שלמדנו מן הכתוב \u0003\"מנחתם ונסכיהם\"\u0004 (במדבר כט, לז) שהמנחה והנסכים של קרבנות המועדים קריבים אפילו \u0003בלילה\u0004 אחרי יום הקרבת הקרבן, \u0003\"מנחתם ונסכיהם\"\u0004 — \u0003אפילו למחר,\u0004 לומר שגם מנחתו ונסכו של הנזיר כשרים להקריבם בלילה ולמחר. \u0003אלא \"עולת\" \"עולתו\"\u0004 שאין לו הסבר אחר, \u0003מאי דרשת בהו\u0004 \u0005[מה אתה דורש בהם]?\u0006","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות על הסברו של ר' יונה, שלמד דין שינוי בחטאת מחטאת נזיר: \u0003מי גמרי מהדדי\u0004 \u0005[האם\u0006 הם \u0005לומדות זו מזו]?\u0006 \u0003חטאת חלב\u0004 כלומר, חטאת שבא על חטא, כמו על אכילת חלב, \u0003מחטאת נזיר לא גמרה\u0004 \u0005[אינה לומדת],\u0006 מפני שחטאת נזיר חמורה יותר, \u0003שכן יש עמה דמים אחרים\u0004 שהנזיר צריך להביא גם עולה ואשם. ולהיפך, גם \u0003חטאת נזיר מחטאת חלב לא גמרה\u0004 \u0005[אינה לומדת]\u0006 \u0003שכן\u0004 חטאת חלב מכפרת על עבירה שיש בה \u0003כרת!\u0004","\u0003אלא אמר רבא: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה בחטאת חלב \u0003מחטאת מצורע, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשה הכהן את החטאת\"\u0004 (ויקרא יד, יט), לומר \u0003שיהו כל\u0004 \u0003עשיותיו לשם חטאת.\u0004","\u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 איפוא \u0003שנוי קדש, שנוי בעלים מנליה\u0004 \u0005[מנין לו]\u0006 שהוא מעכב? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"וכפר על המטהר\" וגו'\u0004 (ויקרא יד, יט), לומר: \u0003על המטהר\u0004 ה\u0003זה ולא על המטהר חבירו.\u0004","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 יש לשאול אותה שאלה עצמה שנשאלה על שיטת ר' יונה: \u0003מי ילפא מהדדי\u0004 \u0005[האם לומדת זו מזו]?\u0006 \u0003חטאת חלב מחטאת מצורע לא ילפא\u0004 \u0005[אינה לומדת],\u0006 \u0003שכן יש עמה\u0004 בחטאת מצורע גם \u0003דמים אחרים\u0004 דם עולה ודם אשם, \u0003חטאת מצורע מחטאת חלב לא גמרה\u0004 \u0005[אינה לומדת],\u0006 \u0003שכן\u0004 יש בה כפרת \u0003כרת!\u0004","ומשיבים: אמנם, \u0003מחדא לא אתיא\u0004 \u0005[\u0006חטאת אחת \u0005מ\u0006חטאת \u0005אחת אינה באה,\u0006 אינה נלמדת\u0003],\u0004 אבל \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד, \u0005אחת\u0006 מן החטאות \u0005משתים\u0006 אחרות\u0005].\u0006","ושואלים: \u0003בהי\u0004 \u0005[באיזו]\u0006 מהן \u0003לא לכתוב\u0004 \u0005[תכתוב]\u0006 התורה? אם תאמר \u0003[לא לכתוב] רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בחטאת חלב ותיתי מהנך\u0004 \u0005[ותבוא\u0006 ותילמד \u0005מאלה\u0006 האחרות\u0005]\u0006 — \u0003מה להנך\u0004 \u0005[לאחרות]\u0006 חטאת נזיר וחטאת מצורע \u0003שכן יש עמהם דמים אחרים!\u0004","ואם תאמר: \u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בחטאת נזיר ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה\u0006 האחרות\u0005]\u0006 — \u0003מה להנך\u0004 \u0005[לאחרות]\u0006 \u0003שכן אין להן שאלה,\u0004 שהחוטא והמצורע חייב להביא חטאתו בכל מקרה, מה שאין כן בנזיר שיכול להישאל על נדר הנזירות ולבטל את החובה!","ואם תאמר: \u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בחטאת מצורע ותיתי מהנך\u0004 \u0005[ותבוא מאלה\u0006 האחרות\u0005],\u0006 אפשר לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן אין באין בדלות\u0004 כמו בחטאת מצורע שיש בה הפרש בין עני ועשיר (ראה ויקרא יד, כא), אלא יש להן קצבה קבועה!","\u0003אלא\u0004 לא ניתן ללמוד מן החטאות עצמן זו על זו, ויש לומר באופן אחר: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זאת התורה לעלה ולמנחה\u0004 ולחטאת... ולזבח השלמים\" וגו' (ויקרא ז, לז), \u0003הקישו הכתוב\u0004 את החטאת \u0003לשלמים, מה שלמים\u0004 — \u0003בין שנוי קדש בין שנוי בעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003לשמן למצוה, אף חטאת\u0004 — \u0003בין שנוי קדש בין שנוי בעלים בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003לשמן למצוה.\u0004","\u0003הילכך\u0004 \u0005[על כן],\u0006 לענין \u0003מצוה\u0004 למדים \u0003משלמים, והנך קראי\u0004 \u0005[ו\u0006אלו \u0005הכתובים\u0006 האחרים\u0005]\u0006 שהבאנו לגבי חטאת, כל אחת לגופה, באים ללמד שהוא גם \u0003לעכב.\u0004","ושואלים: \u0003ואשכחן\u0004 \u0005[ומצאנו]\u0006 איפוא דין זה לגבי \u0003חטאת חלב, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"לחטאת\"\u0004 (ויקרא ד, לג),"],["\u0003חטאת\u0004 של \u0003עבודה זרה,\u0004 שנתייחד לה מקום ופרטי דינים מיוחדים בספר במדבר (טו, כז— לא), או חטאת של \u0003שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו,\u0004 שגם להן דינים מיוחדים הכתובים לעצמם (ויקרא ה, א— יג) ש\u0003לא כתיב בהו\u0004 \u0005[נאמר בהן]\u0006 דבר זה, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שפסולות שלא לשמן? ומשיבים: \u0003חטאת\u0004 של \u0003עבודה זרה אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 \u0003מחטאת חלב, שכן\u0004 היא באה לכפר על חיוב \u0003כרת כמותה, והנך כולהי אתיין\u0004 \u0005[וכל אותן\u0006 האחרות \u0005באות,\u0006 נלמדות\u0005]\u0006 \u0003ב\u0004שיטת הלימוד של \u0003מה הצד,\u0004 מחטאת חלב ומחטאת של נזיר ושל מצורע.","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 קרבן \u0003פסח בזמנו\u0004 כלומר, בזמן מצוותו, בארבעה עשר בניסן אחר הצהרים, אם שחטו \u0003לשמו\u0004 — \u0003כשר,\u0004 שחטו \u0003שלא לשמו\u0004 — \u0003פסול,\u0004 כאמור במשנה. וקרבן שהקדיש לשם פסח, אם שחטו \u0003בשאר ימות השנה\u0004 \u0003לשמו\u0004 כלומר, לשם פסח — הרי הוא \u0003פסול,\u0004 שחטו \u0003שלא לשמו\u0004 — \u0003כשר.\u0004","","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שבשאר ימות השנה, אם שחטו שלא לשמו כשר? \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל, אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת השלמים: \u0003\"ואם מן הצאן קרבנו לזבח שלמים לה'\"\u0004 (ויקרא ג, ו), לומר: \u0003דבר\u0004 (קרבן) \u0003הבא מן הצאן\u0004 בלבד, שהוא קרבן הפסח, אם אינו ראוי לפסח — \u0003יהא לזבח שלמים.\u0004","ומקשים: אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 כששחטו לשם \u0003שלמים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם שחטו לשם \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא! אמר ר' אילא אמר ר' יוחנן:\u0004 יכול היה להיאמר \"לשלמים\", ונאמר \u0003\"לזבח\"\u0004 — \u0003לרבות כל זבח.\u0004 ושואלים: אם כן, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003כל\u0004 מה \u0003דשחיט\u0004 \u0005[ששוחט]\u0006 את הפסח לשמו \u0003להוי\u0004 \u0005[שיהיה]\u0006 \u0003כמותה,\u0004 כגון אם שחטו לשם עולה — שיהא עולה, ולא יהיה שלמים!","","ומשיבים: \u0003אי הוה כתיב\u0004 \u0005[אם היה כתוב]\u0006 \u0003\"לשלמים וזבח\"\u0004 — היינו צריכים לפרש \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"לזבח שלמים\",\u0004 הרי זה לומר: \u0003לכל\u0004 דבר \u0003דשחיט ליה\u0004 \u0005[ששוחט אותו]\u0006 — \u0003שלמים להוי\u0004 \u0005[יהיה].\u0006 ומקשים: מדוע נלמד כך?","\u0003אימא\u0004 \u0005[אמור]\u0006 באופן אחר: \u0003\"לזבח\"\u0004 — הרי זה \u0003כלל, \"שלמים\"\u0004 — \u0003פרט,\u0004 והרי זה \u0003כלל ופרט,\u0004 ולפי כללי מדרש ההלכה: \u0003אין בכלל אלא מה שבפרט,\u0004 אם נשחט לשם \u0003שלמים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[\u0006לשם \u0005דבר אחר]\u0006 — \u0003לא,\u0004 והוא פסול!","ומשיבים: מה שנאמר \u0003\"לה'\"\u0004— \u0003הדר\u0004 \u0005[חזר]\u0006 \u0003וכלל,\u0004 והרי זה כלל ופרט וכלל, והרחיב את הפרט לכל שהוא כעין שלמים, דהיינו כל מיני הקרבנות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' יעקב מנהר פקוד:\u0004 כיצד יכול אתה ללמוד כאן במידת כלל ופרט וכלל? \u0003הא לא דמי כללא בתרא לכללא קמא\u0004 \u0005[הרי אינו דומה הכלל האחרון לכלל הראשון],\u0006 שהרי \u0003כללא קמא\u0004 \u0005[הכלל\u0006 \u0003הראשון]\u0004 \u0003מרבי\u0004 \u0005[מרבה]\u0006 \u0003זבחים ותו לא\u0004 \u0005[ולא יותר],\u0006 שהרי נאמר \"לזבח\", ואילו \u0003כללא בתרא\u0004 \u0005[הכלל\u0006 \u0003האחרון]\u0004 שהוא אומר \u0003\"לה'\",\u0004 כוונתו \u0003כל\u0004 דבר שהוא \u0003לה', ואפילו\u0004 שחט את הפסח \u0003ל\u0004שם \u0003עופות ואפילו למנחות!\u0004","ומשיבים: \u0003הא תנא דבי\u0004 \u0005[הרי התנא\u0006 מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל בכללי ופרטי דריש כי האי גוונא\u0004 \u0005[בכללים ופרטים\u0006 הוא \u0005דורש כעין זה]\u0006 וכך היא השיטה:","\u0003כלל ופרט וכלל אי\u0004 \u0005[אין]\u0006 \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש, שהוא\u0004 פסח שנשחט \u0003שלא לשמו\u0004 אלא לשם שלמים \u0003וכשר, אף כל\u0004 קרבן פסח שנשחט לשם כל קרבן אחר \u0003שלא לשמו וכשר.\u0004 ומקשים: \u0003אי\u0004 (או) נאמר, \u0003מה הפרט מפורש דבר הבא בנדר ובנדבה\u0004 שהוא שלמים, \u0003אף כל\u0004 דבר \u0003הבא בנדר ובנדבה,\u0004 ולפי זה: דווקא אם שחטו לשם \u0003עולה ושלמים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם שחטו לשם \u0003חטאת ואשם\u0004 שהם באים חובה ולא נדבה — \u0003לא!\u0004 \u0003אלא\u0004 צריך לומר באופן אחר: אין כאן דרשת כלל ופרט וכלל, אלא לשון \u0003\"לזבח\" רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 והיא באה לרבות כל דבר.","","","ומקשים, ועדיין \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003לכל\u0004 דבר \u0003דשחיט ליה להוי כוותיה\u0004 \u0005[ש\u0006הוא \u0005שוחט אותו\u0006 לשמו \u0005שיהיה כמותו],\u0006 ושייעשה הפסח הזה חטאת או אשם \u0005וכיוצא בו!\u0006 \u0003אמר ר' אבין:\u0004",""],["\u0003דוחין קדשים הנאכלים\u0004 כלומר, קרבן הפסח שהוא קודש העומד לאכילה, כששחטו שלא לשמו — יידחה \u0003אצל קדשים\u0004 אחרים \u0003הנאכלין\u0004 גם הם, דהיינו שלמים, \u0003ואין דוחין קדשים הנאכלין אצל קדשים שאינן נאכלין,\u0004 דהיינו עולה.","ומקשים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חטאת ואשם מי לא מיתאכלי\u0004 \u0005[האם אינם נאכלים]?\u0006 ואם כן מדוע ייעשה שלמים?","\u0003אלא\u0004 כך צריך לומר: \u0003דוחין\u0004 פסח שהוא \u0003קדשים הנאכלין לכל אדם\u0004 מישראל \u0003אצל\u0004 שלמים שהם \u0003קדשים הנאכלין לכל אדם, ואין דוחין קדשים הנאכלין לכל אדם אצל קדשים שאין נאכלין לכל אדם,\u0004 לפי שחטאת או אשם אוכלים רק הכהנים.","\u0003ר' יוסי בר' אבין אמר\u0004 באופן אחר: \u0003דוחין קדשים קלים אצל קדשים קלים\u0004 כשלמים, \u0003ואין דוחין קדשים קלים אצל קדשי קדשים,\u0004 שהם עולה חטאת ואשם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יצחק בר' סבריו,\u0004 אם זהו טעמו של דבר, \u0003אימא\u0004 \u0005[אמור]\u0006 משום כך: אם \u0003שחטיה\u0004 \u0005[שחט אותו]\u0006 את הפסח \u0003לשם מעשר ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003מעשר,\u0004 שהרי מעשר בכלל קדשים קלים הוא. ומסבירים: \u0003למאי הילכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 יהיה מעשר, כלומר מה ההבדל אם הוא שלמים או מעשר? ש\u0003לא ליבעי\u0004 \u0005[יצטרך]\u0006 להביא עמו \u0003נסכים,\u0004 כדין \u0003מעשר,\u0004 \u0003ו\u0004כן \u0003למלקא עליה\u0004 \u0005[ללקות עליו]\u0006 \u0003(ב\"לא ימכר\") ב\"לא יגאל\"\u0004 (ויקרא כז, לג), שמעשר אי אפשר למוכרו כלל, גם לא לאחר שחיטה!","ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"העשירי יהיה קדש\"\u0004 (ויקרא כז, לב), לומר: \u0003זה\u0004 העשירי בלבד \u0003מעשר\u0004 הוא, \u0003ואין אחר\u0004 שנשחט לשמו נחשב ל\u0003מעשר.\u0004","ומקשים: ועדיין \u0003אימא\u0004 \u0005[אמור]\u0006 כך: אם \u0003שחטיה\u0004 \u0005[שחט אותו]\u0006 את הפסח \u0003לשם בכור\u0004 — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003כבכור, למאי הילכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 למעשה? ש\u0003לא ליבעי\u0004 \u0005[יצטרך]\u0006 \u0003נסכים\u0004 כמו שלמים, \u0003אי נמי דליתביה\u0004 \u0005[או גם כן שיתן אותו]\u0006 \u0003לכהנים\u0004 כבכור!","ומשיבים: \u0003בכור נמי\u0004 \u0005[גם כן]\u0006 בגזירה שווה של \u0003\"עברה\" \"עברה\" ממעשר גמר\u0004 \u0005[למד],\u0006 ולכן כמו המעשר אי אפשר לגרום לבהמה סתם שיהא דינה כבכור.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: אם \u0003שחטיה\u0004 \u0005[שחט אותו]\u0006 את הפסח \u0003לשם תמורה\u0004 — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003תמורה, למאי הילכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 למעשה? \u0003למלקא עליה\u0004 \u0005[ללקות עליו]\u0006 משום שעבר ועשה תמורה. \u0003אי נמי למיקם עליה\u0004 \u0005[או גם כן להיות\u0006 אסור \u0005עליו]\u0006 \u0003ב\"לא ימכר ולא יגאל\"\u0004 (ויקרא כז, לב)!","\u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"והיה הוא ותמורתו\"\u0004 (ויקרא כז, לג), \u0003זו\u0004 הבהמה שהמירו בה היא נעשית \u0003תמורה, ואין\u0004 דבר \u0003אחר\u0004 שנשחט לשם תמורה נעשה \u0003תמורה.\u0004","ושואלים עוד, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 אם \u0003שחטיה\u0004 \u0005[שחטו]\u0006 את הפסח \u0003לשם\u0004 קרבן \u0003תודה ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003תודה, למאי הילכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]?\u0006 \u0003להטעינו לחם,\u0004 שיהיה צריך להביא עמו חלות כמו שמביאים עם התודה!","ודוחים: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר\u0006 כזה\u0005]\u0006 ש\u0003פסח גופיה\u0004 \u0005[עצמו]\u0006 כשמקריבים אותו לשמו \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003לחם, ומותרו\u0004 והמותר שלו, שאינו קרב, כגון כששוחטו שלא לשמו, \u0003בעי\u0004 \u0005[יהיה צריך]\u0006 \u0003לחם?\u0004","ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 לפי ההלכה שהוא נעשה שלמים, אפשר לשאול: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר\u0006 כזה\u0005]\u0006 ש\u0003פסח גופיה לא בעי\u0004 \u0005[עצמו אינו צריך]\u0006 \u0003נסכים, ו\u0004אילו \u0003מותרו\u0004 כשהוא נשחט שלא לשמו \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003נסכים\u0004 כדין שלמים?","ומתקנים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אמרנו]\u0006 כך היתה השאלה: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003מותר תודה עצמה לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003לחם, ואילו מותר דאתיא להו מעלמא\u0004 \u0005[שבאה לו מהחוץ],\u0006 כפסח זה שנשחט לשם תודה, \u0003בעיא\u0004 \u0005[צריך]\u0006 \u0003לחם?\u0004 ושבים לדון בעיקר הראיה שפסח שנשחט שלא לשמו קרב שלמים, מן הפסוק \"ואם מן הצאן קרבנו לזבח שלמים\".","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב [יימר] בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הילל: וממאי\u0004 \u0005[וממה]\u0006 מסיק אתה שפסוק זה \u0003במותר פסח כתיב\u0004 \u0005[נאמר]\u0006 שנשחט שלא לשמו? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003במותר אשם\u0004 \u0003כתיב\u0004 \u0005[נאמר],\u0006 שהרי גם האשם בא מן הצאן בלבד!","\u0003אמר רבא, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואם מן הצאן קרבנו לזבח שלמים\"\u0004 (ויקרא ג, ו), לומר: \u0003דבר השוה בכל הצאן,\u0004 בין בכבשים בין בעיזים. מה שאין כן באשם, שבא רק מן האילים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבין בר חייא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' אבין בר כהנא: בכל אתר את אמרת\u0004 \u0005[בכל מקום אתה אומר]\u0006 שהלשון \u0003\"מן\"\u0004 בא \u0003להוציא\u0004 ולמעט, ולפי זה \"מן הצאן\" צריך להיות דבר הבא רק מחלק מן הצאן, \u0003ו\u0004אילו \u0003כאן\u0004 אתה מפרש \u0003\"מן\u0004 הצאן\" — כל הצאן, \u0003לרבות!\u0004","\u0003אמר ר' מני: הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"מן\"\u0004 בא \u0003להוציא,\u0004 שהרי אין הפסח בא אלא בחלק מן הצאן, \u0003דלא אתי\u0004 \u0005[שאינו בא]\u0006 כשהוא \u0003בן שתי שנים ולא אתי\u0004 \u0005[ואינו בא]\u0006 \u0003בנקיבה.\u0004","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הראיה מן הכתוב \u0003רב חנא בגדתאה\u0004 קושיה אחרת: \u0003ומי מצית אמרת\u0004 \u0005[האם יכול אתה לומר]\u0006 \u0003דכי\u0004 \u0003כתיב האי\u0004 \u0005[שכאשר נאמר\u0006 כתוב \u0005זה]\u0006 \"ואם מן הצאן קרבנו\" וכו' \u0003במותר פסח כתיב\u0004 \u0005[כתוב]?\u0006 \u0003והא מדכתיב\u0004 \u0005[והרי ממה שנאמר]\u0006 מיד אחר כך: \u0003\"אם כשב\"\u0004 (ויקרא ג, ז) \u0003\"אם עז\"\u0004 (ויקרא ג, יב), \u0003מכלל\u0004 הדברים אתה לומד \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003במותר פסח כתיב\u0004 \u0005[נאמר],\u0006 שהרי מפורש במקום אחר שהפסח בא מן הכבשים והעיזים, ומה צורך לחזור ולומר זאת!","ומשיבים: גם אם מדובר במותר פסח, \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[אותו\u0006 כתוב המפרט דיניהם של כשב ועז \u0005נצרך לו לכמו ששנויה\u0006 בברייתא אחרת\u0003]:\u0004 נאמר שם \u0003\"כבש\"\u0004 — \u0003לרבות\u0004 \u0003את הפסח לאליה,\u0004 שאף שלא נתפרש דבר זה בדיני הפסח, בכל אופן צריכים להקריב את האליה שלו, כמו שמקריבים בשלמים.","\u0003כשהוא אומר: \"אם כבש\"\u0004 — הרי \"אם\" זה בא \u0003לרבות פסח שעיברה שנתה\u0004 כלומר, שעבר את שנתו הראשונה ואינו כשר לקרבן פסח, \u0003ו\u0004כן \u0003שלמים הבאים מחמת פסח\u0004 שיתרבו \u0003לכל מצו‍ת שלמים,\u0004 לומר \u0003שיטענו סמיכה ונסכים ותנופת חזה ושוק. כשהוא אומר\u0004 שם: \u0003\"אם עז\"\u0004 — \u0003הפסיק הענין, לימד על העז שאינה טעונה אליה.\u0004","על כך מקשים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006כי דבר \u0005זה מכאן הוא יוצא]\u0006 שפסח שעברה שנתו קרב שלמים? הלא \u0003מדאבוה דשמואל נפקא\u0004 \u0005[מ\u0006דברי \u0005אביו של שמואל הוא יוצא], ש\u0006\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל:\u0004 נאמר \u0003\"ואם מן הצאן קרבנו לזבח שלמים\"\u0004 (ויקרא ג, ו) — \u0003דבר הבא מן הצאן יהא לזבח שלמים!\u0004","ומשיבים, גם לשיטתך יש להקשות: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003מ\u0004דברי \u0003רב נחמן אמר רבה בר אבוה נפקא\u0004 \u0005[יוצא]\u0006 דבר זה! ש\u0003אמר רב נחמן אמר רבה בר אבוה: מנין למותר פסח שקרב שלמים? שנאמר: \"וזבחת פסח לה' אלהיך צאן ובקר\"\u0004 (דברים טז, ב), \u0003והלא אין פסח בא אלא מן הכבשים ומן העזים\u0004 ולא מן הבקר! \u0003אלא מכאן למותר הפסח שיהא לדבר הבא מן הצאן ומן הבקר, ומאי ניהו\u0004 \u0005[ומה הוא זה]?\u0006 \u0003שלמים,\u0004 ואם כן יש פסוקים אחרים שבאים ללמד דבר זה!","\u0003אלא\u0004 יש לומר כך: \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה מקראות כתובים]\u0006 ומדברים בדיני מותר הפסח,"],["\u0003חד\u0004 \u0005[\u0006פסוק \u0005פסוק אחד]\u0006 \u0003ל\u0004מקרה של מקדיש את הפסח לאחר ש\u0003עיברה\u0004 (עבר) \u0003זמנו\u0004 (זמן שחיטתו) וגם \u0003עיברה שנתו\u0004 שקרבן הפסח הזה הוא גדול מבן שנה, ופסול. \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 \u0003ל\u0004מקרה של \u0003עיברה זמנו\u0004 שעבר זמן שחיטת הפסח, \u0003ולא\u0004 עברה \u0003שנתו\u0004 שעדיין הקרבן הוא פחות מבן שנה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003ל\u0004מקרה ש\u0003לא עיברה לא זמנו ולא שנתו,\u0004 אלא שלא הקריבוהו לשם פסח, להשמיענו שכל אלה קרבים כשלמים.","\u0003וצריכי\u0004 \u0005[וצריכים]\u0006 כל אלה להיכתב, \u0003דאי כתב רחמנא חד\u0004 \u0005[שאם היתה כותבת התורה\u0006 רק \u0005אחד\u0006 מהם\u0005],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מדובר דווקא \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003עיברה שנתו וזמנו, דאידחי\u0004 \u0005[שנדחה]\u0006 \u0003מ\u0004דין \u0003פסח לגמרי\u0004 שאין כל אפשרות להקריבו, \u0003אבל עיברה זמנו\u0004 שעבר זמן הקרבת הפסח \u0003ולא\u0004 עברה \u0003שנתו, דחזי\u0004 \u0005[ש\u0006עדיין הוא \u0005ראוי]\u0006 להקריבו \u0003לפסח שני\u0004 בארבעה עשר באייר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ועדיין דינו כפסח.","\u0003ואי כתב רחמנא הני תרתי\u0004 \u0005[ואילו היתה כותבת התורה\u0006 את \u0005אלה השנים],\u0006 הייתי אומר שהם קרבים שלמים \u0003משום דאידחי להו ממילתייהו\u0004 \u0005[שנדחו להם מעניינם],\u0006 \u0003אבל היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא עבר לא זמנו ולא שנתו, דחזי\u0004 \u0005[ש\u0006הוא \u0005ראוי]\u0006 \u0003לפסח\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 להיכתב כל אלה.","\u0003אמר רב משמיה\u0004 \u0005[משמו]\u0006 של החכם \u0003מבוג: חטאת ששחטה לשום\u0004 (לשם) \u0003חטאת נחשון\u0004 כלומר, לשם אותן החטאות שהקריבו נשיאי ישראל בזמן חנוכת המשכן (ראה במדבר ז) שלא כדי לכפר על עוון, אלא כעין דורון — \u0003כשירה\u0004 ועלתה לבעליה לשם חובה, ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"זאת תורת החטאת\"\u0004 (ויקרא ו, יח), לומר: \u0003תורה אחת לכל החטאות,\u0004 שאין הבדל בין חטאת לחטאת.","\u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבא וקאמר לה להא שמעתא\u0004 \u0005[ואומר את ההלכה הזאת].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב משרשיא לרבא,\u0004 ממה ששנינו בברייתא: \u0003ר' שמעון אומר: כל המנחות שנקמצו שלא לשמן\u0004 אלא לשם סוג מנחה אחר — \u0003כשירות ו\u0004גם \u0003עלו לבעלים לשום חובה,\u0004 שלא כמו זבחים, שכשרים אך אינם עולים לבעליהם לשם חובה.","וטעם הדבר, \u0003לפי שאין המנחות דומות לזבחים, ש\u0004כן \u0003הקומץ\u0004 מנחת \u0003מחבת לשם\u0004 מנחת \u0003מרחשת\u0004 — \u0003מעשיה מוכיחין עליה\u0004 כלומר, אופן עשייתה מוכיח עליה \u0003שהיא\u0004 עשויה ב\u0003מחבת\u0004 (שטוחה) ולא מרחשת (מטוגנת בטיגון עמוק), וכן הקומץ מנחה \u0003חריבה\u0004 (שאין בה שמן) \u0003לשם\u0004 \u0003בלולה\u0004 (בשמן) — \u0003מעשיה מוכיחין\u0004 עליה \u0003שהיא חריבה,\u0004 ולפיכך אין המחשבה והדיבור מועילים בה כלל.","\u0003אבל בזבחים אינו כן,\u0004 דרך \u0003שחיטה אחת לכולן,\u0004 דרך \u0003קבלה אחת לכולן,\u0004 דרך \u0003זריקה אחת לכולן,\u0004 ולכן אם נעשתה אחת העבודות שלא לשמם — מועיל בהם הדיבור, ואינם עולים לבעלים ידי חובה.","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא משום ש\u0003מעשיה מוכיחין\u0004 הדין כן, שהמנחה כשירה ועלתה לבעלים, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003אין מעשיה מוכיחין\u0004 — \u0003לא,\u0004 ולפי דברי רב בשם מבוג, \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא תעלה המנחה לבעלים? \u0003לימא\u0004 \u0005[שנאמר]\u0006 מן הכתוב: \u0003\"זאת תורת המנחה\"\u0004 (ויקרא ו, ז), \u0003תורה אחת לכל המנחות!\u0004","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003מבוג: חטאת ששחטה\u0004 לא לשם חטאת נחשון, אלא \u0003על מנת שיתכפר בה נחשון\u0004 — \u0003כשירה,\u0004 וטעם הדבר, כי \u0003אין כפרה למתים,\u0004 ולכן אין זה נקרא שינוי בעלים.","ושואלים: אם לכך התכוון, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003מת בעלמא\u0004 \u0005[סתם],\u0006 ולמה הזכיר דווקא נחשון?","ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 מפני שנשחט לשם \u0003מת\u0004 הדין כן, \u0003הא\u0004 \u0005[אבל]\u0006 אם היה עושה לשם חטאת של אדם \u0003חי דומיא\u0004 \u0005[בדומה]\u0006 לחטאת \u0003נחשון\u0004 — היתה \u0003פסולה,\u0004 \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 ששוחט לשם \u0003חטאת נזיר וחטאת מצורע,\u0004 שכמו חטאת נחשון, אין הן באות לכפר על חטא, אלא להכשיר ולטהר, ומכל מקום יש בהם דין שינוי בעלים.","ומקשים: הלוא \u0003הני\u0004 \u0005[אלה],\u0006 אף שמעשיהן כמעשה חטאת, הרי מצד הכפרה \u0003עולות נינהו\u0004 \u0005[הן],\u0006 ואם מקריב חטאת לשם מי שמחוייב עולה — כשרה היא, משום שאינו מחוייב כפרה כמותו (ראה לעיל זבחים ג:)!","\u0003אלא אי\u0004 \u0003איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003מבוג: חטאת ששחטה על\u0004 מי \u0003שמחוייב חטאת כנחשון\u0004 — \u0003כשירה,\u0004 כי \u0003חטאת נחשון\u0004 לא היתה חטאת ממש, אלא כעין \u0003עולה היא.\u0004","\u0003איכא דאמר\u0004 \u0005[יש שאומר]\u0006 בלשון אחרת: \u0003אמר רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003מבוג: חטאת ששחטה לשם חטאת נחשון\u0004 — \u0003פסולה,\u0004 מפני ש\u0003חטאת נחשון עולה היא,\u0004 והרי זה כשוחט חטאת שלא לשמה.","ושואלים: ומדוע הזכיר חטאת נחשון? \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 חטאת ששחטה לשם \u0003חטאת נזיר וחטאת מצורע,\u0004 שגם הן כעולה! ומשיבים: \u0003עיקר חטאת\u0004 את המקרה הראשון של חטאת יחיד \u0003נקט\u0004 \u0005[תפס]\u0006 כדוגמה.","\u0003אמר רב: חטאת\u0004 שהפריש כדי לכפר על אכילת \u0003חלב, ששחטה לשם חטאת\u0004 על אכילת \u0003דם,\u0004 או ששחטה \u0003לשם חטאת עבודה זרה\u0004 — הרי היא \u0003כשירה,\u0004 שאין זה שינוי מעיקר שמה.","אבל אם שחטה \u0003לשם חטאת נזיר, לשם חטאת מצורע\u0004 — \u0003פסולה,\u0004 מדוע? כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003עולות נינהו\u0004 \u0005[הם],\u0006 שאין להן תפקיד כפרה כחטאות ממש.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: חטאת חלב ששחטה לשם חטאת\u0004 שבאה לכפר על \u0003טומאת מקדש וקדשיו, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 שהיא כשירה, משום שהיא באה לכפר על עבירה שיש בה \u0003כרת כמותה,\u0004","\u0003או דילמא\u0004 \u0005[שמא]\u0006 אין זו אותו קרבן, שהרי \u0003אין\u0004 דינה \u0003קבוע כמותה?\u0004 שהרי מביא בהמה או עוף או מנחה, לפי עושרו של החוטא (ראה ויקרא ה, ג— יג).","ומעירים: \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני כולהו לפסולא\u0004 \u0005[היה שונה\u0006 בדברי רב \u0005בכולם לפסול],\u0006 שגם אם שחט חטאת חלב לשם חטאת דם, או חטאת עבודה זרה — פסולה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שנאמר: \u0003\"ושחט אותה לחטאת\"\u0004 (ויקרא ד, לג) לומר: דווקא \u0003לשם אותה חטאת,\u0004 ואם משנה לשם כל חטאת אחרת — פסולה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: [בעיא\u0004 \u0005[את הבעיה]\u0006 ששאל \u0003רבא,]\u0004 מה דינה של חטאת ששחטה לשם חטאת טומאת מקדש וקדשיו, לשיטתכם \u0003היכי מתניתו לה\u0004 \u0005[כיצד אתם שונים אותה]?\u0006 והרי לפי דרך זו, בוודאי פסולה היא!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 את שאלת רבא \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003בשינוי בעלים מתנינן לה\u0004 \u0005[שונים אותה],\u0006 כששוחטה לשם אחרים. \u0003[והכי מתנינן לה\u0004 \u0005[וכך אנו שונים אותה]\u0006\u0003],\u0004 שמתחילה \u0003אמר רבא: חטאת חלב ששחטה על מי שמחוייב חטאת דם וחטאת עבודה זרה\u0004 — הרי היא \u0003פסולה,\u0004 שהרי גם האחר חייב בחטאת. אבל אם שחטה \u0003על מי שמחוייב חטאת נזיר וחטאת מצורע\u0004 — הרי היא \u0003כשירה,\u0004 שאין המביא חטאת כזו מחוייב כפרה כמותו.","\u0003ובעיין לה הכי\u0004 \u0005[ואנו שואלים אותה כך]:\u0006 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: חטאת חלב ששחטה על מי שמחוייב חטאת\u0004 של \u0003טומאת מקדש וקדשיו, מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 שהיא באה לכפר על \u0003כרת כמותה,\u0004 ולכן דינו כמקריב לשם אחר החייב חטאת דם, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אין\u0004 קרבנו \u0003קבוע כמותה\u0004 ואין הוא נחשב מחוייב כפרה כמותו?","שאלה זו לא נפתרה, ועל כן \u0003תקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שחטה\u0004 את החטאת \u0003לשמה\u0004 על מנת \u0003לזרוק דמה שלא לשמה\u0004 — מה דינה? \u0003ר' יוחנן אמר: פסולה, וריש לקיש אמר: כשירה.\u0004","ומסבירים את טעמיהם: \u0003ר' יוחנן\u0004 \u0003אמר פסולה,\u0004 כי \u0003מחשבין מעבודה לעבודה,\u0004 שמחשבת פסול מועילה אפילו חשב מחשבת פסול ביחס לעבודה אחרת\u0003,\u0004 \u0003וילפינן\u0004 \u0005[ולמדים אנו]\u0006 דבר זה \u0003ממחשבת פיגול,\u0004 שאם בזמן ששוחט עשה זאת על מנת לזרוק את הדם לאחר זמנו — הרי זה מפגל.","\u0003וריש לקיש אמר כשירה\u0004 היא, כי \u0003אין מחשבין מעבודה לעבודה, ולא ילפינן\u0004 \u0005[ואין אנו למדים]\u0006 \u0003ממחשבת פיגול.\u0004","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והולכים\u0006 הם בענין זה \u0005לשיטתם],\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שחלקו בבעיה הבאה:"],["\u0003השוחט את הבהמה על מנת לזרוק דמה לעבודה זרה,\u0004 או \u0003להקטיר חלבה לעבודה זרה\u0004 — \u0003ר' יוחנן אמר: אסורה\u0004 הבהמה בהנאה על ידי שחיטה זו, כדין תקרובת עבודה זרה, אף על פי שלא זרק דמה או הקטיר חלבה לעבודה זרה אחר כך, כי \u0003מחשבין מעבודה לעבודה\u0004 שמה שחושב בזמן השחיטה לגבי הזריקה מועיל, \u0003וילפינן\u0004 \u0005[ולמדים אנו]\u0006 \u0003חוץ מבפנים\u0004 שכשם שבבית המקדש דבר כזה פוסל בפיגול, כך הוא אוסר במחשבת עבודה זרה.","\u0003ריש לקיש אמר: מותרת, אין מחשבין מעבודה לעבודה, ולא ילפינן\u0004 \u0005[ואין אנו למדים]\u0006 \u0003חוץ מפנים.\u0004","ומעירים: שתי המחלוקות הללו צריכות, \u0003ואי אשמעינן בהא\u0004 \u0005[ואם היה משמיע לנו בזו]\u0006 בשוחט לעבודה זרה, הייתי אומר: דווקא \u0003בהא\u0004 \u0005[בזו]\u0006 \u0003אמר ריש לקיש\u0004 שאין מחשבים, מפני שאין למדים חוץ מפנים, \u0003אבל\u0004 בשחיטה על מנת לזרוק שלא לשמה, שהוא לימוד של מחשבת \u0003פנים מ\u0004מחשבת \u0003פנים\u0004 (מחשבת לשמה ממחשבת פיגול) — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יוחנן\u0004 שמחשבים.","ולהיפך, \u0003ואי אשמעינן הא\u0004 \u0005[ואם היה משמיע לנו זו]\u0006 במחשב בעבודות המקדש, הייתי אומר \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' יוחנן, אבל בההיא\u0004 לגבי עבודה זרה \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לריש לקיש\u0004 שאין למדים חוץ מפנים, על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 שייאמרו שניהם.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: מתיב\u0004 \u0005[משיב היה]\u0006 \u0003רב ירמיה\u0004 כדרך קל וחומר \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לר' יוחנן, ור' אילא\u0004 היה משיב כדי \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לריש לקיש.\u0004","ומפרטים, \u0003רב ירמיה לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לר' יוחנן\u0004 מסברה זו: \u0003ומה\u0004 אם \u0003במקום שאם אמר \"הריני שוחט חוץ לזמנו\" שהוא כשר,\u0004 אם \u0003שחטו על מנת לזרוק דמו חוץ לזמנו\u0004 — \u0003פסול, מקום שאם אמר \"הריני שוחט שלא לשמו\"\u0004 שהוא \u0003פסול,\u0004 אם \u0003שחטו על מנת לזרוק דמו שלא לשמו\u0004 — \u0003אינו דין שיהא פסול?\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר אהילאי:\u0004 אין זה קל וחומר הגון, כי \u0003מה\u0004 למחשב \u0003לחוץ לזמנו\u0004 שהוא חמור \u0003שכן\u0004 מביא לידי עונש \u0003כרת\u0004 על אכילתו, תאמר במחשבה שלא לשמו, שאף שהוא פסול, אין חייבים כרת על אכילתו!","\u0003אלא אמר רבא בר אהילאי, הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 כך יש להוכיח: \u0003ומה מקום שאם אמר \"הריני שוחט חוץ למקומו\" שהוא כשר,\u0004 אם \u0003שחטו על מנת לזרוק דמו חוץ למקומו\u0004 — הרי הוא \u0003פסול\u0004 (ואינו פיגול שחייבים כרת על אכילתו, כדין מחשבת חוץ לזמנו), \u0003מקום שאם אמר \"הריני שוחט שלא לשמו\" שהוא פסול, [שחטו על מנת] לזרוק דמו שלא לשמו\u0004 — \u0003אינו דין שיהא פסול?\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 גם זה אינו קל וחומר, כי \u0003מה ל\u0004פסול \u0003חוץ למקומו\u0004 שהוא חמור יותר — \u0003שכן נוהג בכל הזבחים,\u0004 שמחשבה זו של חוץ למקומו יכולה להיות בכל זבח, \u0003תאמר בשלא לשמו\u0004 — \u0003שאינו נוהג\u0004 פסול \u0003אלא בפסח וחטאת!\u0004","\u0003אלא אמר רב אשי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003ומה במקום שאם אמר \"הריני שוחט לשם פלוני\"\u0004 (שאינו בעליו של הקרבן) דינו \u0003שהוא כשר,\u0004 מכל מקום אם שחט על מנת \u0003לזרוק דמו לשם פלוני\u0004 — \u0003פסול, מקום שאם אמר \"הריני שוחט שלא לשמן\" שהוא פסול,\u0004 אם \u0003[שחטו על מנת] לזרוק דמן שלא לשמן\u0004 — \u0003אינו דין שיהא פסול?\u0004 ומכאן ראיה לשיטת ר' יוחנן.","ומעתה מביאים את ההוכחה שהיה \u0003ר' אילא\u0004 מביא \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לריש לקיש\u0004 שאין מחשבים מעבודה לעבודה: \u0003לא תאמר\u0004 התורה דין מחשבת שלא לשמו \u0003בזריקה, ותיתי\u0004 \u0005[ותבוא\u0006 ויילמד הדבר\u0005]\u0006 \u0003מקל וחומר מבינייא\u0004 \u0005[מביניהן],\u0006 \u0003משחיטה וקבלה, למאי הלכתא כתב רחמנא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה כתבה התורה\u0006 במפורש\u0005]\u0006 דין זה גם בזריקה? \u0003לומר,\u0004 ש\u0003אין מחשבין מעבודה לעבודה,\u0004 אלא בכל עבודה יש פסול רק בה עצמה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ודלמא\u0004 \u0005[ושמא]\u0006 נכתב דבר זה ללמדנו את ההיפך, ש\u0003מחשבין מעבודה לעבודה!\u0004","ומשיבים: \u0003אם כן, לשתוק קרא מיניה ותיתי\u0004 \u0005[שישתוק הכתוב ממנו,\u0006 ולא יפרשנו, \u0005ויבוא\u0006 יילמד הדבר\u0005]\u0006 \u0003מקל וחומר\u0004 שאמר \u0003רב אשי\u0004 לעיל, משינוי בעלים. ואם נכתב, ודאי נכתב על מנת להוציא מקל וחומר זה.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005]\u0006 \u0003פריך הכי\u0004 \u0005[מקשה כך]\u0006 על ראיה זו: \u0003מה להנך\u0004 \u0005[לאלה],\u0006 לשחיטה וקבלה, \u0003שכן טעונות צפון\u0004 שייעשו בחלקה הצפוני של העזרה (בקדשי קדשים), \u0003וישנן\u0004 גם \u0003בחטאות הפנימיות,\u0004 מה שאין כן בזריקה, ולא ניתן היה, איפוא, ללמוד מהן לזריקה.","ומן הצד השני, \u0003ואידך\u0004 \u0005[והאחר]\u0006 ריש לקיש, מה הוא עונה על כך? \u0003השתא מיהא\u0004 \u0005[עכשיו על כל פנים]\u0006 במקור הדין של שחיטה שלא לשמה \u0003בשלמים קיימין\u0004 \u0005[אנו עומדים],\u0006 שדינים אלה של שלא לשמה נלמדו מפרשת השלמים (ומהם למדנו לשאר קרבנות). ובשלמים אין שחיטה וקבלה טעונות צפון, ואין דמה ניתן בפנים, ולפיכך היה מקום ללמוד מהן לזריקה.","ובדומה למחלוקת ר' יוחנן וריש לקיש \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בשאלה: בהמה \u0003ש\u0004\u0003שחטה לשמה\u0004 על מנת \u0003לזרוק דמה שלא לשמה\u0004 — \u0003רב נחמן אמר: פסולה, רבה אמר: כשרה. והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רבה לגבי רב נחמן מ\u0004אותו \u0003קל וחומר\u0004 שאמר \u0003רב אשי\u0004 משינוי בעלים.","שנינו במשנה ש\u0003ר' אליעזר אומר: אף האשם\u0004 פסול שלא לשמו. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: חטאת באה על חטא ואשם בא על חטא, מה חטאת שלא לשמה\u0004 — \u0003פסולה, אף אשם שלא לשמו\u0004 — \u0003פסול.\u0004","\u0003אמר לו ר' יהושע: לא, אם אמרת בחטאת שכן דמה\u0004 נזרק \u0003למעלה\u0004 מאמצע המזבח, מה שאין כן באשם ושאר קרבנות!","\u0003אמר לו ר' אליעזר: פסח יוכיח, שדמו\u0004 נזרק \u0003למטה\u0004 (בחצי המזבח התחתון), \u0003ו\u0004בכל זאת \u0003שחטו שלא לשמו\u0004 — \u0003פסול.\u0004","\u0003אמר לו ר' יהושע: מה לפסח שכן זמנו קבוע,\u0004 מה שאין כן באשם!","\u0003אמר לו ר' אליעזר: חטאת תוכיח,\u0004 שאין זמנה קבוע.","\u0003אמר לו ר' יהושע:\u0004"],["\u0003חוזרני חלילה\u0004 חוזר אני שוב לטענה הקודמת, וכך נסתובב במעגל בלא שנגיע למסקנה.","\u0003חזר ר' אליעזר ודנו דין אחר: חטאת נאמר בה \"היא\" בשחיטה\u0004 \"ושחט אותו... חטאת הוא\" (כד, ד), לומר שכאשר \u0003היא לשמה\u0004 — \u0003כשירה, שלא לשמה\u0004 — \u0003פסולה, ו\u0004כן \u0003פסח נאמר בו \"הוא\" בזביחה\u0004 (\"זבח פסח הוא לה'\" שמות יב, כז), לומר שכאשר \u0003הוא לשמו\u0004 — \u0003כשר, שלא לשמו\u0004 — \u0003פסול.\u0004","ולפיכך \u0003אף אשם נאמר בו \"הוא\"\u0004 (\"והקטיר אותם הכהן המזבחה אשה לה' אשם הוא\". ויקרא ז, ה), לומר ש\u0003הוא לשמו\u0004 — \u0003כשר, שלא לשמו\u0004 — \u0003פסול!\u0004","\u0003אמר לו ר' יהושע:\u0004 מכאן אין הוכחה, שכן אמנם \u0003חטאת נאמר בה \"היא\" בשחיטה,\u0004 לומר ש\u0003היא לשמה כשרה, שלא לשמה פסולה,\u0004 וכן \u0003פסח נאמר בו \"הוא\" בזביחה,\u0004 לומר ש\u0003הוא לשמו כשר, שלא לשמו\u0004 \u0003פסול. אבל אשם לא נאמר בו \"הוא\" אלא לאחר הקטרת אימורין, ו\u0004הרי \u0003הוא עצמו שלא הוקטרו אימורין\u0004 שלו כלל — \u0003כשר,\u0004 ואם כן מה שנאמר בו \"הוא\" בוודאי אינו מעכב!","\u0003אמר לו ר' אליעזר,\u0004 מכל מקום \u0003הרי\u0004 הכתוב מקיש אותם ו\u0003אומר: \"כחטאת כאשם\"\u0004 (ויקרא ז, ז), לומר: \u0003מה חטאת שלא לשמו\u0004 — \u0003פסול, אף אשם שלא לשמו\u0004 — \u0003פסול.\u0004","עד כאן הבאנו את לשון הברייתא, ומעתה דנים בה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו, \u0003אמר לו ר' יהושע: חוזרני חלילה.\u0004 ומקשים: \u0003ולמיהדר דינא ולייתי\u0004 \u0005[ושיחזור הדין, ויבוא הדבר]\u0006 לדעת ר' אליעזר \u0003ב\u0004דרך הלימוד של \u0003\"מה הצד\",\u0004 שאף שאשם שונה גם מחטאת וגם מפסח, יש בו צד השווה בשניהם, וממנו ילמד!","ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש מקום לשבור\u0006 את ההשוואה ולומר\u0005]:\u0006 \u0003מה להצד השוה שבהן שכן יש בהן\u0004 בחטאת ובפסח \u0003צד כרת,\u0004 מה שאין כן האשם.","ועוד שנינו בברייתא, \u0003אמר לו ר' יהושע: לא, אם אמרת בחטאת שכן דמה למעלה,\u0004 מה שאין כן אשם. ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יהושע טענה אחרת: \u0003לא, אם אמרת בחטאת שכן נכנס דמה לפני ולפנים\u0004 בפר ושעיר של יום הכיפורים!","ומשיבים: \u0003בחטאות החיצונות קאמרינן\u0004 \u0005[אומרים אנו],\u0006 להן אנו משווים את האשם, ובהן אין הדם נכנס לפנים.","ומקשים: ושיאמר לו הבדל אחר בין חטאת ואשם, \u0003שאם נכנס דמה\u0004 של חטאת (חיצונה, רגילה) \u0003[לפני] ולפנים\u0004 — \u0003פסולה,\u0004 מה שאין כן דם אשם!","ומשיבים: \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003לר' אליעזר\u0004 הוא סבור ש\u0003אף האשם\u0004 שנכנס דמו לפנים נפסל, כאשר יבואר להלן.","ושואלים: יאמר לו ר' יהושע שהחטאת חמורה מאשם, \u0003שכן מכפרת על חייבי כריתות,\u0004 ואין כן האשם!","ודוחים: ר' אליעזר מוכיח \u0003מחטאת\u0004 של \u0003שמיעת הקול,\u0004 שמי שנשבע לשקר שאינו יודע עדות לחבירו — מביא חטאת, אף שאין זה עוון כרת.","ושואלים עוד: ר' יהושע היה יכול לומר שחטאת חמורה מאשם \u0003שכן טעונה ארבע מתנות\u0004 שצריך לזרוק את דמה על המזבח בארבע נתינות נפרדות. מה שאין כן אשם, שנותן שתי מתנות בלבד!","ומשיבים: אולי סבור ר' אליעזר \u0003כר' ישמעאל,\u0004 ש\u0003אמר: כל הדמים\u0004 (קרבנות) \u0003טעונה\u0004 \u0003ארבע מתנות.\u0004","ושואלים: מכל מקום יכול היה ר' יהושע לומר ששונה החטאת משום \u0003ש\u0004היא \u0003טעונה\u0004 ארבע מתנות \u0003על ארבע קרנות\u0004 המזבח, ולא די בארבע מתנות על שתי קרנות בלבד, כפי שהוא באשם!","ומשיבים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך]\u0006 שאתה מקשה, הרי יכול היה להצביע על דברים אחרים המיוחדים לחטאת: \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חובת נתינה של הדם ב\u0003אצבע\u0004 ולא זריקה מן הכלי. וכן \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חובת נתינה על גוף ה\u0003קרן\u0004 שבראש המזבח ולא במקום אחר. וגם למי שאינו סבור כן, \u0003האיכא\u0004 \u0005[הרי יש]\u0006 חובת נתינה על \u0003חודה\u0004 של זוית המזבח דווקא! \u0003אלא\u0004 צריך לומר כי \u0003חד מתרי תלת טעמי נקט\u0004 \u0005[אחד משנים שלושה טעמים תפס],\u0006 ואין לשאול מפני מה לא אמר ר' אליעזר את כולם.","וממשיכים לדון באותה ברייתא. \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003אמר לו ר' יהושע\u0004 לר' אליעזר: \u0003לא, אם אמרת\u0004 בחטאת שכן דמה למעלה. ושואלים: \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 \u0003ר' אליעזר:\u0004 לשיטתו, \u0003אשם נמי\u0004 \u0005[גם כן]\u0006 \u0003דמו למעלה,\u0004 שהרי הוא משווה את דיני החטאת והאשם!","\u0003אמר אביי: אשם דמו למעלה לא מצית אמרת\u0004 \u0005[אינך יכול לומר],\u0006 שיש ללמוד \u0003קל וחומר מעולה, ומה עולה שהיא\u0004 חמורה לפי שכולה קריבה \u0003כליל\u0004 בכל זאת \u0003דמה\u0004 נזרק \u0003למטה, אשם שאינו\u0004 עולה \u0003כליל\u0004 (אלא בשרו נאכל לכהנים) \u0003לא כל שכן?\u0004","ואומרים: יש לדחות את הקל וחומר, \u0003מה לעולה שכן אינה מכפרת\u0004 שאינה באה לכפרת עוון, מה שאין כן אשם!","ואומרים: \u0003חטאת העוף תוכיח\u0004 שהיא מכפרת, ודמה ניתן למטה.","ואומרים: \u0003מה לחטאת העוף שכן אינה מין זבח,\u0004 שעוף אינו נשחט (נזבח) אלא נמלק!","ואומרים: \u0003עולה תוכיח\u0004 שהיא מין זבח. ונלמד דין זה משניהם, שכן \u0003לא ראי\u0004 (הרי) \u0003זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן\u0004 — \u0003שהן קדשי קדשים ודמן למטה, אף אני אביא אשם שהוא קודש קדשים ודמו למטה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזקיא לרב אשי, ולפרוך\u0004 \u0005[ושיקשה]\u0006 על כך: \u0003מה להצד השוה שבהן,\u0004 בעולה ובחטאת העוף, \u0003שכן אין להן קצבה\u0004 שאין סכום קצוב מסויים למחיר הקרבן, \u0003תאמר באשם שיש לו קצבה\u0004 (\"כסף שקלים\". ויקרא ה, טו)!","\u0003אלא היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' אליעזר,\u0004 שגם הוא סבור שהאשם דמו ניתן למטה — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי זריקת דם החטאת: \u0003\"הכהן המחטא אותה\"\u0004 (ויקרא ו, יט), והמילה \u0003\"אותה\"\u0004 בא להדגיש: החטאת בלבד \u0003דמה למעלה, ואין דמו של אחר למעלה.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שר' אליעזר מקבל את הדרשה \"אותה\", הרי גם בשחיטת \u0003חטאת\u0004 לשמה, שלמדנו מן הכתוב \"ושחט אותה לחטאת\" (ויקרא ד, לג) \u0003נמי נימא\u0004 \u0005[גם כן נאמר]:\u0006 \u0003אותה לשמה\u0004 — \u0003כשרה, שלא לשמה\u0004 — \u0003פסולה, הא\u0004 \u0005[אבל]\u0006 \u0003שאר זבחים,\u0004 ובכלל זה אשם, \u0003בין לשמן בין שלא לשמן\u0004 — \u0003כשרין,\u0004 ומדוע אין ר' אליעזר סבור כן לענין אשם!","ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003\"אותה\"\u0004 שנאמר לענין פסול שלא לשמה \u0003לאו דוקא\u0004 \u0005[לא\u0006 נאמר \u0005בדיוק],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שייר פסח,\u0004 שגם הוא פסול שלא לשמו.","ומקשים: \u0003הכא נמי לאו דוקא\u0004 \u0005[כאן גם כן אינו מדוייק]\u0006 לענין זריקה למעלה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שייר עולת העוף,\u0004 שגם היא דמה נזרק למעלה!","ומשיבים: לגבי קרבנות הטעונים \u0003זביחה\u0004 (שחיטה) \u0003מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003לא שייר מידי\u0004 \u0005[דבר],\u0006 ואין העוף שדינו מליקה נחשב שיור לענין זה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 גם את עולת העוף לא שייר לענין זה, כי \u0003הא מני\u0004 \u0005[\u0006דרשה \u0005זו\u0006 שממעטת כל קרבן מזריקת הדם למעלה, כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אלעזר בר' שמעון היא,\u0004 ש\u0003אמר: האי\u0004 \u0005[זה]\u0006 לחטאת בהמה \u0003מקום לחוד, והאי\u0004 \u0005[וזה]\u0006 לעולת העוף \u0003מקום לחוד.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003דמים התחתונים\u0004 כלומר, הקרבנות שדמם צריך לתת למטה, \u0003ניתנין מחוט הסיקרא\u0004 שהיה באמצע המזבח \u0003ולמטה,\u0004 \u0003והעליונים\u0004 ניתנים \u0003מחוט הסיקרא ולמעלה. אמר ר' אלעזר בר' שמעון: במה דברים אמורין\u0004 שהעליונים דמם ניתן בכל מקום למעלה מחוט הסיקרא? \u0003בעולת העוף, אבל בחטאת בהמה\u0004 לא די בכך שדמה למעלה, אלא \u0003היא עצמה אין נעשה\u0004 זריקת דמה \u0003אלא על גופה של קרן,\u0004 ולא במקום אחר.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה להלן: \u0003שהיה ר' עקיבא אומר: כל דמים\u0004 של כל הקרבנות \u0003שנכנסו להיכל לכפר\u0004 — \u0003פסולים, וחכמים אומרים: חטאת בלבד\u0004 פסולה, כאמור בכתוב \"וכל חטאת אשר יובא מדמה... לכפר בקדש לא תאכל...\" (ויקרא ו, כג). \u0003ר' אליעזר אומר: אף האשם, שנאמר: \"כחטאת כאשם\"\u0004 (ויקרא ז, ז).","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 דעת \u0003ר' אליעזר כדקאמר טעמא\u0004 \u0005[כמו שאמר את הטעם]\u0006 — מן ההיקש שבכתוב, \u0003אלא רבנן מאי טעמא\u0004 \u0005[חכמים מה הטעם]\u0006 שאינם סבורים כן באשם?","\u0003אמר רבא: אשם\u0004 ש\u0003נכנס דמו לפנים פסול לא מצית אמרת\u0004 \u0005[אינך יכול לומר\u0006 כן\u0005],\u0006 כי \u0003קל וחומר\u0004 הוא \u0003מעולה: מה\u0004"],["\u0003עולה שהיא\u0004 קריבה \u0003כליל\u0004 על המזבח, ובכל זאת אם \u0003נכנס דמה לפנים\u0004 — \u0003כשרה, אשם שאינו\u0004 קרב \u0003כליל לא כל שכן\u0004 שדמו שנכנס לפנים כשר?","ודוחים: אין ללמוד מכאן, כי \u0003מה לעולה שכן אינה מכפרת,\u0004 ואילו אשם מכפר!","ומשיבים: \u0003מנחת חוטא תוכיח\u0004 שמכפרת, ואינה נפסלת בכניסתה לקודש.","על תשובה זו שואלים, \u0003ולימא\u0004 \u0005[ושיאמר]:\u0006 \u0003חטאת העוף תוכיח,\u0004 שאף היא אינה נפסלת בכניסתה לפנים. והוכחה זו טובה יותר מן ההוכחה ממנחת חוטא, שאינה דם! ומשיבים: מחטאת העוף לא רצה להביא ראיה, כי \u0003חטאת העוף בעיא\u0004 \u0005[שאלה]\u0006 של \u0003ר' אבין היא,\u0004 שלא נפתרה, האם דמה שנכנס לפנים נפסל או לא.","ושואלים: \u0003ולפרוך\u0004 \u0005[ושיפרוך]\u0006 את ההוכחה הזו כך: \u0003מה למנחת חוטא שכן אינה מין זבח!\u0004","ואומרים: \u0003עולה תוכיח,\u0004 שהיא מין זבח, ואם נכנס דמה — כשרה. \u0003וחזר הדין, לא ראי זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן שהן קדשי קדשים ונכנס (דמן) לפנים\u0004 — \u0003כשרין, אף אני אביא אשם שהוא קודש קדשים ונכנס דמו לפנים\u0004 — והרי הוא \u0003כשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מברניש לרב אשי, ולפרוך\u0004 \u0005[ושיקשה]\u0006 ר' אליעזר על כך: \u0003מה להצד השוה שבהן שכן אין להן קצבה, תאמר באשם\u0004 שיש בו חומרה, \u0003שיש לו קצבה,\u0004 בכסף שקלים!","\u0003אלא\u0004 צריך לומר: \u0003היינו טעמייהו דרבנן\u0004 \u0005[זהו טעמם של חכמים]\u0006 שאינם פוסלים אלא בחטאת ולא באשם, ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין זה: \"וכל חטאת אשר יובא מ\u0003דמה\u0004 אל אוהל מועד\" (ויקרא ו, כג), הרי זו הדגשה: \u0003דמה של זו, ולא דמה של\u0004 קרבן \u0003אחר.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אליעזר\u0005],\u0006 מה למד הוא מן הדיוק הזה? ומשיבים: \u0003\"דמה\"\u0004 דווקא \u0003ולא בשרה,\u0004 שאם נכנס בשרה של חטאת לפנים אינה פסולה.","\u0003ואידך\u0004 \u0005[והאחרים,\u0006 חכמים\u0005]\u0006 מה הם אומרים? הם סבורים שכאן היה יכול לכתוב \u0003\"דם\"\u0004 וכתב \u0003\"דמה\",\u0004 ולמדים מ\"דם\" להוציא בשר, ומ\"דמה\" להוציא דם קרבן אחר.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אליעזר\u0005]?\u0006 את הדרשה \u0003\"דם\" \"דמה\" לא דריש\u0004 \u0005[אינו דורש].\u0006","ושבים למחלוקת ר' אליעזר וחכמים במשנה. ושואלים: \u0003בשלמא לרבנן דאמרי\u0004 \u0005[נניח\u0006 לשיטת \u0005חכמים שאומרים]:\u0006 \u0003אשם ששחטו שלא לשמו כשר\u0004 — \u0003היינו דאיתקש\u0004 \u0005[זהו\u0006 הטעם \u0005שהוקשה]\u0006 \u0003מנחה לחטאת\u0004 ו\u0003מנחה לאשם.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 נאמר במנחה \u0003\"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), ומפני מה יש השוואה כפולה, לחטאת ולאשם? ללמד: \u0003מנחת חוטא הרי היא כחטאת\u0004 שפסולה שלא לשמה, \u0003לפיכך\u0004 אם \u0003קמצה שלא לשמה\u0004 — \u0003פסולה,\u0004 ואילו \u0003מנחת נדבה הרי היא כאשם,\u0004 שאינו נפסל שלא לשמו, \u0003לפיכך קמצה שלא לשמה\u0004 — \u0003כשרה.\u0004 אם כן לשיטת חכמים ההיקש מובן יפה.","\u0003אלא ל\u0004דעת \u0003ר' אליעזר, למאי הלכתא איתקש\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה הוקשה]\u0006 \u0003מנחה לחטאת ומנחה לאשם?\u0004","ומשיבים: \u0003לכי אידך\u0004 \u0005[לכמו\u0006 הברייתא \u0005האחרת]\u0006 של \u0003ר' שמעון, דתנן\u0004 \u0005[ששנינו]:\u0006 המוליך את קומץ המנחה למזבח כדי להקטירו \u0003לא בכלי שרת\u0004 — \u0003פסולה\u0004 המנחה, \u0003ור' שמעון מכשיר.\u0004","\u0003ואמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון? אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), וההשוואה הכפולה באה לומר: אם \u0003בא לעובדה ביד\u0004 שלאחר קמיצתה מוליך את הקומץ למזבח בידו ממש — \u0003עובדה\u0004 ביד \u0003ימין כחטאת,\u0004 ואם עובדה ומוליכה למזבח \u0003בכלי\u0004 — יכול ל\u0003עובדה בשמאל\u0004 כמו שיכול לעשות בדם ה\u0003אשם\u0004 לדעת ר' שמעון.","ותוהים: \u0003ור' שמעון, האי קרא מפיק ליה להכי ומפיק ליה להכי\u0004 \u0005[פסוק זה מוציא אותו לכאן ומוציא אותו לכאן]\u0006 ולומד ממנו שני דברים שונים?","ומשיבים: \u0003עיקר קרא\u0004 \u0005[הפסוק]\u0006 לענין \u0003לכ\u0004 מו שאמר \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא הוא דאתא\u0004 \u0005[שבא].\u0006 \u0003ומנחת חוטא\u0004 ש\u0003פסולה שלא לשמה [טעמא אחרינא\u0004 \u0005[טעם אחר]\u0006 \u0003הוא],\u0004 מקור אחר יש לדבר: \u0003חטאת, טעמא מאי\u0004 \u0005[מה הטעם]\u0006 פסולה היא שלא לשמה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"היא\"\u0004 (ויקרא ד, כד), \u0003מנחת חוטא נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003בה\u0004 במפורש \u0003\"היא\"\u0004 (\"כי חטאת היא\". ויקרא ה, יא).","ושבים לעיקר הוכחתו של ר' אליעזר מן ההיקש של \"כחטאת כאשם\" (ויקרא ו, ז), ושואלים: \u0003ולרבנן\u0004 \u0005[\u0006ולדעת \u0005חכמים]\u0006 \u0003למאי הלכתא איתקש\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה הוקש]\u0006 \u0003אשם לחטאת?\u0004 ומשיבים, \u0003לומר לך: מה חטאת טעונה סמיכה\u0004 בשתי ידים על ראש הקרבן (ויקרא ד, כט), \u0003אף אשם טעון סמיכה.\u0004","שנינו במשנה, \u0003יוסף בן חוני אומר: הנשחטין\u0004 לשם פסח ולשם חטאת פסולין. \u0003אמר ר' יוחנן: יוסף בן חוני ור' אליעזר אמרו דבר אחד,\u0004 שאף ר' אליעזר סבור כיוסף בן חוני.","\u0003רבה אמר:\u0004 \u0003ב\u0004קרבנות ה\u0003אחרים\u0004 הנשחטים \u0003לשם חטאת פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 ור' אליעזר סבור שהם כשרים. אבל בנשחטים לשם פסח, ר' אליעזר מסכים ליוסף בן חוני שהם פסולים.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הפסח שעברה שנתו\u0004 שהוא גדול מבן שנה, ולכן אינו ראוי עוד לפסח אלא לשלמים, \u0003ושחטו בזמנו\u0004 בערב פסח \u0003לשמו\u0004 לשם פסח, \u0003וכן השוחט\u0004 קרבנות \u0003אחרים לשם פסח בזמנו\u0004 — \u0003ר' אליעזר פוסל, ור' יהושע מכשיר.\u0004","\u0003אמר ר' יהושע: אם בשאר ימות השנה,\u0004 למרות \u0003ש\u0004הפסח \u0003אינו כשר\u0004 כששחטו \u0003לשמו,\u0004 מכל מקום קרבנות \u0003אחרים כשרים\u0004 כששחטם \u0003לשמו,\u0004 אם כן \u0003בזמנו,\u0004 כ\u0003שהוא\u0004 הפסח עצמו \u0003כשר לשמו\u0004 — \u0003אינו דין שיכשרו אחרים\u0004 כשנשחטו \u0003לשמו?\u0004","\u0003אמר לו ר' אליעזר: או חילוף הדברים,\u0004 לפי דרך לימוד זו אפשר לעשות קל וחומר אחר, שהוא מופרך לגמרי, ולטעון כך: \u0003ומה אם בשאר ימות השנה,\u0004 למרות \u0003ש\u0004הפסח \u0003אינו כשר לשמו\u0004 — \u0003כשר הוא\u0004 אם נשחט \u0003לשם אחרים, בזמנו\u0004 בארבעה עשר בניסן \u0003שהוא\u0004 עצמו \u0003כשר לשמו\u0004 — \u0003אינו דין שיוכשר\u0004 כשנשחט \u0003לשם אחרים? ו\u0004אם כן \u0003יוכשר פסח בארבעה עשר שלא לשמו,\u0004 והרי הכל מודים שפסח שנשחט בזמנו שלא לשמו פסול!","ועוד אמר ר' אליעזר לר' יהושע: \u0003וכך אתה אומר?\u0004 אף קל וחומר שאמרת אפשר להפריכו מתוך עצמו, שכן \u0003מה לי הוכשרו אחרים בשאר ימות השנה\u0004 כשנשחטו \u0003לשמו\u0004 של פסח, \u0003שכן הוא כשר\u0004 אם נשחט אז \u0003לשם אחרים,\u0004 אבל האם תוכל לומר \u0003שיכשרו אחרים בזמנו לשמו? שכן הוא\u0004 הרי \u0003פסול\u0004 אז \u0003לשם אחרים!\u0004","\u0003אמר לו ר' יהושע: אם כן,\u0004 לשיטתך, שקרבנות אחרים ששחטם בערב פסח לשם פסח פסולים, \u0003הורעתה כח פסח\u0004 לענין \"לשמו\", \u0003ונתת כח\u0004 (כלומר, נתת חומרה) גדול יותר \u0003בשלמים,\u0004 שהרי פסח ששחטו לשם שלמים בזמן שלמים (בשאר ימות השנה) הריהו כשר, ואילו שלמים ששחטם לשם פסח בזמן הפסח — פסולים!","\u0003חזר ר' אליעזר ודנו\u0004 והוכיחו ב\u0003דין אחר: מצינו\u0004 ש\u0003מותר פסח\u0004 (כגון פסח שעבר זמנו) \u0003בא שלמים, ואין מותר שלמים\u0004 (כגון שנותרו לו מעות שהפריש עבור שלמים) \u0003בא פסח,\u0004 ולפיכך נלמד:","\u0003ומה פסח שמותרו בא שלמים,\u0004 ונמצא שהוא בכלל השלמים, בכל זאת אם \u0003שחטו בזמנו לשום שלמים\u0004 — \u0003פסול, שלמים שאין מותרן בא פסח, אם שחטם לשם פסח בזמנו\u0004 — \u0003אינו דין שיהו פסולין?\u0004"],["\u0003אמר לו ר' יהושע:\u0004 בדרך זו אין להוכיח, כי \u0003מצינו\u0004 ש\u0003מותר חטאת\u0004 (כגון שנותרו לו ממעות שהפריש לחטאת) \u0003בא עולה, ואין מותר עולה בא חטאת.\u0004","ולפי דרכך אפשר היה להסיק כך: \u0003ומה חטאת שמותרה בא עולה,\u0004 בכל זאת אם \u0003שחטה לשם עולה\u0004 — \u0003פסולה, עולה שאין מותרה בא חטאת, שחטה לשם חטאת\u0004 — \u0003אינו דין שתהא פסולה?\u0004","\u0003אמר לו ר' אליעזר: לא, אם אמרת בחטאת, שכן\u0004 היא \u0003כשרה לשמה כל השנה כולה, תאמר בפסח\u0004 — \u0003שאינו כשר לשמו אלא בזמנו\u0004 בלבד, \u0003ו\u0004\u0003הואיל והוא פסול לשמו\u0004 שלא בזמנו, \u0003דין הוא שיפסלו אחרים לשמו\u0004 בזמנו.","שנינו במשנה: \u0003שמעון אחי עזריה אומר כו'\u0004 שכל הקרבנות ששחטם לשם גבוה מהם — כשרים, לשם נמוך מהם — פסולים.","\u0003רב אשי מתני משמיה\u0004 \u0005[היה שונה משמו]\u0006 של \u0003ר' יוחנן, ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני משמיה\u0004 \u0005[היה שונה\u0006 את הדבר הזה \u0005משמו]\u0006 של \u0003ר' ינאי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003שמעון אחי עזריה?\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לגבי הכהנים: \u0003\"ולא יחללו את קדשי בני ישראל את אשר ירימו לה'\"\u0004 (ויקרא כב, טו), שיש להבינו לא כאיסור, אלא כקביעת הלכה, \u0003במורם מהן\u0004 אם שינה בעבודתם ועשאם לשם גבוה מהם במעלות הקודש \u0003אין מתחללין,\u0004 ומכאן אתה למד כי \u0003בנמוך מהם מתחללין.\u0004","ושואלים: \u0003והאי להכי\u0004 \u0005[ו\u0006פסוק \u0005זה לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 \u0003והא מיבעי ליה\u0004 \u0005[והרי\u0006 ואותו פסוק \u0005נצרך לו]\u0006 לדרשה אחרת, \u0003לכ\u0004 דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: מנין לאוכל את הטבל\u0004 (תבואה שלא הפריש ממנה תרומה ומעשר) \u0003שהוא במיתה\u0004 האמורה באותה פרשה? \u0003שנאמר: \"ולא יחללו את קדשי בני ישראל את אשר ירימו לה'\",\u0004 ולשון הכתוב משמעה כי \u0003ב\u0004קדשי בני ישראל ש\u0003עתידים לתרום הכתוב מדבר,\u0004 ועדיין לא הרימו, והוא הטבל!","ומשיבים: \u0003אם כן,\u0004 רק לצורך דרשתו של שמעון אחי עזריה מדבר הכתוב, \u0003לכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"אשר הורמו\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שימוש הלשון \u0003\"אשר ירימו\"\u0004 בלשון עתיד? \u0003שמע מיניה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 גם לענין קדשים שנשחטו לשם גבוה מהם שאינם מתחללים, וגם לענין טבל שאסור לחללו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 האם כוונתו של שמעון אחי עזריה היא שאם שחטם לשם גבוה מהם \u0003כשרין ואין מרצין\u0004 אין עולים לבעליהם לרצון, וכדברי חכמים במשנה, \u0003וכי פליג\u0004 \u0005[וכאשר\u0006 הוא \u0005חולק]\u0006 על חכמים \u0003בחדא פליג\u0004 \u0005[ב\u0006דבר \u0005אחד\u0006 הוא \u0005חולק]\u0006 באלה ששחטם לשם נמוך מהם, שלדעתו הם פסולים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו שהנשחטים לשם גבוה מהם \u0003כשרין ומרצין, ו\u0004לפי זה \u0003בתרתי פליגי\u0004 \u0005[בשני\u0006 דברים הוא \u0005חולק]?\u0006 שהרי לדעת חכמים, אם שחטם לשם גבוה מהם — כשרים, אבל לא עלו לבעלים ידי חובה.","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' זריקא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בהמשך דברי שמעון אחי עזריה במשנה: כיצד? \u0003הבכור והמעשר ששחטן לשם שלמים\u0004 — \u0003כשרים,\u0004 ואילו \u0003שלמים ששחטן לשם בכור או לשם מעשר\u0004 — \u0003פסולין.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שבכור ומעשר ששחטם לשם שלמים \u0003כשרין ומרצין,\u0004 יש לתמוה: וכי \u0003בכור בר ריצויי\u0004 \u0005[בן ריצוי]\u0006 \u0003הוא?\u0004 הרי אינו ענין של רצון ופיוס! \u0003אלא\u0004 ודאי הכוונה היא \u0003כשרין ואין מרצין. ומדסיפא\u0004 \u0005[ומ\u0006כיון \u0005שבסוף]\u0006 הכוונה היא \u0003כשרין ואין מרצין, רישא נמי\u0004 \u0005[בהתחלה גם כן],\u0006 לגבי קדשים קלים שנשחטו לשם קדשי קדשים, הכוונה היא \u0003כשרין ואין מרצין.\u0004","ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים הדברים]?\u0006 \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 שמא לענין קדשים קלים ששחטם לשם קדשי קדשים הכוונה היא שכשרים ומרצים, ולענין בכור ומעשר ששחטם לשם שלמים הכוונה היא רק שהם כשרים.","ושואלים: \u0003אלא\u0004 אם לא ללמד על הרישא \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בדוגמה זו של בכור ומעשר ששחטם לשם שלמים? וכי דוגמה של \u0003גבוה ונמוך קא משמע לן\u0004 \u0005[משמיע לנו]?\u0006 הרי דבר זה כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 תחילה: \u0003כיצד? קדשי קדשים ששחטן לשם קדשים קלים כו'!\u0004","ומשיבים: יש צורך בדין זה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003קדשי קדשים וקדשים קלים הוא דאיכא\u0004 \u0005[שיש]\u0006 בהם דין \u0003גבוה ונמוך\u0004 שאמר שמעון אחי עזריה, \u0003אבל\u0004 קדשים \u0003קלים ו\u0004קדשים \u0003קלים\u0004 אחרים \u0003לא,\u0004 שאין בהם גבוה ונמוך, וכולם נחשבים כדרגה אחת — לכן הודיענו שגם בקדשים קלים יש חלוקה לדרגות.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[\u0006הרי \u0005גם זה שנינו]\u0006 במקום אחר: \u0003שלמים קודמים את הבכור\u0004 בהקרבה, \u0003מפני שהן טעונין מתן ארבע וסמיכה ונסכים ותנופת חזה ושוק,\u0004 מה שאין כן בבכור!","ומשיבים: \u0003הא\u0004 \u0005[זה]\u0006 הדין האמור במשנתנו \u0003עיקר,\u0004 המשנה \u0003ההיא אגררא נסבה\u0004 \u0005[בגרר,\u0006 בדרך אגב \u0005לקח אותה]\u0006 אגב רשימה ארוכה של קדימויות בקדשים.","\u0003הפסח ששחטו שחרית בארבעה עשר\u0004 בניסן, שהוא יום שחיטת הפסח, אבל לפני הזמן (שהוא בין הערביים), אם עשה זאת \u0003שלא לשמו\u0004 — \u0003ר' יהושע מכשיר כאילו נשחט בשלשה עשר,\u0004 ופסח ששחטו שלא בזמנו — כשר. \u0003בן בתירא פוסל\u0004 אותו \u0003כאילו נשחט בין הערבים\u0004 של יום ארבעה עשר.","\u0003אמר שמעון בן עזאי: מקובל אני מפי שבעים ושנים זקן\u0004 שדנו הסנהדרין והחליטו על כך \u0003ביום\u0004 \u0003שהושיבו את ר' אליעזר\u0004 בן עזריה \u0003ב\u0004ראש ה\u0003ישיבה, שכל הזבחים הנאכלין שנזבחו שלא לשמן\u0004 — \u0003כשרין, אלא שלא עלו לבעלים משום חובה, חוץ מן הפסח ומן החטאת.\u0004 ומעירים: \u0003ו\u0004לפי זה \u0003לא הוסיף בן עזאי\u0004 על דברי המשנה הראשונה \u0003אלא העולה,\u0004 שאינה מן הזבחים הנאכלים, \u0003ולא הודו לו חכמים\u0004 בזה.","\u0003אמר ר' אלעזר אמר ר' אושעיא:\u0004 כשם שפוסל בן בתירא פסח ששחטו בבוקר ארבעה עשר שלא לשמו, כך \u0003מכשיר היה בן בתירא בפסח ששחטו שחרית בארבעה עשר לשמו,\u0004 שלדעתו \u0003כוליה יומא זימניה הוא\u0004 \u0005[כל היום\u0006 של ארבע עשר בניסן \u0005זמנו הוא].\u0006","ושואלים: אם כן, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"כאילו\u0004 נשחט בין הערביים\"? הרי לשיטתו אין חובה לשוחטו דוקא בין הערביים!","ומשיבים: \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003אמר ר' יהושע \"כאילו\u0004 נשחט בשלושה עשר\", \u0003אמר איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003\"כאילו\".\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אדמיפלגי\u0004 \u0005[עד ש\u0006הם \u0005חלוקים]\u0006 \u0003ב\u0004פסח שנשחט \u0003שלא לשמו\u0004 בשחרית, \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003ב\u0004פסח שנשחט אז \u0003לשמו,\u0004 האם הוא כשר או לא!","ומשיבים: \u0003אי איפלגו\u0004 \u0005[אם היו נחלקים]\u0006 \u0003בלשמו, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 דווקא בזה נחלקו, \u0003אבל בשלא לשמו מודי\u0004 \u0005[מודה]\u0006 \u0003ר' יהושע לבן בתירא\u0004 שהוא פסול אף בבוקר, \u0003הואיל ומקצתו\u0004 של היום \u0003ראוי\u0004 לקרבן, לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף בזה נחלקו.","ושואלים: כיצד יכול בן בתירא לומר שזמנו של הפסח גם בשחרית? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש: \"ושחטו אותו כל קהל עדת ישראל \u0003בין הערבים\"\u0004 (שמות יב, ו)!","\u0003אמר עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי:\u0004 הוא מפרש שהכוונה היא — \u0003בין שני ערבים\u0004 כלומר, בין שני לילות, ליל שלושה עשר וליל ארבעה עשר.","ומקשים: אם כך מפרשים ביטוי זה, קרבן \u0003תמיד דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \"את הכבש אחד תעשה בבוקר ואת הכבש השני תעשה \u0003בין הערבים\"\u0004 (במדבר כח, ד), \u0003הכי נמי דכולי יומא\u0004 \u0005[כך גם כך\u0006 תאמר \u0005שכל היום]\u0006 \u0003כשר?\u0004","ומשיבים: \u0003התם מדכתיב\u0004 \u0005[שם ממה שנאמר]:\u0006 \u0003\"את הכבש אחד תעשה בבקר\"\u0004 (במדבר כח, ד), \u0003מכלל\u0004 הדברים אתה למד ש\u0003בין הערבים\u0004 — \u0003בין הערבים ממש.\u0004","ושואלים, \u0003אימא\u0004 \u0005[אמור]\u0006 כך: כבש \u0003חד\u0004 \u0005[אחד]\u0006 תעשה דווקא \u0003בבקר, אידך\u0004 \u0005[והאחר]\u0006 אפשר להקריב \u0003כוליה יומא\u0004 \u0005[כל היום]!\u0006","ודוחים: לכך נאמר \u0003\"אחד... בבקר\"\u0004 — \u0003ולא שנים בבקר,\u0004 לומר שהשני צריך להעשות בין הערביים ממש.","ושואלים: \u0003נרות\u0004 המנורה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהם \"ובהעלות אהרן את הנרות \u0003בין הערבים\"\u0004 (שמות ל, ח), \u0003הכי נמי דכולי יומא\u0004 \u0005[כך גם כן תאמר שכל היום]\u0006 \u0003כשר\u0004 להדלקת הנרות?","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש: \u0003\"מערב ועד בקר\"\u0004 (שמות כז, כא), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"מערב ועד בקר\"\u0004 כוונתו: \u0003תן לה\u0004 במנורה את \u0003מדתה\u0004 שמן \u0003שתהא דולקת והולכת מערב ועד בקר.\u0004 ועוד דרשו שם \u0003דבר אחר: אין לך עבודה\u0004 ש\u0003כשרה מערב ועד בקר אלא זו בלבד,\u0004 שהיא העבודה המאוחרת מכל עבודות היום.","ושואלים עוד: \u0003קטורת, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה: \"בין הערבים\"\u0004 (שמות ל, ח) \u0003הכי נמי דכולי יומא\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שכל היום]\u0006 \u0003כשר?\u0004","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003קטרת\u0004"],["\u0003דאיתקש\u0004 \u0005[שהוקשה]\u0006 בכתוב זה \u0003לנרות,\u0004 ולפיכך זמנה תלוי בזמן הדלקת הנרות.","ושואלים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בפסח, בדומה לנרות, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"שם תזבח את הפסח בערב\"\u0004 (דברים טז, ו)!","ומשיבים: הכתוב \u0003ההוא\u0004 לא נצרך לעניינו, אלא \u0003ל\"יאוחר דבר\" הוא דאתא\u0004 \u0005[שבא].\u0006 ומה עניינו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 ביחס לשאלה מה קודם להקרבה, \u0005הפסח או תמיד\u0006 של בין הערביים: \u0003יאוחר דבר שנאמר בו \"בערב\" ו\u0004גם \u0003\"בין הערבים\"\u0004 (והוא הפסח) \u0003לדבר שלא נאמר בו אלא \"בין הערבים\" בלבד\u0004 (התמיד).","ותוהים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 ש\u0003אילו\u0004 היה \u0003שחיט ליה מצפרא\u0004 \u0005[שוחט אותו מן הבוקר]\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003זימניה\u0004 \u0005[זמנו]\u0006 \u0003הוא\u0004 כבר בבוקר, כמו קרבן הפסח לשיטת בן בתירא, \u0003וכי מטי\u0004 \u0005[וכאשר מגיע]\u0006 \u0003בין הערבים, אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003\"יאוחר דבר\",\u0004 ואתה מקדים לו קרבן שזמנו מתחיל רק אז?","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 דבר זה יתכן, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' יוחנן, הלכה:\u0004 כאשר איחר אדם להתפלל מוסף עד שהגיע זמן המנחה, לאחר חצות היום, \u0003מתפלל של מנחה\u0004 קודם \u0003ואחר כך מתפלל של מוספין,\u0004 למרות שזמנה של תפילת המוסף החל כבר בבוקר.","ושואלים: \u0003ו\u0004לדרך זו, ש\"בין הערביים\" משמעו לדעת בן בתירא כל היום כולו, אם כן \u0003\"בין הערבים\" דכתיב גבי\u0004 \u0005[שנאמר אצל]\u0006 \u0003קטרת ונרות למה לי?\u0004 שהרי ממילא אין זה זמנם!","\u0003ועוד,\u0004 הרי שנינו בברייתא: \u0003השיב רבי תחת\u0004 (במקום) \u0003בן בתירא לדברי ר' יהושע,\u0004 שאמר שפסח שנשחט בשחרית של ארבעה עשר בניסן שלא לשמו כשר כאילו נשחט בשלושה עשר: \u0003לא, אם אמרת בשלשה עשר שאין\u0004 אפילו \u0003מקצתו ראוי\u0004 להקרבת הפסח, \u0003תאמר בארבעה עשר שמקצתו ראוי\u0004 (בין הערביים).","\u0003ואם איתא\u0004 \u0005[אכן]\u0006 לדעת בן בתירא הפסח כשר כשנשחט לשמו בכל יום ארבעה עשר, אם כן \u0003כולו\u0004 ולא רק מקצתו \u0003ראוי הוא!\u0004","\u0003אלא\u0004 יש לדחות מה שאמרנו, וצריך לומר כמו ש\u0003אמר ר' יוחנן: פוסל היה בן בתירא בפסח ששחטו בארבעה עשר שחרית, בין\u0004 שנשחט \u0003לשמו\u0004 — הואיל ונשחט קודם זמנו, ו\u0003בין\u0004 שנשחט \u0003שלא לשמו\u0004 — \u0003הואיל ומקצתו\u0004 של יום זה \u0003ראוי\u0004 לשחיטה.","\u0003מגדף בה\u0004 (היה תמה על כך) \u0003ר' אבהו: אם כן,\u0004 קרבן \u0003פסח כשר לבן בתירא היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 \u0003אי דאפרשיה האידנא\u0004 \u0005[אם שהפרישו עכשיו]\u0006 בבוקר ארבעה עשר בניסן לשם פסח — \u0003דחוי מעיקרו\u0004 (מתחילתו) \u0003הוא,\u0004 שהרי אינו ראוי להקריבו, ושוב אינו כשר! \u0003ואי דאפרשינהו\u0004 \u0005[ו\u0006גם \u0005אם שהפרישו]\u0006 \u0003מאתמול\u0004 בשעה שראוי היה להקריבו (שלא לשמו) — הרי \u0003נראה ונדחה הוא\u0004 בבוקר, שהרי לא ניתן להקריבו עד בין הערביים, וקרבן שנדחה שוב אינו נעשה ראוי!","\u0003אלא אמר ר' אבהו: תהא\u0004 מציאות של פסח כשר, כאשר מפרישו \u0003לאחר חצות\u0004 היום, כשהוא ראוי לשחיטת פסח.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמפרישו \u0003מצפרא\u0004 \u0005[מהבוקר],\u0006 מכל מקום \u0003אין\u0004 פסול \u0003מחוסר זמן\u0004 (קרבן שלא הגיע זמנו ליקרב) נוגע \u0003ל\u0004קרבן הראוי ליקרב \u0003בו ביום,\u0004 וכיון שלאחר חצות יהא ראוי אין הוא דחוי.","\u0003רב פפא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהפרישו \u0003מאורתא\u0004 \u0005[מהלילה\u0006 הקודם\u0005]\u0006 — קרבן שהוקדש ב\u0003לילה אין\u0004 נחשב ל\u0003מחוסר זמן\u0004 אם הוא ראוי להקרבה ביום שלאחריו, \u0003דתני דבי\u0004 \u0005[ששנה\u0006 חכם \u0005בית מדרשו]\u0006 של \u0003ר' ישמעאל:\u0004 ולד של צאן ובקר (שפסול לקרבן עד יום השמיני ללידתו) ב\u0003ליל שמיני\u0004 כבר \u0003נכנס לדיר\u0004 עם \u0003חביריו\u0004 \u0003להתעשר\u0004 מעשר בהמה; \u0003וכ\u0004דברי","\u0003ר' אפטוריקי,\u0004 ש\u0003ר' אפטוריקי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והיה שבעת ימים תחת אמו\"\u0004 (ויקרא כב, כז), ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003לילה\u0004 שלאחר היום השביעי \u0003כבר\u0004 \u0003חזי\u0004 \u0005[ראוי הוא]\u0006 להקרבה. \u0003ו\u0004מן הצד השני \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ומיום השמיני והלאה ירצה\u0004 לקרבן אשה לה'\" (ויקרא כב, כז), משמע: \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003לילה לא חזי\u0004 \u0005[אינו ראוי]\u0006 עדיין!","\u0003הא כיצד\u0004 אתה מיישב את הסתירה? \u0003לילה\u0004 ראוי \u0003לקדושה\u0004 שאפשר להקדישו כבר בלילה, \u0003ויום להרצאה\u0004 שבו הוא נרצה לקרבן לה'. משמע שאף שאין הקרבן ראוי להקרבה כלל בלילה — ניתן אז להקדישו, ואין אומרים שהוא מחוסר זמן.","בעקבות הדיון הקודם \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אבהו, לימא קסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003ר' יוחנן\u0004 ש\u0003בעלי חיים נדחין\u0004 ושוב אינם ראויים להקרבה לאחר שנדחו פעם אחת?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 ש\u0003אמר ר' יוחנן: בהמה\u0004 שהיתה \u0003של שני שותפין, הקדיש\u0004 שותף אחד את \u0003חציה\u0004 שהיה ברשותו, \u0003וחזר ולקח\u0004 (וקנה) מן השותף \u0003את\u0004 \u0003חציה\u0004 האחר \u0003והקדישה\u0004 — הרי היא \u0003קדושה,\u0004 משום שחלה הקדושה גם על חלקה הזה, \u0003ו\u0004אולם \u0003אינה קריבה\u0004 כקרבן.","\u0003ו\u0004בהמה זו \u0003עושה תמורה\u0004 שאם אמר על בהמה אחרת \"זו תמורת זו\" — גם האחרת קדושה, \u0003ותמורתה כיוצא בה\u0004 שיש לה אותו דין עצמו, שהיא קדושה ואינה קריבה.","\u0003ושמע מינה תלת\u0004 \u0005[ולמד ממנה\u0006 מהלכה זו \u0005שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003בעלי חיים נדחין,\u0004 שהרי בהמה זו נדחתה מתחילה, כשהקדיש חציה, ולא היתה ראויה להקרבה. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 שגם \u0003דחוי מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003הוה\u0004 \u0005[הריהו]\u0006 \u0003דחוי,\u0004 ולא רק מה שהיה ראוי מתחילתו ונדחה, שהרי בהמה זו היתה דחויה מתחילה, משעה שהקדיש חציה. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 עוד כי"],["\u0003יש דחוי בדמים\u0004 כלומר, אפילו בדבר שלא נתקדש בקדושת הגוף אלא לדמיו בלבד.","כיון שהוזכרו ענייני דיחויים, מביאים הלכה נוספת: \u0003אמר עולא אמר ר' יוחנן: אכל חלב\u0004 בשוגג \u0003והפריש קרבן\u0004 חטאת לכפר על חטאתו, \u0003ו\u0004אחר כך \u0003נשתמד\u0004 (המיר דתו) המפריש, ואינו ראוי להביא קרבן, \u0003ו\u0004לאחר זמן \u0003חזר בו\u0004 ושב מדרכו, \u0003הואיל ונדחה\u0004 הקרבן מהקרבה בזמן שהיה האיש משומד, שאז לא היה ראוי להקריב — \u0003ידחה\u0004 הקרבן לעולם.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 עוד הלכה בדומה לה, \u0003אמר ר' ירמיה אמר ר' אבהו אמר ר' יוחנן: אכל חלב והפריש קרבן\u0004 עליו, \u0003ונשתטה,\u0004 ואינו יכול להביא קרבן כשאין בו דעת, \u0003וחזר ונשתפה\u0004 (שב לשפיות דעת), \u0003הואיל ונדחה\u0004 הקרבן בזמן שהיה שוטה — \u0003ידחה\u0004 לעולם.","ומעירים: \u0003וצריכי\u0004 \u0005[וצריכות]\u0006 שתי ההלכות להיאמר, הן בנשתמד והן בנשתטה, \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק את \u0005הראשונה]\u0006 בנשתמד, היינו אומרים שהוא דחוי לעולם \u0003משום\u0004 ש\u0003הוא דחי נפשיה\u0004 \u0005[דוחה\u0006 את \u0005עצמו]\u0006 \u0003בידים,\u0004 שהרי נשתמד מדעתו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 שנשתטה, \u0003דממילא אידחי\u0004 \u0005[שמאליו נדחה]\u0006 — \u0003כישן דמי\u0004 \u0005[הוא נחשב]\u0006 והישן בוודאי מתכפר.","\u0003ואי אשמעינן הכא\u0004 \u0005[ואם היה משמיע לנו כאן]\u0006 בשוטה, שהקרבן דחוי, היינו אומרים כי דווקא כאן, \u0003משום\u0004 ש\u0003אין בידו לחזור\u0004 שאינו יכול בעצמו לחזור לשפיותו, הריהו כדחוי לגמרי, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בנשתמד, ש\u0003יש\u0004 \u0003בידו לחזור\u0004 בכל רגע, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייחשב הדבר לדחיה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו הדברים בשני המקרים.","ועוד בענין זה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: אכל חלב והפריש\u0004 עליו \u0003קרבן,\u0004 \u0003ו\u0004לאחר מכן \u0003הורו בית דין שחלב\u0004 זה \u0003מותר,\u0004 ונמצא שאינו מביא קרבן זה, \u0003ו\u0004אחר כך \u0003חזרו בהן, מהו\u0004 דינו של אותו קרבן? \u0003מי הוי\u0004 \u0005[האם הוא]\u0006 נחשב \u0003דחוי או לא הוי\u0004 \u0005[אינו]\u0006 נחשב כ\u0003דחוי?\u0004","\u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003פתח ר' יוחנן\u0004 לדבר על דיני \u0003דחויין, מהא\u0004 \u0005[\u0006מדוגמה \u0005זו]\u0006 \u0003פתח, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בנשתמד ונשתטה, \u0003גברא אידחי\u0004 \u0005[האדם נדחה]\u0006 אבל ה\u0003קרבן לא אידחי\u0004 \u0005[נדחה],\u0006 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003קרבן נמי אידחי\u0004 \u0005[גם כן נדחה]\u0006 כשהורו בית הדין להיתר, וזה בוודאי הוא דיחוי גמור.","שנינו במשנה \u0003אמר שמעון בן עזאי: מקובלני מפי שבעים ושנים זקן כו'.\u0004 ומסבירים: \u0003למה לי למתנא\u0004 \u0005[לו לשנות]\u0006 \u0003\"שבעים ושנים זקן\"\u0004 ולא \"זקנים\" בלבד? משום \u0003דכולהו בחדא שיטתא הוו קיימי\u0004 \u0005[שכולם בשיטה אחת היו עומדים],\u0006 שכולם הסכימו להלכה זו, כאיש אחד.","שנינו במשנה: \u0003לא הוסיף בן עזאי\u0004 על דברי סתם משנה, \u0003אלא העולה,\u0004 שגם היא, כמו פסח וחטאת, אם נשחטה שלא לשמה — פסולה.","\u0003אמר רב הונא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בן עזאי?\u0004 נאמר: \u0003\"עולה הוא אשה ריח ניחח לה'\"\u0004 (ויקרא א, יג), ו\"הוא\" בא להדגיש: \u0003היא\u0004 — \u0003לשמה כשרה, שלא לשמה פסולה.\u0004","ומקשים: \u0003אשם נמי כתיב ביה\u0004 \u0005[גם כן נאמר בו]\u0006 \u0003\"הוא\"\u0004 (ויקרא ז, ה), ובכל זאת אינו פסול שלא לשמו!","ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 \"הוא\" שנאמר — \u0003לאחר הקטרת אימורים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 והרי הקרבן כשר גם אם לא הוקטרו אימוריו בכלל, ובוודאי לא בא הכתוב לפוסלו.","ומקשים: \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 בעולה, \u0003לאחר הקטרת אימורים הוא דכתיב\u0004 \u0005[שנאמר]!\u0006","ומשיבים: \u0003תרי\u0004 \u0005[שני]\u0006 \u0003\"הוא\" כתיבי\u0004 \u0005[כתובים]\u0006 במקרא לגבי עולה, כתוב זה (ויקרא א, יג), והאחר בספר שמות (כט, יח).","ומקשים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אשם נמי תרי\u0004 \u0005[גם כן שני]\u0006 \u0003\"הוא\" כתיבי\u0004 \u0005[כתובים]\u0006 (ויקרא ה, יט. ויקרא ז, ה)!","\u0003אלא,\u0004 לא מן הכתובים למד \u0003בן עזאי,\u0004 אלא \u0003בקל וחומר מייתי לה\u0004 \u0005[מביא,\u0006 לומד \u0005אותה]:\u0006 \u0003ומה חטאת שאינה\u0004 קריבה \u0003כליל\u0004 על המזבח, ובשרה נאכל לכהנים, אם \u0003שחטה שלא לשמה\u0004 — \u0003פסולה, עולה שהיא כליל\u0004 — \u0003לא כל שכן\u0004 שתיפסל שלא לשמה?","ומקשים: הרי אפשר לדחות, \u0003מה לחטאת\u0004 שיש בה חומרה מיוחדת, \u0003שכן מכפרת\u0004 ולכן פסולה שלא לשמה, תאמר בעולה שאינה באה לשם כפרה!","ודוחים: \u0003פסח יוכיח\u0004 שאינו מכפר ופסול לשמו.","ושואלים: \u0003מה לפסח, שכן\u0004 הוא קרבן ש\u0003זמנו קבוע,\u0004 מה שאין כן עולה!","ומשיבים: \u0003חטאת תוכיח\u0004 שאין זמנה קבוע. \u0003וחזר הדין\u0004 מכאן לשם, \u0003לא ראי\u0004 (הרי) \u0003זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן שהן קדשים ו\u0004אם \u0003שחטן שלא לשמן\u0004 — \u0003פסול, אף אני אביא עולה שהיא קדשים ושחטה שלא לשמה\u0004 — \u0003פסולה.\u0004","ומקשים: \u0003מה להצד השוה שבהן שיש בהן צד כרת,\u0004 פסח — אם לא עשה אותו, וחטאת — בגלל עבירה שיש בה כרת היא באה!","ומשיבים: \u0003בן עזאי\u0004"],["\u0003צד כרת לא פריך\u0004 \u0005[אינו פורך],\u0006 משום שאין זה שווה ממש בשניהם, אלא רק שיש לשניהם קשר לכרת.","ושואלים: אם אינו פורך משום צד כרת, \u0003אשם נמי לייתי\u0004 \u0005[גם כן יביא,\u0006 יוסיף\u0005]\u0006 לנפסלים שלא לשמם, שהרי גם הוא קדשים ונשחט שלא לשמו!","ומשיבים: \u0003אשם, פריך\u0004 \u0005[פורך]\u0006 בנימוק אחר: \u0003מה להצד השוה שבהן,\u0004 בפסח וחטאת, \u0003שכן ישנן בצבור כביחיד\u0004 מה שאין כן באשם, שלעולם אינו בא בציבור.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003צד כרת נמי פריך\u0004 \u0005[גם כן מקשה]\u0006 ועל ידו אכן מתבטל הקל וחומר, \u0003ובן עזאי\u0004 שסבור שעולה שנשחטה שלא לשמה פסולה — \u0003גמרא גמיר לה\u0004 \u0005[במסורת למד אותה],\u0006 ולא מכוח דרשת הכתוב. \u0003והא דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003רב הונא קל וחומר,\u0004 לא היה זה המקור לדברי בן עזאי, \u0003ו\u0004\u0003לא אמרה\u0004 רב הונא \u0003אלא לחדד בה\u0004 את \u0003תלמידיו,\u0004 שיעיינו בדבריו, וימצאו להם פירכה.","\u0003הפסח והחטאת ששחטן שלא לשמן,\u0004 או \u0003קבל\u0004 את הדם בכלי, או \u0003הלך\u0004 (הוליך את הדם למזבח), או \u0003זרק\u0004 את הדם על המזבח \u0003שלא לשמן, או\u0004 שעשה אחת מעבודות אלה \u0003לשמן ושלא לשמן,\u0004 \u0003או שלא לשמן ולשמן\u0004 — כל אלה \u0003פסולים.\u0004","\u0003כיצד לשמן ו\u0004אחר כך \u0003שלא לשמן?\u0004 כגון ששחט \u0003לשם פסח ולשם שלמים,\u0004 כיצד \u0003שלא לשמן ולשמן?\u0004 כגון ששחט \u0003לשם שלמים ולשם פסח.\u0004","\u0003שהזבח נפסל בארבעה דברים\u0004 (ארבע עבודות) במחשבה פסולה: \u0003בשחיטה, ובקבול, ובהילוך, ובזריקה.\u0004","\u0003ר' שמעון מכשיר בהילוך, שהיה אומר: אי אפשר\u0004 להקריב קרבן \u0003שלא בשחיטה ושלא בקבלה ושלא בזריקה, אבל אפשר בלא הילוך,\u0004 כיצד? אם \u0003שוחט בצד המזבח וזורק.\u0004","\u0003ר' אליעזר אומר: המהלך במקום שהוא צריך להלך\u0004 — \u0003מחשבה\u0004 בזמן ההילוך \u0003פוסלת,\u0004 אם הילך \u0003במקום שאינו צריך להלך\u0004 — \u0003אין מחשבה פוסלת.\u0004","ושואלים: \u0003וקבלה מי פסלה\u0004 \u0005[האם\u0006 היא \u0005פוסלת]\u0006 במחשבה?","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"והקריבו\u0004 בני אהרן הכהנים את הדם\" (ויקרא א, ה) — \u0003זו קבלת הדם.\u0004 \u0003אתה אומר קבלת הדם, או אינו אלא זריקה? כשהוא אומר\u0004 מיד אחר כך: \u0003\"וזרקו\u0004 את הדם על המזבח סביב\" (ויקרא א, ה) — \u0003הרי זריקה אמור, הא מה אני מקיים\u0004 במילה \u0003\"והקריבו\"? זו קבלת הדם.\u0004 ומה שנאמר שם \u0003\"בני אהרן הכהנים\"\u0004 בא ללמד \u0003שתהא\u0004 הקבלה \u0003בכהן כשר ו\u0004כשהוא לבוש \u0003בכלי שרת.\u0004","\u0003אמר ר' עקיבא: מנין לקבלה שלא תהא [אלא] בכהן\u0004 \u0003כשר ובכלי שרת? נאמר כאן: \"בני אהרן\", ונאמר להלן: \"אלה שמות בני אהרן הכהנים המשחים\u0004 אשר מלא ידם לכהן\" (במדבר ג, ג), \u0003מה להלן\u0004 \"בני אהרן הכהנים\" הוא \u0003בכהן כשר\u0004 (שהרי מוזכר שהיו אלה אלעזר ואיתמר) \u0003ובכלי שרת\u0004 (שנאמר \"אשר מלא ידם לכהן\" ומבואר במקום אחר שהוא בלבישת בגדי הכהונה. שמות כט, ל), \u0003אף כאן בכהן כשר ובכלי שרת.\u0004","\u0003אמר ר' טרפון\u0004 בלשון כעין שבועה: \u0003אקפח\u0004 (אאבד) \u0003את בניי, אם לא שמעתי\u0004 מרבותי \u0003להבחין\u0004 שיש \u0003הפרש בין קבלה לזריקה,\u0004 אבל איני זוכר \u0003ואין לי לפרש\u0004 מה ההבדל ביניהם.","\u0003אמר ר' עקיבא אני אפרש: קבלה לא עשה בה מחשבה כמעשה\u0004 כלומר, אין המחשבה פוסלת בה, \u0003זריקה עשה בה מחשבה כמעשה.\u0004 ועוד, דם ש\u0003קבלו בחוץ\u0004 (מחוץ למקדש) — \u0003אינו חייב כרת,\u0004 אבל אם \u0003זרקו בחוץ\u0004 — \u0003ענוש כרת.\u0004 וכן אם \u0003קבלוהו\u0004 אנשים \u0003פסולין\u0004 לעבודה — \u0003אין חייבין עליו,\u0004 ואם \u0003זרקוהו פסולין\u0004 — \u0003חייבין עליו.\u0004","\u0003אמר לו ר' טרפון\u0004 בהתפעלות ובלשון שבועה: \u0003העבודה,\u0004 נשבע אני בעבודת המקדש (את) [אם] \u0003הטית ימין ושמאל\u0004 ממה ששמעתי, \u0003אני שמעתי\u0004 מרבותי \u0003ואין לי\u0004 יכולת \u0003לפרש,\u0004 ואילו \u0003אתה דורש\u0004 מדעתך \u0003ומסכים לשמועה\u0004 ששמעתי. \u0003בלשון הזה אמר לו\u0004 ר' \u0003טרפון:\u0004 \u0003עקיבא, כל הפורש ממך כפורש מחייו!\u0004 על כל פנים עולה מדברי ר' עקיבא שבקבלה אין מחשבה פוסלת (\"לא עשה בה מחשבה כמעשה\"), ובניגוד למשנתנו!","\u0003אמר רבא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאין מחשבה פוסלת בקבלה — \u0003במחשבת פיגול,\u0004 שמקבל את הדם על מנת להקטיר את האימורים או לאכול את הבשר לאחר זמנו. \u0003כאן\u0004 שפוסלת — \u0003במחשבת שלא לשמה.\u0004","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מן הלשון \u0005שכך הוא,\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנתנו: \u0003\"שהזבח נפסל\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"מתפגל\",\u0004 הרי שמדובר רק בפסול שלא לשמה, ולא בפיגול. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומקשים על דברי רבא: \u0003ו\u0004האם \u0003מחשבת פיגול לא פסלה\u0004 \u0005[פוסלת]\u0006 \u0003בקבלה?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003יכול לא תהא מחשבה\u0004 של חוץ לזמנו \u0003מועלת\u0004 כלומר, משפיעה וגורמת לדין פיגול, \u0003אלא בזריקה בלבד, מנין לרבות שחיטה וקבלה? תלמוד לומר: \"ואם האכל יאכל מבשר זבח שלמיו\u0004 ביום השלישי \u0003(פיגול הוא) לא ירצה\"\u0004 (ויקרא ז, יח), ומפרשים (ראה להלן זבחים כט,א) שמדובר בפסוק זה במחשב בזמן העבודה לאוכלו שלא בזמנו, והבטוי \"האכל יאכל\" בא ללמדנו כי \u0003בדברים המביאין לידי אכילה הכתוב מדבר,\u0004 כלומר, באותן עבודות שמתירות את הזבח להאכל.","\u0003יכול שאני מרבה אף שפיכת שיריים\u0004 של הדם, שנשארו בכלי לאחר הזריקה, שצריך לשפוך אותם על יסוד המזבח, \u0003או הקטרת אימורין?\u0004","\u0003תלמוד לומר: \"ביום השלישי לא ירצה המקריב אותו לא יחשב\"\u0004 (ויקרא ז, יח), \u0003זריקה\u0004 (\"המקריב אותו\") \u0003בכלל\u0004 כל העבודות \u0003היתה, ולמה יצתה? להקיש אליה, לומר לך: מה זריקה מיוחדת שהיא עבודה\u0004 \u0003(ומכפרת) ומעכבת כפרה, אף כל\u0004 דבר שהוא \u0003עבודה ומעכבת כפרה\u0004 יש בו דין פיגול, \u0003יצאו שפיכת שיריים והקטרת אימורין שאין מעכבין את הכפרה,\u0004 ולכן אין בהם דין פיגול. וכיון שאף קבלה היא עבודה הכרחית, נמצא שאף בה יש מחשבת פיגול, שלא כדברי רבא!"],["\u0003אלא לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שאין מחשבת פיגול פוסלת בקבלה — הרי זה במקרה \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"הריני [שוחט] על מנת לקבל דמה למחר\",\u0004 שאין קבלת הדם בכלל אכילת מזבח, שגורמת לפיגול. \u0003הא\u0004 \u0005[זה]\u0006 שמחשבת פיגול פוסלת בקבלה — במקרה \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"הריני מקבל דמה על מנת לשפוך שירים\u0004 של הדם על יסוד המזבח \u0003למחר\",\u0004 שקבלת הדם היא עבודה שמעכבת את הכפרה, ואם עשאה על מנת שיאכל המזבח (בשפיכת השיריים) חוץ לזמנו — הרי זה פיגול. ושבים לדון בברייתא שהבאנו לעיל.","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא:\u0004 \u0003ו\u0004האם \u0003שפיכת שירים והקטרת אימורין לא פסלה בהו\u0004 \u0005[אין פוסלת בהם]\u0006 \u0003מחשבה?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו]:\u0006 \u0003יכול לא תהא מחשבה מועלת\u0004 לפגל \u0003אלא באכילת בשר, מנין לרבות\u0004 גם \u0003שפיכת שירים והקטרת אימורים? תלמוד לומר: \"ואם האכל יאכל\"\u0004 (ויקרא ז, יח), \u0003בשתי אכילות הכתוב מדבר, אחת אכילת אדם\u0004 שהבשר נאכל לכהנים או לבעלים, \u0003ואחת אכילת מזבח\u0004 שהדם או האימורים מגיעים למזבח!","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמחשבה מועילה — \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"הריני זורק על מנת לשפוך שירים למחר\",\u0004 שנמצא חושב בשעת עבודה שמעכבת את הכפרה על אכילת מזבח שלא בזמנה. \u0003הא\u0004 \u0005[זה]\u0006 שאין מחשבה מועילה — \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"הריני שופך שירים על מנת להקטיר אימורין למחר\",\u0004 ואינו מפגל, משום שאף שחישב על אכילת מזבח — חישב בשעת עבודה שאינה מעכבת את הכפרה.","מתוך שעסקנו בעבודות שונות מה דינן לענין פיגול, מביאים מה ש\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: שמעתי שטבילת אצבע מפגלת בחטאת פנימית,\u0004 שאם כשטובל הכהן אצבעו בדם שבמזרק כדי להזות על הפרוכת חישב להקטיר את אימורי החטאת למחר — הרי זה פיגול.","\u0003שמעה אילפא\u0004 את המימרה הזו ו\u0003אמרה קמיה\u0004 \u0005[לפני]\u0006 החכם \u0003רב פדא, אמר\u0004 רב פדא: \u0003כלום\u0004 לא \u0003למדנו פיגול אלא משלמים,\u0004 שהרי עיקר דין הפיגול נכתב בתורה בקרבן שלמים (ויקרא ז, יח), ומשם למדנו לשאר הקרבנות. ומכיוון שכך\u0003,\u0004 \u0003מה\u0004 \u0003שלמים אין טבילת אצבע מפגלת בהן\u0004 (שאין בהם דין טבילת אצבע כלל), \u0003אף חטאת אין טבילת אצבע מפגלת בהן!\u0004","על כך משיבים: \u0003וכי הכל\u0004 את כל פרטי הדינים הקשורים בפיגול \u0003משלמים למדו?\u0004 שאם היה כך, היינו צריכים לומר: \u0003אי\u0004 \u0005[אם\u0006 כך\u0005]\u0006 \u0003מה שלמים,\u0004 מחשבה שחשב עליהם \u0003שלא לשמן אין מוציא\u0004 במחשבה זו את השלמים \u0003מידי פיגול,\u0004 \u0003אף\u0004 ב\u0003חטאת\u0004 יהא הדין כן, שאם חשב בה \u0003שלא לשמה\u0004 \u0003אין מוציא מידי פיגול.\u0004 והרי אנו יודעים שאם שחט במחשבה זו בחטאת שוב אין בה דין פיגול!","\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 כדי להסביר זאת? הלכה זו \u0003מרבויא דקראי קאתיא\u0004 \u0005[מריבוי המקראות היא באה],\u0006 \u0003[הכא נמי מרבויא דקרא קאתי\u0004 \u0005[כאן גם כן\u0006 לענין טבילת אצבע בחטאת הפנימית, \u0003נאמר כי\u0004 \u0005מריבוי המקראות בא].\u0006","כיוצא בזה \u0003אמר ר' יהושע בן לוי: בעליה זו\u0004 שאנו יושבים בה עכשיו \u0003שמעתי, שטבילת אצבע מפגלת. תהי בה\u0004 \u0005[תוהה\u0006 היה \u0005על כך]\u0006 \u0003ר' שמעון בן לקיש: כלום\u0004 לא \u0003למדו\u0004 דין \u0003פיגול אלא משלמים?\u0004 ואם כן, \u0003מה שלמים אין טבילת אצבע מפגלת בהן, אף חטאת אין טבילת אצבע מפגלת בהן!\u0004","ותמהים: \u0003וכי הכל משלמים למדו? אי מה שלמים שלא לשמן אין מוציא מידי פיגול, אף חטאת שלא לשמה אין מוציא מידי פיגול!\u0004","\u0003אמר ר' יוסי בר' חנינא: אין\u0004 \u0005[כן],\u0006 \u0003הכל משלמים למדו,\u0004 גם דין זה שאין החטאת מתפגלת אם חשב בה שלא לשמה, גם כן למדים מדין השלמים, ובאופן זה: \u0003הואיל וחוץ למקומו פוסל בשלמים\u0004 כגון אם שחט (או קיבל וכו') על מנת לאוכלו חוץ לירושלים, \u0003ו\u0004מחשבת \u0003שלא לשמו פוסל בחטאת,\u0004 אנו יכולים ללמוד מכאן: \u0003מה חוץ למקומו הפוסל בשלמים\u0004 — \u0003מוציא מידי פיגול,\u0004 שאין עוד דין פיגול בקרבן שחשב בו מחשבת חוץ למקומו, \u0003אף שלא לשמו הפוסל בחטאת\u0004 — \u0003מוציאה מידי פיגול.\u0004 אבל אין הדין כן לגבי טבילת אצבע, שאינה מצויה כלל בשלמים.","\u0003אמר ר' ירמיה:\u0004 הוכחה זו \u0003מצדה תברא\u0004 \u0005[היא שבורה],\u0006 שהרי אותה עצמה אפשר לפרוך בפשטות: \u0003מה לחוץ למקומו הפוסל בשלמים\u0004 מוציא מידי פיגול, \u0003שכן\u0004 דין זה \u0003נוהג בכל הזבחים, תאמר ב\u0004פסול \u0003שלא לשמו שאינו נוהג אלא בפסח וחטאת בלבד\u0004 שיוציא מידי פיגול?","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]?\u0006 שהלימוד משלמים אינו מתבסס על השוואת פרטים מדוייקת, אלא על השוואה עקרונית: כמו בשלמים, \u0003כל\u0004 \u0003דבר הפוסל בהן\u0004 (כמו מחשבה חוץ למקומו) \u0003מוציאם מידי פיגול,\u0004 וכן כל \u0003דבר המעכב בהן\u0004 (כל עבודה שמעכבת את הכפרה) \u0003מביאן לידי פיגול,\u0004","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בחטאת פנימית נאמר: \u0003דבר הפוסל בה מוציא מידי פיגול,\u0004 והוא מחשבת שלא לשמה. וכיוצא בזה לענייננו, \u0003דבר המעכב בה מביאה לידי פיגול,\u0004 והואיל וטבילת אצבע מעכבת בה — הריהי עושה פיגול.","\u0003אמר רב מרי\u0004 לסייע למה שנאמר שטבילת אצבע מפגלת: \u0003אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 בדיני מנחות, שדין הפיגול שבהם גם הוא נלמד משלמים: \u0003זה הכלל: כל הקומץ\u0004 מן המנחה, \u0003ו\u0004ה\u0003נותן\u0004 את הקומץ \u0003בכלי, והמוליך\u0004 את הקומץ למזבח, \u0003והמקטיר\u0004 את הקומץ על המזבח, במחשבת חוץ לזמנו — עושה את המנחה פיגול.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003קומץ היינו\u0004 \u0005[הרי זה]\u0006 מקביל ל\u0003שוחט\u0004 בשלמים, שמפריש מן הקרבן את החלק המתיר, בזבח — הדם, ובמנחה — הקומץ, \u0003מוליך\u0004 את הקומץ למזבח \u0003היינו\u0004 \u0005[הרי זה]\u0006 כ\u0003מוליך\u0004 הדם, \u0003מקטיר\u0004 את הקומץ על המזבח \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 כ\u0003זורק\u0004 את הדם, \u0003אלא נותן בכלי מאי ניהו\u0004 \u0005[מה הוא]?\u0006 למה הוא דומה?","\u0003אילימא דדמי\u0004 \u0005[אם תאמר ש\u0006הוא \u0005דומה]\u0006 \u0003לקבלה\u0004 שהכנסת הקומץ לכלי הריהי כמו קבלת הדם בכלי — \u0003מי דמי\u0004 \u0005[האם\u0006 הוא \u0005דומה]?\u0006 \u0003התם ממילא\u0004 \u0005[שם מעצמו\u0006 הוא \u0003נעשה\u0004\u0005]\u0006 שהדם נוזל מעצמו לתוך הכלי, \u0003הכא איהו קא שקיל ורמי\u0004 \u0005[כאן\u0006 במנחה \u0005הוא נוטל\u0006 קומץ \u0005ומכניס\u0006 לכלי\u0005]!\u0006","\u0003אלא\u0004 צריך לומר שהטעם אינו בגלל השוואה זו של פרטי העבודה, אלא \u0003כיון\u0004 ש\u0003לא סגי\u0004 \u0005[די]\u0006 שאי אפשר ב\u0003לא יהיב\u0004 \u0005[שיתן],\u0006 שהנתינה בכלי הכרחית לעבודה, \u0003על כרחיה\u0004 \u0005[על כרחו]\u0006 צריך לומר ש\u0003עבודה חשובה היא,\u0004 ולכן היא מפגלת. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בטבילת אצבע של חטאת פנימית, למרות שאין היא עבודה המצויה בשלמים, \u0003כיון\u0004 ש\u0003לא סגי\u0004 \u0005[די]\u0006 ש\u0003לא עביד לה\u0004 \u0005[יעשה אותה],\u0006 \u0003על כרחיה\u0004 \u0005[על כרחו]\u0006 \u0003היינו\u0004 \u0005[הרי זו]\u0006 \u0003הולכה\u0004 שמפגלים בה, גם אם אין כיוצא בה בשלמים!","את ההוכחה הזו דוחים: \u0003לא, לעולם\u0004 צריך לומר לענין מנחה \u0003דדמי\u0004 \u0005[ש\u0006נתינה בכלי \u0005דומה]\u0006 \u0003לקבלה,\u0004 עבודת מנחה מול עבודת זבח, \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 כנגד זה: \u0003הכא ממילא\u0004 \u0005[כאן\u0006 הדם נשפך \u0005מעצמו\u0006 לכלי\u0005],\u0006 \u0003התם איהו קא שקיל ויהיב\u0004 \u0005[שם,\u0006 בקומץ, \u0005הוא לוקח ונותן],\u0006 \u0003כיון דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 \u0003מתן כלי הוא,\u0004 שהחלק העולה למזבח נכנס לתוך כלי, \u0003מה לי\u0004 אם נעשה \u0003ממילא\u0004 \u0005[מעצמו],\u0006 \u0003מה לי קא שקיל ויהיב\u0004 \u0005[אם נוטל\u0006 בעצמו \u0005ונותן].\u0006 ואין להוכיח מכאן לגבי טבילת אצבע, שאין לה דמיון בפרטי קרבן השלמים.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם נאמר\u0006 שדין טבילת אצבע, האם היא נחשבת הולכה, שנוי במחלוקת \u0005תנאים],\u0006 \u0003דתני חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003טבילת אצבע מפגלת בחטאת, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא מפגלת\u0004 (אם חשב בזמן טבילה להקטיר אימורים למחר) \u0003ולא מתפגלת\u0004 (אם שחט כדי לטבול אצבע למחר), \u0003מאי לאו תנאי\u0004 \u0005[האם לא\u0006 מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין טבילת אצבע, האם היא בכלל הולכה?","ודוחים: \u0003לא,\u0004 הכל מודים שטבילת אצבע בחטאת הפנימית הולכה היא, אלא \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' שמעון,\u0004 הסבור במשנה לעיל (עמוד א) שהילוך אינו מפגל כלל.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מפרשים את הברייתא כשיטת \u0003ר' שמעון, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע מדובר דווקא לגבי\u0005]\u0006 \u0003טבילת אצבע? האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006"]]};
